int getMaximumGenerated(int n)
  {
    n++;
    if (n <= 2)
      return n - 1;
    vector<int> arr(n, -1);
    arr[0] = 0;
    arr[1] = 1;
    int ans = INT_MIN;

    for (int i = 2; i < n; ++i)
    {
      if (i % 2 == 0)
      {
        arr[i] = arr[i / 2];
      }
      else
        arr[i] = arr[(i - 1) / 2] + arr[(i + 1) / 2];
      ans = max(ans, arr[i]);
    }

    return ans;
  }

