    }

using namespace std;
int countSubstrings(string str,int K) {
    int N=str.size();
    int answer=0;
    unordered_map<char,int>map;
    for(int i=0;i<K;i ++) {
        map[str[i]]++;
    }
    if(map.size()==K)answer ++;
    for(int i=K;i<N;i ++) {
        map[str[i]] ++;
        map[str[i-K]] --;
        if(map[str[i-K]]==0) {
            map.erase(str[i-K]) ;
        }
        if(map.size()==K) {
            answer++;
        }
    }
    return answer;
}

