using namespace std;
int minimumMoves(string S,int K) {
    int N=S.length();
    int ops=0;
    int last_idx=-1;
    for(int i=0;i<K;i ++) {
        if(S[i]== '1')last_idx=i ;
    }
    if(last_idx==-1) {
        ++ops;
        S[K-1]= '1';
        last_idx=K-1 ;
    }
    for(int i=1;i<N-K+1;i ++) {
        if(last_idx<i)last_idx=-1;
        if(S[i+K-1]== '1')last_idx=i+K-1;
        if(last_idx==-1) {
            ++ops;
            S[i+K-1]= '1';
            last_idx=i+K-1 ;
        }
    }
    return ops;
}

int maxDotProduct(vector<int>& nums1, vector<int>& nums2) {

        int n1 = nums1.size(), n2 = nums2.size();
        vector<int> dp(n2 + 1, -1e9);

        for(int i = 0; i < n1; i ++){
            vector<int> tdp(n2 + 1, -1e9);
            for(int j = 0; j < n2; j ++){
                tdp[j + 1] = nums1[i] * nums2[j];
                tdp[j + 1] = max(tdp[j + 1], nums1[i] * nums2[j] + dp[j]);
                tdp[j + 1] = max(tdp[j + 1], dp[j]);
                tdp[j + 1] = max(tdp[j + 1], dp[j + 1]);
                tdp[j + 1] = max(tdp[j + 1], tdp[j]);
            }
            dp = tdp;
        }
        return dp[n2];
    }

