bool isCycleDFS(unordered_map<int, vector<int>> &adj, int u, vector<bool>& visited, vector<bool>& inRecursion) {
        visited[u] = true;
        inRecursion[u] = true;


        for(int &v : adj[u]) {
            //if not visited, then we check for cycle in DFS
            if(visited[v] == false && isCycleDFS(adj, v, visited, inRecursion))
                return true;
            else if(inRecursion[v] == true)
                return true;
        }

        inRecursion[u] = false;
        return false;

    }

int numTrees(int n, vector<int>& dp){

        if(n <= 1)
            return 1;

        if(dp[n] != -1)
            return dp[n];

        int res = 0;
        for(int i = 1; i <= n; i ++)
            res += numTrees(i - 1, dp) * numTrees(n - i, dp);
        return dp[n] = res;
    }

