using namespace std;
int MinOfCubedDP(int k) {
    int*DP=new int[k+1], j=1,t=1;
    DP[0]= 0;
    for(int i=1;i<=k;i ++) {
        DP[i]= INT_MAX;
        while(j<=i) {
            if(j==i)DP[i]= 1;
            else if(DP[i]> DP[i-j]) DP[i]= DP[i-j]+ 1;
            t ++;
            j=t*t*t ;
        }
        t=j=1 ;
    }
    return DP[k];
}

