string shiftingLetters(string s, vector<int>& shifts) {
        int n = shifts.size();

        //mod 26 is done here because shifting any character 26 times
        //is as good as not shifting it at all
        for(int i = n-2; i>=0; i--)
            shifts[i] = (shifts[i] + shifts[i+1])%26;

        for(int i = 0; i < n; i++) {

            int x  = s[i] - 'a';  //to bring into range of 0-26
            x     += shifts[i];   //Now, shift
            x     %= 26;         //wrap it back to 0-26
            x     += 'a';        //Bring back to range of 'a'-'z'

            s[i]   = (char)x;

        }
        return s;
    }

int minDistance(string word1, string word2) {

        vector<vector<int>> dp(2, vector<int>(word2.size() + 1, 0));
        for(int i = 1 ; i <= word1.size() ; i ++)
            for(int j = 1 ; j <= word2.size() ; j ++){
                dp[i%2][j] = max(dp[(i-1)%2][j], dp[i%2][j-1]);
                if(word1[i-1] == word2[j-1])
                    dp[i%2][j] = max(dp[i%2][j], 1 + dp[(i-1)%2][j-1]);
            }
        return word1.size() + word2.size() - 2 * dp[word1.size()%2][word2.size()];
    }

void morrisInorderTraversal(Node *root, const function<void(char)>& cb) {
        auto curr = root;
        while (curr) {
            if (!curr->left) {
                cb(curr->val);
                curr = curr->right;
            } else {
                auto node = curr->left;
                while (node->right && node->right != curr) {
                    node = node->right;
                }
                if (!node->right) {
                    node->right = curr;
                    curr = curr->left;
                } else {
                    cb(curr->val);
                    node->right = nullptr;
                    curr = curr->right;
                }
            }
        }
    }

