    sort(sortedseq.begin(),sortedseq.end());
    for(int i=0;i<=n;i ++) {
        for(int j=0;j<=n;j ++) {
            if(i==0 j==0)L[i ][j]= 0;
            else if(seq[i-1]== sortedseq[j-1]) L[i ][j]= L[i-1 ][j-1]+ 1;
