int maxScore(string s,vector<int>a) {
    if(dp.find(s)!= dp.end())return dp[s];
    int n=s.size();
    if(n==0)return 0;
    if(n==1)return a[0];
    int head=0;
    int mx=-1;
    while(head<n) {
        int tail=head;
        while(tail<n) {
            if(s[tail]!= s[head]) {
                head=tail;
                break ;
            }
            string sub=s.substr(head,tail+1);
            mx=max(mx,a[sub.size()-1]+ maxScore(s.substr(0,head)+ s.substr(tail+1,s.size()), a));
            tail+=1 ;
        }
        if(tail==n)break ;
    }
    dp[s]= mx;
    return mx;
}

