Node *build(int in[], int pre[], int &pi, int n, int si, int ei)
{
  if (si > ei)
    return NULL;
  int e = pre[pi++];

  int index = -1;
  for (int i = si; i <= ei; ++i)
  {
    if (in[i] == e)
    {
      index = i;
      break;
    }
  }

  Node *root = new Node(e);
  root->left = build(in, pre, pi, n, si, index - 1);
  root->right = build(in, pre, pi, n, index + 1, ei);
  return root;
}

int numWays(int n, vector<vector<int>>& relation, int k) {

        vector<set<int>> g(n);
        for(const vector<int>& arc: relation)
            g[arc[0]].insert(arc[1]);

        vector<vector<int>> dp(n, vector<int>(k + 1, 0));
        for(int i = 0; i < n; i ++)
            if(g[i].count(n - 1)) dp[i][1] = 1;

        for(int j = 2; j <= k; j ++)
            for(int i = 0; i < n; i ++)
                for(int next: g[i])
                    dp[i][j] += dp[next][j - 1];
        return dp[0][k];
    }

void dfs(vector<int>& freq, int index, string& cur, vector<string>& res){

        if(index >= cur.size() / 2){
            res.push_back(cur);
            return;
        }

        for(char ch = 0; ch < freq.size(); ch ++)
            if(freq[ch]){
                cur[index] = cur[cur.size() - index - 1] = ch;
                freq[ch] -= 2;
                dfs(freq, index + 1, cur, res);
                freq[ch] += 2;
            }
    }

