bool dfs(const vector<vector<int>>& g, int u, int p,
             vector<bool>& visited, vector<int>& pre, vector<int>& cycle){

        visited[u] = true;
        pre[u] = p;
        for(int v: g[u]){
            if(v == p) continue;
            if(!visited[v]){
                if(dfs(g, v, u, visited, pre, cycle)) return true;
            }
            else{
                cycle.push_back(v);
                int cur = u;
                while(cur != v){
                    cycle.push_back(cur);
                    cur = pre[cur];
                }
                return true;
            }
        }
