    int right=0,left=0;
    int coun=0,max_length=INT_MIN;
    s=s+'1';
    for(int i=0;i<=n;i ++) {
        if(s[i]== ' o ')coun ++;
        else {
            if(coun>max_length) {
                right=0;
                left=0;
                if(s[i]== ' x ')right=1;
                if(((i-coun)> 0)&&(s[i-coun-1]== ' x ')) left=1;
                coun=ceil(( double)coun /(right+left));
