void rotate(vector<int>& nums, int k) {

        queue<int> q;
        int kk = k;
        for(int i = (int)nums.size() - 1; i >= 0 && kk --; i --)
            q.push(nums[i]);
        for(int i = q.size() ; i < kk ; i ++)
            q.push(q.front()), q.pop();

        for(int i = (int)nums.size() - k - 1; i >= 0; i --)
            nums[i + k] = nums[i];

        while(!q.empty()){
            k --;
            if(k < 0)
                k += nums.size();
            k %= nums.size();
            nums[k] = q.front();
            q.pop();
        }
        return;
    }

