        dp[0] = 0;
        for(int i = 1; i < n; i ++)
            for(int j = i - 1; j >= 0; j --)
                if(dp[j] != INT_MAX && j + nums[j] >= i)
                    dp[i] = min(dp[i], 1 + dp[j]);
