int maxScore(vector<int> &cards, int k)
  {
    int curr = 0, ans = 0, total = 0;
    k = cards.size() - k;
    for (auto &i : cards)
      total += i;

    for (int i = 0; i < cards.size(); ++i)
    {
      if (i < k)
      {
        curr += cards[i];
        if (i == k - 1)
          ans = max(ans, total - curr);
      }
      else
      {
        curr += cards[i] - cards[i - k];
        ans = max(ans, total - curr);
      }
    }
    return ans;
  }

