long smallestCommon(long a,long b,long c,long d) {
    if(a==c)return a;
    if(a>c) {
        swap(a,c);
        swap(b,d);
    }
    long first_term_diff =(c-a);
    long possible_y;
    for(possible_y=0;possible_y<b;possible_y ++) {
        if(( first_term_diff%b+possible_y*d)% b==0) {
