int findKMin(vector<int>arr,int n,int k) {
    deque<int>Qi(k);
    int i;
    for(i=0;i<k;++ i) {
        while((!Qi.empty())&& arr[i]>= arr[Qi.back()]) Qi.push_back(i);
    }
    int minDiff=INT_MAX;
    for(; i<n;++ i) {
        minDiff=min(minDiff,arr[Qi.front()]);
        while((!Qi.empty())&& Qi.front()<=i-k)Qi.pop_front();
        while((!Qi.empty())&& arr[i]>= arr[Qi.back()]) Qi.pop_back();
        Qi.push_back(i);
    }
    minDiff=min(minDiff,arr[Qi.front()]);
    return minDiff ;
}
