int minScoreTriangulation(vector<int>& A) {

        int n = A.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));

        for(int i = 0; i + 2 < n; i ++)
            dp[i][i + 2] = A[i] * A[i + 1] * A[i + 2];

        for(int len = 4; len <= n; len ++)
            for(int i = 0; i + len - 1 < n; i ++){

                int j = i + len - 1;
                dp[i][j] = INT_MAX;
                for(int k = i + 1; k < j; k ++)
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j] + A[i] * A[j] * A[k]);
            }
        return dp[0][n - 1];
    }

