vector<int> constructArray(int n, int k) {

        vector<int> arr(n);

        int l = 1, r = n;
        for(int i = 0; i < k; i += 2){
            arr[i] = l ++;
            if(i + 1 == k){
                for(int j = k; j < n; j ++) arr[j] = l ++;
                break;
            }

            arr[i + 1] = r --;
            if(i + 2 == k){
                for(int j = k; j < n; j ++) arr[j] = r --;
                break;
            }
        }

        return arr;
    }

