char slowestKey(vector<int>& releaseTimes, string keysPressed) {
        int prev = 0;
        int duration = 0;
        char ans = '\0';

        for(int i = 0; i < releaseTimes.size(); ++i) {

            int pressTime = releaseTimes[i] - prev;
            if(pressTime > duration) {
                duration = pressTime;
                ans = keysPressed[i];
            }

            else if(pressTime == duration && ans < keysPressed[i]) {
                ans = keysPressed[i];
            }

            prev = releaseTimes[i];
        }

        return ans;
    }

