bool find3Numbers(int arr[], int N, int X)
{
  sort(arr, arr + N);
  for (int i = 0; i < N; ++i)
  {
    int j = i + 1, k = N - 1;
    while (j < k)
    {
      if (arr[i] + arr[j] + arr[k] == X)
        return true;
      else if (arr[i] + arr[j] + arr[k] > X)
        k--;
      else
        j++;
    }
  }
  return false;
}

void bfs(int n, const vector<vector<int>>& g, int s, vector<int>& dis){

        vector<bool> visited(n, false);
        queue<int> q;
        q.push(s);
        visited[s] = true;
        dis[s] = 0;
        while(!q.empty()){
            int u = q.front(); q.pop();
            for(int v: g[u])
                if(!visited[v]){
                    q.push(v);
                    visited[v] = true;
                    dis[v] = dis[u] + 1;
                }
        }
    }

