bool facet_has_edge(const Facet& f, const Vh v0, const Vh v1)
{
  std::array<std::array<int, 2>, 3> edges = {{ {{1,2}}, {{2,3}}, {{3,1}} }};

  for (int i = 0; i < 3; ++i)
  {
    const std::array<int, 2>& ei = edges[i];
    if ( f.first->vertex((f.second + ei[0]) % 4) == v0
      && f.first->vertex((f.second + ei[1]) % 4) == v1)
      return true;
    if ( f.first->vertex((f.second + ei[0]) % 4) == v1
      && f.first->vertex((f.second + ei[1]) % 4) == v0)
      return true;
  }
  return false;
}

int twoCitySchedCost(vector<vector<int>>& costs) {

        vector<vector<int>> A, B;

        int res = 0;
        for(const vector<int>& cost: costs)
            if(cost[0] < cost[1])
                res += cost[0], A.push_back(cost);
            else
                res += cost[1], B.push_back(cost);

        vector<vector<int>>& t = A.size() < B.size() ? B : A;

        sort(t.begin(), t.end(), [](const vector<int>& v1, const vector<int>& v2){
           return abs(v1[0] - v1[1]) > abs(v2[0] - v2[1]);
        });

        while(t.size() > costs.size() / 2){
            res += abs(t.back()[0] - t.back()[1]);
            t.pop_back();
        }
