vector<long long> maximumEvenSplit(long long finalSum) {

        if(finalSum % 2ll) return {};

        vector<long long> res;
        long long cur = 2;
        while(finalSum >= cur){
            res.push_back(cur);
            finalSum -= cur;
            cur += 2;
        }

        if(finalSum == 0) return res;
        res.back() += finalSum;
        return res;
    }

static inline const char* FindStr4End( const char *p, const char *end )
{
    if( p >= end )
        return 0;

    if( p[0] == '\0' )    // special case for SuperCollider integer address pattern
        return p + 4;

    p += 3;
    end -= 1;

    while( p < end && *p )
        p += 4;

    if( *p )
        return 0;
    else
        return p + 1;
}

