void getTotCount(int num) {
    totCount=1;
    firstCount=1;
    int temp=1;
    while(( num&temp)== 0) {
        temp=temp<<1;
        totCount+=1 ;
    }
    firstCount=totCount;
    temp=num>>totCount;
    while(temp!=0) {
        totCount+=1;
        temp=temp>>1 ;
    }
}
