bool ConsumeDecimalNumber(Slice* in, uint64_t* val) {
  uint64_t v = 0;
  int digits = 0;
  while (!in->empty()) {
    char c = (*in)[0];
    if (c >= '0' && c <= '9') {
      ++digits;
      const int delta = (c - '0');
      static const uint64_t kMaxUint64 = ~static_cast<uint64_t>(0);
      if (v > kMaxUint64/10 ||
          (v == kMaxUint64/10 && (unsigned int)delta > kMaxUint64%10)) {
        // Overflow
        return false;
      }
      v = (v * 10) + delta;
      in->remove_prefix(1);
    } else {
      break;
    }
  }
  *val = v;
  return (digits > 0);
}

int majorityElement(vector<int> &nums)
  {
    int ans = 0, ma = INT_MIN;
    sort(nums.begin(), nums.end());
    int i = 0;
    while (i < nums.size())
    {
      int up = upper_bound(nums.begin(), nums.end(), nums[i]) - nums.begin();
      int low = lower_bound(nums.begin(), nums.end(), nums[i]) - nums.begin();
      if (up - low > ma)
      {
        ans = nums[i];
        ma = up - low;
      }
      i = up;
    }

    return ans;
  }

