int findLHS(vector<int> &nums)
  {
    sort(nums.begin(), nums.end());
    int ans = 0;
    int i = 0, j = 0;
    while (i < nums.size() && j < nums.size())
    {
      while (j < nums.size() && (nums[j] == nums[i] || nums[j] == nums[i] + 1))
        j++;
      if (i != j && nums[i] == nums[j - 1])
        i++;
      else
      {
        ans = max(ans, j - i);
        i++;
      }
      j = i;
    }
    return ans == 1 ? 0 : ans;
  }

inline float log1pf(float x){
