int count_triangles(int a,int b,int c,int d) {
    int ans=0;
    for(int x=a;x<=b;++ x) {
        int num_greater_than_d=max(d,c+x)- max(d,b+x-1);
        ans+=num_greater_than_d *(d-c+1);
        int r=min(max(c,c+x), d)- c;
        int l=min(max(c,b+x-1), d)- c;
        int x1 =(r *(r+1))/2;
        int x2 =(l *(l+1))/2;
        ans+=x1-x2 ;
    }
    return ans;
}

