int subzero(string str,int k) {
    int ans=0,curr=0;
    int len=str.length();
    for(int i=0;i<len;++ i) {
        if(str[i]== '0')curr ++;
        else curr=0;
        ans=max(ans,curr);
    }
    if(ans==len)return len*k;
    else {
        int pre=0,suff=0;
        for(int i=0;i<len;i ++) {
            if(str[i]== '0')pre ++;
            else break ;
        }
        for(int i=len-1;i>=0;i --) {
            if(str[i]== '0')suff ++;
            else break ;
        }
        if(k>1)ans=max(ans,pre+suff);
        return ans ;
    }
}

