int bestRotation(vector<int>& nums) {

        AVLTreeMultiSet<int> tree;

        int n = nums.size();
        for(int i = 0; i < n; i ++)
            tree.add(nums[i] - i);

        int best_score = 0, k = 0;
        for(int i = 0; i < n; i ++){
            int score = tree.size_less_than_or_equal_to(-i);
//            cout << "k : " << i << " score : " << score << '\n';

            if(score > best_score) best_score = score, k = i;

            tree.remove(nums[i] - i);
            tree.add(nums[i] - (n - 1) - (i + 1));
        }
        return k;
    }

