long long countSubarrays(vector<int>& nums, long long k) {

        int l = 0, r = -1, n = nums.size();
        long long cur_sum = 0, res = 0;
        while(l < n){
            if(r + 1 < n && 1ll * (cur_sum + nums[r + 1]) * (r + 1 - l + 1) < k){
                r ++;
                cur_sum += nums[r];
            }
            else{
                if(l <= r){
                    res += (r - l + 1);
                    cur_sum -= nums[l];
                }
                l ++;
                r = max(r, l - 1);
            }
        }
        return res;
    }

