vector<int> productExceptSelf(vector<int> &nums)
  {
    int n = nums.size();
    vector<int> left(n, 1), right(n, 1);

    int mult = 1;
    for (int i = 1; i < n; ++i)
    {
      mult = mult * nums[i - 1];
      left[i] = mult;
    }

    mult = 1;
    for (int i = n - 2; i >= 0; --i)
    {
      mult = mult * nums[i + 1];
      right[i] = mult;
    }

    for (int i = 0; i < n; ++i)
      nums[i] = left[i] * right[i];

    return nums;
  }

