        sort(begin(arr), end(arr), lambda); //O(nlog(n))

        for(int &x : arr) { //O(n)
            if(mp[x] == 0) continue;

            if(mp.find(2*x) == end(mp) || mp[2*x] == 0) return false;

            mp[x]--;
            mp[2*x]--;
        }

        return true;
    }

