TreeNode* dfs(const vector<int>& v, int l, int r){

        if(l > r || l >= v.size() || r >= v.size()) return NULL;

        TreeNode* root = new TreeNode(v[l]);

        int i;
        for(i = l + 1; i <= r; i ++)
            if(v[i] > v[l]) break;

        root->left = dfs(v, l + 1, i - 1);
        root->right = dfs(v, i, r);
        return root;
    }

int maxChunksToSorted(vector<int>& arr) {
