        MAX[0] = arr[0];
        for(int i = 1; i<n; i++)
            MAX[i] = max(MAX[i-1], arr[i]);

        int rightMax = MAX[n-1];
        int count    = 0;
        for(int  i = n-1; i>=0; i--) {
            if(sorted[i] == MAX[i]) {
                if(sorted[i] > rightMax)
                    continue; //because we need to include this as well for being sorted correctly

                rightMax = arr[i];
                count++;
            }
        }

        return count;
    }

int solve(int i, int remainder, vector<int>& nums, vector<vector<int>>& t) {
        if (i >= nums.size()) {
            return (remainder == 0) ? 0 : INT_MIN;
        }

        if (t[i][remainder] != -1)
            return t[i][remainder];

        // Pick the current number
        int pick = nums[i] +
                   solve(i + 1, (remainder + nums[i]) % 3, nums, t);

        // Skip the current number
        int notPick = solve(i + 1, remainder, nums, t);

        return t[i][remainder] = max(pick, notPick);
    }

