        int Count = 0;
        for(int i = 0; i<boxes.size(); i++) {
            int h_box = boxes[i];

            int j = 0;

            while(j <= lastWareHouse && warehouse[j] >= h_box)
                j++;

            if(j == 0)
                break;

            if(j <= lastWareHouse) {
                lastWareHouse = j-2;
            } else {
                lastWareHouse--;
            }
            Count++;
        }
        return Count;
    }

