    int ans = -A[0] + A[A.size() - 1];
    for (int i = 0; i < A.size() - 1; ++i)
    {
      int j = i + 1;
      int low = min(A[0] + K, A[j] - K);
      int high = max(A[A.size() - 1] - K, A[i] + K);
      ans = min(ans, high - low);
    }
    return ans;
  }

