int maxProfit(vector<int>& prices) {

        int n = prices.size();

        if(n <= 1)
            return 0;

        int buy[3] = {-prices[0], max(-prices[0], -prices[1]), 0};
        int sell[3] = {0, max(0, prices[1] - prices[0]), 0};

        for(int i = 2 ; i < n ; i ++){
            sell[i % 3] = max(sell[(i - 1) % 3], buy[(i - 1) % 3] + prices[i]);
            buy[i % 3] = max(buy[(i - 1) % 3], sell[(i - 2) % 3] - prices[i]);
        }

        return sell[(n - 1) % 3];
    }

int dfs2(TreeNode *root, ll &ans, ll totalSum)
    {
        int sumHere = root->val;

        if (root->left)
            sumHere += dfs2(root->left, ans, totalSum);
        if (root->right)
            sumHere += dfs2(root->right, ans, totalSum);

        ans = max(ans, sumHere * (totalSum - sumHere));
        return sumHere;
    }

