int n,m,X;
int maxSum(vector<vector<int>>grid) {
    vector<vector<int>>prefsum(n,vector<int >(m));
    for(int i=0;i<n;i ++) {
        for(int x=0;x<m;x ++) {
            if(x==0)prefsum[i ][x]= grid[i ][x];
            else prefsum[i ][x]= prefsum[i ][x-1]+ grid[i ][x];
        }
    }
    vector<vector<int>>dp(n,vector<int >(X+1,INT_MIN));
    for(int i=0;i<n;i ++)dp[i ][0]= 0;
    for(int i=1;i<=min(m,X);++i) {
        dp[0 ][i]= dp[0 ][i-1]+ grid[0 ][i-1];
    }
    for(int i=1;i<n;++ i) {
        for(int j=1;j<=X;++ j) {
            dp[i ][j]= dp[i-1 ][j];
            for(int x=1;x<=min(j,m); x ++) {
                dp[i ][j]= max(dp[i ][j], dp[i-1 ][j-x]+ prefsum[i ][x-1]) ;
            }
        }
    }
    return dp[n-1 ][X];
}

