int minOperations(vector<int>& numbers) {

        int n = numbers.size();

        vector<int> two(n, 0), three(n, 0), base(n, 0);
        for(int i = 0; i < n; i ++){
            int x = numbers[i];
            while(x % 2 == 0) two[i] ++, x /= 2;
            while(x % 3 == 0) three[i] ++, x /= 3;
            base[i] = x;
        }

        for(int i = 1; i < n; i ++)
            if(base[i] != base[0]) return -1;

        int res = 0;

        int max_two = *max_element(two.begin(), two.end());
        for(int e: two) res += max_two - e;

        int max_three = *max_element(three.begin(), three.end());
        for(int e: three) res += max_three - e;

        return res;
    }

void Relu6(MYINT* A, MYINT* B, MYITE N, MYITE H, MYITE W, MYITE C, MYINT six, MYINT div) {
    for (MYITE n = 0; n < N; n++) {
        for (MYITE h = 0; h < H; h++) {
            for (MYITE w = 0; w < W; w++) {
                for (MYITE c = 0; c < C; c++) {
                    MYINT a = A[n * H * W * C + h * W * C + w * C + c];
                    if (a < 0) {
                        a = 0;
                    }
                    if (a > six) {
                        a = six;
                    }

                    B[n * H * W * C + h * W * C + w * C + c] = a / div;
                }
            }
        }
    }
    return;
}

int minimumArea(vector<vector<int>>& grid) {
        int m = grid.size(); //Rows
        int n = grid[0].size(); //Columns

        int minRow = m;
        int maxRow = -1;
        int minCol = n;
        int maxCol = -1;

        for(int i = 0; i < m; i++) {
            for(int j = 0; j < n; j++) {
                if(grid[i][j] == 1) {
                    minRow = min(minRow, i);
                    maxRow = max(maxRow, i);

                    minCol = min(minCol, j);
                    maxCol = max(maxCol, j);
                }
            }
        }
        return (maxRow - minRow + 1) * (maxCol - minCol + 1);
    }

