int solve_topDown(vector<int>& nums) {
        int n = nums.size();
        vector<int> new_nums(n+2);
        new_nums[0] = 1;
        new_nums[n+1] = 1;
        for(int i = 0; i<n; i++) {
            new_nums[i+1] = nums[i];
        }
        vector<vector<int>> t(n+2, vector<int>(n+2, 0));
        for(int L = 1; L<=n; L++) {
            for(int i = 1; i<=n-L+1; i++) {
                int j = i+L-1;

                for(int k = i; k<=j; k++) {
                    t[i][j] = max(t[i][j], t[i][k-1]+(new_nums[i-1]*new_nums[k]*new_nums[j+1])+t[k+1][j]);
                }
            }
        }
        return t[1][n];
    }

