pair<int,int>find(int dividend,int divisor,int start,int end) {
    if(start>end)return {
        0,dividend
    }
    ;
    int mid=start +(end-start)/ 2;
    int n=dividend-divisor*mid;
    if(n>divisor)start=mid+1;
    else if(n<0)end=mid-1;
    else {
        if(n==divisor) {
            ++mid;
            n=0 ;
        }
        return {
            mid,n
        }
        ;
    }
    return find(dividend,divisor,start,end);
}
