    int sum=0;
    for(int i=n-2;i>=0;i --) {
        if(bin[i]== '1') {
            int posFromRight=n-i-1;
            if(posFromRight%4==1)sum=sum+2;
            else if(posFromRight%4==2)sum=sum+4;
            else if(posFromRight%4==3)sum=sum+8;
            else if(posFromRight%4==0)sum=sum+6 ;
        }
    }
    if(sum%10==0)return true;
    return false;
}

