void replaceRemove(string&s,char X,char Y,char Z) {
    int start=0,end=s.size()-1;
    while(start<=end) {
        if(s[start]== Z) {
            while(end>=0&&s[end]== Z) {
                end--;
            }
            if(end>start) {
                swap(s[start], s[end]);
                if(s[start]== X)s[start]= Y;
                start++;
            }
        }
        else {
            if(s[start]== X)s[start]= Y;
            start++;
        }
    }
    while(s.size()>0&&s[s.size()-1]== Z) {
        s.pop_back() ;
    }
}

