vector<int> goodIndices(vector<int>& nums, int k) {

        int n = nums.size();
        vector<int> dp1(n, 1), dp2(n, 1);
        for(int i = 1; i < n; i ++)
            if(nums[i] <= nums[i - 1]) dp1[i] = 1 + dp1[i - 1];
        for(int i = n - 2; i >= 0; i --)
            if(nums[i] <= nums[i + 1]) dp2[i] = 1 + dp2[i + 1];

        vector<int> res;
        for(int i = 1; i < n - 1; i ++)
            if(dp1[i - 1] >= k && dp2[i + 1] >= k) res.push_back(i);
        return res;
    }

