    for(int i=0;i<n/2;i ++) {
        map<char,int>mp;
        mp[A[i]] ++;
        mp[A[n-i-1]] ++;
        mp[B[i]] ++;
        mp[B[n-i-1]] ++;
        int sz=mp.size();
        if(sz==4)ans+=2;
        else if(sz==3)ans+=1 +(A[i]== A[n-i-1]);
        else if(sz==2)ans+=mp[A[i]]!=2 ;
