        int s = 0, t = n - 1;
        vector<int> dis(n, -1);

        queue<int> q;
        q.push(0);
        dis[0] = 0;
        while(!q.empty()){
            int u = q.front(); q.pop();
            if(u == t) break;

            for(int i = 1; i <= nums[u] && u + i < n; i ++)
                if(dis[u + i] == -1){
