int partitionDisjoint(vector<int> &A)
  {
    int n = A.size();
    vector<int> left(n, 0), right(n, 0);

    left[0] = A[0];
    right[n - 1] = A[n - 1];

    for (int i = 1; i < n; ++i)
      left[i] = max(left[i - 1], A[i]);
    for (int i = n - 2; i >= 0; --i)
      right[i] = min(right[i + 1], A[i]);

    for (int i = 1; i < n; ++i)
    {
      if (left[i - 1] <= right[i])
        return i;
    }

    return -1;
  }

