int getSetBitsFromOneToN(int N) {
    int two=2,ans=0;
    int n=N;
    while(n) {
        ans +=(N/two)*(two>>1);
        if(( N &(two-1)) >(two>>1)- 1)ans +=(N &(two-1)) -(two>>1)+ 1;
        two <<= 1;
        n >>= 1 ;
    }
    return ans;
}

int longestAlternatingSubarray(vector<int>& nums, int threshold) {

        int n = nums.size(), res = 0;
        for(int l = 0; l < n; l ++){
            if(nums[l] % 2 || nums[l] > threshold) continue;

            bool ok = true;
            for(int r = l; r < n && ok; r ++){
                for(int i = l + 1; i <= r && ok; i ++)
                    if(nums[i] % 2 == nums[i - 1] % 2 || nums[i] > threshold)
                        ok = false;
                if(ok) res = max(res, r - l + 1);
            }
        }
        return res;
    }

