bool isSafe(vector<vector<char>> &board, int r, int c, char val)
  {
    for (int i = 0; i < 9; ++i)
    {
      if (board[i][c] == val || board[r][i] == val)
        return false;
    }

    int si = 3 * (r / 3), sj = 3 * (c / 3);
    for (int i = 0; i < 3; ++i)
    {
      for (int j = 0; j < 3; ++j)
      {
        if (board[i + si][j + sj] == val)
          return false;
      }
    }

    return true;
  }

