bool iskaprekar(int n) {
    if(n==1)return true;
    int sq_n=n*n;
    int count_digits=0;
    while(sq_n) {
        count_digits ++;
        sq_n/=10 ;
    }
    for(int r_digits=1;r_digits<count_digits;r_digits ++) {
        int eq_parts=pow(10,r_digits);
        if(eq_parts==n)continue;
        int sum=sq_n/eq_parts+sq_n%eq_parts;
        if(sum==n)return true ;
    }
    return false;
}

