int minMoves(int target, int maxDoubles) {

        if(maxDoubles == 0) return target - 1;

        int res = 0, cur = target;
        while(maxDoubles && cur != 1){
            if(cur & 1) cur --, res ++;
            else cur >>= 1, res ++, maxDoubles --;
        }
        res += (cur - 1);
        return res;
    }

