string makePalindrome(string str) {
    int i=0,j=str.length()-1;
    while(i<=j) {
        if(str[i]== '*'&&str[j]== '*') {
            str[i]= ' a ';
            str[j]= ' a ' ;
        }
        else if(str[j]== '*')str[j]= str[i];
        else if(str[i]== '*')str[i]= str[j];
