int F3n_1(int n)        // O( length(3n+1) )
{
    if(n == 1)
        return 1;

    if(n%2 == 0)
        return 1 + F3n_1(n/2);    // Either this call

    return 1 + F3n_1(3 *n + 1);    // or this call, but NOT Both
}

using namespace std;
int transformSubsequence(int n,int m,vector<int>A,vector<int>B) {
    if(B.size()==0)return n;
    vector<vector<int>>dp(n+1,vector<int >(m+1,0));
    for(int i=0;i<n+1;i ++) {
        for(int j=0;j<m+1;j ++) {
            if(i==0 or j==0)dp[i ][j]= 0;
            else if(A[i-1]== B[j-1]) dp[i ][j]= 1+dp[i-1 ][j-1];
            else dp[i ][j]= max(dp[i-1 ][j], dp[i ][j-1]) ;
        }
    }
    return n-dp[n ][m];
}

int TrappingWaterTillEnd(Iter begin, Iter end) {
  int sum = 0, highest_level_seen = numeric_limits<int>::min();
  for (Iter iter = begin; iter != end; ++iter) {
    if (*iter >= highest_level_seen) {
      highest_level_seen = *iter;
    } else {
      sum += highest_level_seen - *iter;
    }
  }
  return sum;
}

int ComputeNumberOfWaysToH(int h, int maximum_step,
                           vector<int>* number_of_ways_to_h_ptr) {
  if (h <= 1) {
    return 1;
  }

  vector<int>& number_of_ways_to_h = *number_of_ways_to_h_ptr;
  if (number_of_ways_to_h[h] == 0) {
    for (int i = 1; i <= maximum_step && h - i >= 0; ++i) {
      number_of_ways_to_h[h] +=
          ComputeNumberOfWaysToH(h - i, maximum_step, number_of_ways_to_h_ptr);
    }
  }
  return number_of_ways_to_h[h];
}

