    if (t == nullptr) {
      l = r = nullptr;
      return;
    }
    if (t->key <= pos) {
      split(t->r, pos, l, r);
      t->r = l;
      l = t;
    } else {
      split(t->l, pos, l, r);
      t->l = r;
      r = t;
    }
