int minDominoRotations(vector<int> &A, vector<int> &B)
  {
    vector<int> ca(7), cb(7), same(7);
    int n = A.size();
    for (int i = 0; i < A.size(); i++)
    {
      ca[A[i]]++;
      cb[B[i]]++;
      if (A[i] == B[i])
        same[A[i]]++;
    }
    for (int i = 1; i < 7; i++)
    {
      if (ca[i] + cb[i] - same[i] == n)
        return n - max(ca[i], cb[i]);
    }
    return -1;
  }

vector<string> findStrobogrammaticRecu(const int n, int k) {
        static const unordered_map<string, string> lookup{{"0", "0"}, {"1", "1"},
                                                          {"6", "9"}, {"8", "8"},
                                                          {"9", "6"}};
        if (k == 0) {
            return {""};
        } else if (k == 1) {
            return {"0", "1", "8"};
        }
        vector<string> result;
        for (const auto& num : findStrobogrammaticRecu(n, k - 2)) {
            for (const auto& kvp : lookup) {
                if (n != k || kvp.first != "0") {
                    result.emplace_back(kvp.first + num + kvp.second);
                }
            }
        }
        return result;
    }

int longestSquareStreak(vector<int>& nums) {
        sort(begin(nums), end(nums));
        unordered_map<int, int> dp;
        int result = 0;
        for (const auto& x : nums) {
            const int sqrt_x = static_cast<int>(sqrt(x));
            if (sqrt_x * sqrt_x == x) {
                dp[x] = dp[sqrt_x] + 1;
            } else {
                dp[x] = 1;
            }
            result = max(result, dp[x]);
        }
        return result != 1 ? result : -1;
    }

double BuyAndSellStockTwice(const vector<double>& prices) {
  double max_total_profit = 0;
  vector<double> first_buy_sell_profits(size(prices), 0);
  double min_price_so_far = numeric_limits<double>::infinity();

  // Forward phase. For each day, we record maximum profit if we
  // sell on that day.
  for (int i = 0; i < size(prices); ++i) {
    min_price_so_far = min(min_price_so_far, prices[i]);
    max_total_profit = max(max_total_profit, prices[i] - min_price_so_far);
    first_buy_sell_profits[i] = max_total_profit;
  }

  // Backward phase. For each day, find the maximum profit if we make
  // the second buy on that day.
  double max_price_so_far = numeric_limits<double>::min();
  for (int i = size(prices) - 1; i > 0; --i) {
    max_price_so_far = max(max_price_so_far, prices[i]);
    max_total_profit = max(max_total_profit, max_price_so_far - prices[i] +
                                                 first_buy_sell_profits[i]);
  }
  return max_total_profit;
}

