int deleteString(string s) {

        StringHashU hash(s);

        int n = s.size();
        vector<int> dp(n + 1, 0);
        dp[n - 1] = 1;
        for(int start = n - 2; start >= 0; start --){
            int len = n - start, tres = 1;
            for(int i = 1; i <= len / 2; i ++)
                if(hash.get_hash(start, start + i - 1) == hash.get_hash(start + i, start + 2 * i - 1))
                    tres = max(tres, 1 + dp[start + i]);
            dp[start] = tres;
        }
        return dp[0];
    }

