uint64_t subarray_sum(int64_t sum, const std::vector<int64_t> &in_arr) {
    int64_t nelement = in_arr.size();
    int64_t count_of_subset = 0;
    int64_t current_sum = 0;
    std::unordered_map<int64_t, int64_t>
        sumarray;  // to store the subarrays count
                   // frequency having some sum value

    for (int64_t i = 0; i < nelement; i++) {
        current_sum += in_arr[i];

        if (current_sum == sum) {
            count_of_subset++;
        }
        // If in case current_sum is greater than the required sum
        if (sumarray.find(current_sum - sum) != sumarray.end()) {
            count_of_subset += (sumarray[current_sum - sum]);
        }
        sumarray[current_sum]++;
    }
    return count_of_subset;
}

int dfs(const vector<int>& days, int index, int n, const vector<int>& costs, vector<int>& dp){

        if(index >= n) return 0;
        if(dp[index] != -1) return dp[index];

        int res = costs[0] + dfs(days, index + 1, n, costs, dp);

        int i1 = 0;
        for(; i1 < n; i1 ++)
            if(days[i1] >= days[index] + 7) break;
        res = min(res, costs[1] + dfs(days, i1, n, costs, dp));

        int i2 = 0;
        for(; i2 < n; i2 ++)
            if(days[i2] >= days[index] + 30) break;
        res = min(res, costs[2] + dfs(days, i2, n, costs, dp));

        return dp[index] = res;
    }

long long dividePlayers(vector<int>& skill) {

        int n = skill.size();

        multiset<int> s;
        int sum = 0;
        for(int e: skill) s.insert(e), sum += e;

        if(sum % (n / 2)) return -1;
        int t = sum / (n / 2);

        long long res = 0;
        while(!s.empty()){
            int a = *s.begin();
            s.erase(s.begin());
            int b = t - a;
            auto iter = s.find(b);
            if(iter == s.end()) return -1;
            s.erase(iter);
            res += a * b;
        }
        return res;
    }

pair<int, int> solve(TreeNode* root) {
        if(!root)
            return {0, 0};

        auto l = solve(root->left);
        auto r = solve(root->right);

        pair<int, int> result;

        //if root is robbed, then we can only take notRobbed from left and right child
        result.first = root->val + l.second + r.second;

        //if root is NOT robbed, then we can take maximum from left and right child's
        //robbed and not robbed

        result.second = max(l.first, l.second) + max(r.first, r.second);

        return result;
    }

