int solve(const vector<int>& v, int k){

        set<int> seen;
        seen.insert(0);

        int sum = 0, res = INT_MIN;
        for(int e: v){

            sum += e;
            set<int>::iterator iter = seen.lower_bound(sum - k);
            if(iter != seen.end())
                res = max(res, sum - *iter);
            seen.insert(sum);
        }
        return res;
    }

