bool ok(const vector<int>& nums, int k, double average){

        double sum = 0.0;
        for(int i = 0; i < k; i ++)
            sum += nums[i] - average;

        if(sum >= 0) return true;
        double premin = 0, presum = 0.0;
        for(int i = k; i < nums.size(); i ++){
            sum += nums[i] - average;
            presum += (nums[i - k] - average);

            premin = min(premin, presum);
            if(sum - premin >= 0) return true;
        }
        return false;
    }

int dfs(const int n, const int k, int index, bool same,
            vector<vector<int>>& dp){

        if(index == n) return 1;
        if(dp[same][index] != -1) return dp[same][index];

        int res = 0;
        if(same) res += (k - 1) * dfs(n, k, index + 1, false, dp);
        else{
            res += (k - 1) * dfs(n, k, index + 1, false, dp);
            res += dfs(n, k, index + 1, true, dp);
        }
        return dp[same][index] = res;
    }

int for20(priority_queue<int>& pq, int need_change){
        int res = 0;
        while(!pq.empty() && need_change){
            int cur = pq.top(); pq.pop();
            res ++, need_change --;
            cur -= 3;
            if(cur >= 3) pq.push(cur);
        }

        if(need_change) res += need_change;
        else{
            while(!pq.empty()){
                int cur = pq.top(); pq.pop();
                res += cur / 3;
            }
        }
        return res;
    }

int dfs(const vector<int>& nums, int index, int S,
            vector<vector<int>>& dp){

        if(index == nums.size())
            return S == 0;

        if(S + 1000 < 0 || S + 1000 >= 2001)
            return 0;

        if(dp[index][S + 1000] != -1)
            return dp[index][S + 1000];

        int ret = 0;
        ret += dfs(nums, index + 1, S - nums[index], dp);
        ret += dfs(nums, index + 1, S + nums[index], dp);
        return dp[index][S + 1000] = ret;
    }

