void bfs(int start, unordered_map<int, vector<int>> &adj, int id,
             vector<int>& nodeId, unordered_map<int, set<int>>& mp,
             vector<bool>& visited) {

        queue<int> q;
        q.push(start);
        visited[start] = true;
        nodeId[start] = id;
        mp[id].insert(start);

        while (!q.empty()) {
            int node = q.front();
            q.pop();

            for (int &ngbr : adj[node]) {
                if (!visited[ngbr]) {
                    visited[ngbr] = true;
                    nodeId[ngbr] = id;
                    mp[id].insert(ngbr);
                    q.push(ngbr);
                }
            }
        }
    }

int solve(TreeNode* root, int &moves) {
        if(root == NULL) {
            return 0;
        }

        int l = solve(root->left, moves);
        int r = solve(root->right, moves);

        int total_extra_candies = (l + r + root->val) - 1;

        moves += abs(l) + abs(r);

        return total_extra_candies;
    }

vector<int> minOperations(string boxes) {
        int n = boxes.size();
        int left_cnt = 0, tot_cnt = 0; // cnt of 1s
        int left_sum = 0, tot_sum = 0; // sum of indices where its a 1


        for(int i = 0; i < n; i++) {
            if (boxes[i] == '1') tot_cnt++, tot_sum += i;
        }

        vector<int> ans = {};
        for(int i = 0; i < n; i++) {
            int right_cnt = tot_cnt - left_cnt;
            int right_sum = tot_sum - left_sum;

            int left = left_cnt * i - left_sum;
            int right = right_sum - right_cnt * i;
            ans.push_back(left + right);

            if (boxes[i] == '1') left_cnt++, left_sum += i;
        }
        return ans;
    }

bool isLongPressedName(string name, string typed) {

        int start1 = 0, start2 = 0;
        for(int i1 = start1 + 1; i1 <= name.size(); i1 ++)
            if(i1 == name.size() || name[i1] != name[start1]){

                if(start2 >= typed.size())
                    return false;

                for(int i2 = start2 + 1; i2 <= typed.size(); i2 ++)
                    if(i2 == typed.size() || typed[i2] != typed[start2]){

                        if(typed[start2] != name[start1] || i2 - start2 < i1 - start1)
                            return false;

                        start2 = i2;
                        break;
                    }

                start1 = i1;
            }

        return start1 == name.size();
    }

