int modExp(int a,int b) {
    int result=1;
    while(b>0) {
        if(b&1)result=result*a;
        a=a*a;
        b/=2 ;
    }
    return result ;
}
int check(int num) {
    if(num&1 num<3)return -1;
    else if(num%4==0)return modExp(num/4,4);
    else if(num%6==0)return modExp(num/3,2)* modExp(num/6,2);
    else if(num%10==0)return modExp(num/5,2)*(num/10)*(num/2);
    else return -1;
}

int bestClosingTime(string customers) {
        int n           = customers.length();

        int minHour  = 0;
        int penalty  = count(begin(customers), end(customers), 'Y');

        int minPenalty = penalty;

        for(int i = 0; i< n ; i++) {

            if(customers[i] == 'Y') {
                penalty--;
            } else {
                penalty++;
            }

            if(penalty < minPenalty) {
                minHour = i+1;
                minPenalty = penalty;
            }
        }

        return minHour;

    }

