int longestSubstring(string s,int n) {
    map<int,int>index;
    int answer=0;
    int mask=0;
    index[mask]= -1;
    for(int i=0;i<n;i ++) {
        int temp =(int)s[i]- 97;
        mask ^=(1<<temp);
        if(index[mask]) {
            answer=max(answer,i-index[mask]) ;
        }
        else index[mask]= i;
        for(int j=0;j<26;j ++) {
            int mask2=mask ^(1<<j);
            if(index[mask2]) {
                answer=max(answer,i-index[mask2]) ;
            }
        }
    }
    return answer;
}

int dfs(const string& s, int l, int r, vector<vector<int>>& dp){

        if(l > r) return 0;
        if(l == r) return 1;

        if(dp[l][r] != -1) return dp[l][r];

        int res = 1 + dfs(s, l + 1, r, dp);
        for(int i = l + 1; i <= r; i ++)
            if(s[i] == s[l])
                res = min(res, dfs(s, l, i - 1, dp) + dfs(s, i + 1, r, dp));
