static float Gendyn_mirroring(float lower, float upper, float in) {
    // mirroring for bounds- safe version
    if (in > upper || in < lower) {
        float range = (upper - lower);

        if (in < lower)
            in = (2.0f * upper - lower) - in;

        in = fmod(in - upper, 2.0f * range);

        if (in < range)
            in = upper - in;
        else
            in = in - (range);
    }

    return in;
}

