int combinationsPossible(int N,int idx,int prev,int val,int K,vector<vector<vector<int>>>&dp) {
    if(val>K) {
        return 0 ;
    }
    if(dp[val ][idx ][prev]!= -1) {
        return dp[val ][idx ][prev];
    }
    if(idx==N-1) {
        if(val==K) {
            return 1 ;
        }
        return 0 ;
    }
    int ans=0;
    if(prev==1) {
        ans+=combinationsPossible(N,idx+1,1,val+1,K,dp);
        ans+=combinationsPossible(N,idx+1,0,val,K,dp);
    }
    else {
        ans+=combinationsPossible(N,idx+1,1,val,K,dp);
        ans+=combinationsPossible(N,idx+1,0,val,K,dp);
    }
    return dp[val ][idx ][prev]= ans;
}

void sortColors(vector<int>& nums) {
        int n = nums.size();

        int i = 0;   //denotes for 0
        int j = 0;   //denotes for 1
        int k = n-1; //denotes for 2

        while ( j <= k) {
            if(nums[j] == 1) {
                j++;
            } else if(nums[j] == 2) {
                swap(nums[j], nums[k]);
                k--;
            } else { //nums[j] == 0
                swap(nums[j], nums[i]);
                i++;
                j++;
            }
        }
    }

