        t[0][0] = 1; //total ways to reach 0,0 from 0,0

        //Fill 0th row
        for(int col = 1; col < n; col++) {
            t[0][col] = 1;
        }

        //Fill 0th col
        for(int row = 1; row < m; row++) {
            t[row][0] = 1;
        }

        for(int i = 1; i < m; i++) {
            for(int j = 1; j < n; j++) {
                t[i][j] = t[i-1][j] + t[i][j-1];
            }
        }

        return t[m-1][n-1];

    }

