void rotate(vector<int>& nums, int k) {

        int start = 0, cur = 0, t = nums[cur];
        for(int i = 0; i < nums.size() ; i ++){
            int next = (cur + k) % nums.size();
            int t2 = nums[next];
            nums[next] = t;
            t = t2;
            cur = next;

            if(cur == start)
                start ++, cur = start, t = nums[cur];
        }
        return;
    }

