inline int32 Hash(const char* inKey, size_t* outLength) {
    // the one-at-a-time hash.
    // a very good hash function. ref: a web page by Bob Jenkins.
    const char* origKey = inKey;
    int32 hash = 0;
    while (*inKey) {
        hash += *inKey++;
        hash += hash << 10;
        hash ^= hash >> 6;
    }
    hash += hash << 3;
    hash ^= hash >> 11;
    hash += hash << 15;
    *outLength = (size_t)(inKey - origKey);
    return hash;
}

