int dfs(const string& s, int l, int r, vector<vector<int>>& dp){

        if(l > r) return 0;
        if(l == r) return 1;
        if(dp[l][r] != -1) return dp[l][r];

        int res = dfs(s, l + 1, r, dp);
        for(int i = r; i > l; i --)
            if(s[i] == s[l]){
                res = max(res, 2 + dfs(s, l + 1, i - 1, dp));
                break;
            }
        return dp[l][r] = res;
    }

