int solve(const vector<int>& nums, int start, int k, const vector<long long>& presum){

        int l = start, r = nums.size() - 1;
        while(l < r){

            int mid = (l + r + 1) / 2;
            if((long long)nums[mid] * (mid - start + 1) - (presum[mid + 1] - presum[start]) <= (long long)k)
                l = mid;
