ListNode* removeNthFromEnd(ListNode* head, int n) {
        int length = lengthLinkedList(head);

        if(length == n) { //Length node form end means first node
            ListNode* temp = head->next;
            delete(head);
            return temp;
        }

        ListNode* temp = head;
        ListNode* prev = NULL;
        int travel = length-n;

        while(travel--) {
            prev = temp;
            temp = temp->next;
        }

        prev->next = temp->next;

        delete(temp);

        return head;

    }

