int maxDepthBST(vector<int>& order) {

        map<int, int> tree; // e -> depth
        int res = 1;
        tree[order[0]] = 1;

        for(int i = 1; i < order.size(); i ++){
            int d = 1;

            map<int, int>::iterator iter = tree.lower_bound(order[i]);
            if(iter != tree.end()) {
                d = max(d, iter->second + 1);
            }

            if(iter != tree.begin()){
                iter --;
                d = max(d, iter->second + 1);
            }

            tree[order[i]] = d;
            res = max(res, d);
        }
        return res;
    }

