int min_cost(int n,int x,int p,int q) {
    if(x==1) {
        cout <<(n-1)* p<<endl;
        return 0 ;
    }
    int ans =(n-1)* p;
    int pre=0;
    while(n>1) {
        int tmp=n/x;
        if(tmp<0)break;
        pre +=(n-tmp*x)* p;
        n/=x;
        pre+=q;
        ans=min(ans,pre +(n-1)* p);
    }
    return ans;
}

TreeNode* construct(const vector<int>& A, int l, int r){

        if(l > r) return NULL;

        int best_val = A[l], best_index = l;
        for(int i = l + 1; i <= r; i ++)
            if(A[i] > best_val)
                best_val = A[i], best_index = i;

        TreeNode* retNode = new TreeNode(A[best_index]);
        retNode->left = construct(A, l, best_index - 1);
        retNode->right = construct(A, best_index + 1, r);
        return retNode;
    }

