ListNode* insertGreatestCommonDivisors(ListNode* head) {
        // Base case: if head is null or there's only one node, return head.
        if (!head || !head->next) {
            return head;
        }

        // Recursively process the rest of the list
        ListNode* temp = insertGreatestCommonDivisors(head->next);

        // Create a new node with the GCD of current and next node values
        ListNode* gcdNode = new ListNode(__gcd(head->val, head->next->val));

        // Insert the new node between the current node and the next node
        gcdNode->next = temp;
        head->next = gcdNode;

        // Return the current node
        return head;
    }

long long minimumTotalDistance(vector<int>& robot, vector<vector<int>>& factory) {
        static const int64_t INF = numeric_limits<int64_t>::max();
        sort(begin(robot), end(robot));
        sort(begin(factory), end(factory));
        vector<int64_t> dp(size(robot) + 1, INF);  // dp[j] at i: min of factory[:i+1] and robot[:j]
        dp[0] = 0;
        for (int i = 0; i < size(factory); ++i) {
            int64_t prefix = 0;
            deque<pair<int64_t, int>> dq = {{dp[0] - prefix, 0}};  // pattern of min in the sliding window with size (limit+1)
            for (int j = 1; j <= size(robot); ++j) {
                prefix += abs(robot[j - 1] - factory[i][0]);
                if (j - dq.front().second == factory[i][1] + 1) {
                    dq.pop_front();
                }
                while (!empty(dq) && dq.back().first >= (dp[j] != INF ? dp[j] - prefix : INF)) {
                    dq.pop_back();
                }
                dq.emplace_back((dp[j] != INF ? dp[j] - prefix : INF), j);
                dp[j] = dq.front().first != INF ? dq.front().first + prefix : INF;
            }
        }
        return dp.back();
    }

vector<int> prevPermOpt1(vector<int>& arr) {

        if(is_sorted(arr.begin(), arr.end())) return arr;

        int n = arr.size();
        for(int i = n - 1; i > 0; i --)
            if(arr[i - 1] > arr[i]){
                auto iter = lower_bound(arr.begin() + i, arr.end(), arr[i - 1]);
                iter --;

                int index = iter - arr.begin();
                int t = *iter;
                while(arr[index - 1] == t) index --;

                swap(arr[i - 1], arr[index]);
                break;
            }
        return arr;
    }

