    int x=INT_MAX;
    if(k<=c)return 0;
    int h=k-c;
    int l=0;
    while(l<=h) {
        int m =(l+h)/ 2;
        if(( a*m*m)+(b*m)>(k-c)) {
            x=min(x,m);
            h=m-1 ;
        }
        else if(( a*m*m)+(b*m)<(k-c)) l=m+1;
        else return m ;
    }
    return x;
}

