int right_angled(int n) {
    set<pair<int,pair<int,int>>> s;
    for(int x=1;x<=n;x ++) {
        for(int y=1;y<=n;y ++) {
            if(x*x+y*y<=n*n) {
                int z=sqrt(x*x+y*y);
                if(z*z !=(x*x+y*y)) continue;
                vector<int>v;
                v.push_back(x);
                v.push_back(y);
                v.push_back(sqrt(x*x+y*y));
                sort(v.begin(),v.end());
                s.insert( {
                    v[0], {
                        v[1], v[2]
                    }
                }
                );
            }
            else break ;
        }
    }
    return s.size();
}

