        int n = prices.size();

        vector<int> res(n, 0);
        res[n - 1] = prices[n - 1];
        for(int i = n - 2; i >= 0; i --){
            res[i] = prices[i];
            for(int j = i + 1; j < n; j ++)
                if(prices[j] <= prices[i]){
                    res[i] -= prices[j];
                    break;
                }
        }
        return res;
    }

