        int n = A.size();
        int best = 0;
        for(int i = n - 1; i >= 0; i --)
            for(int j = i - 1; j >= 0; j --){
                if(j - 1 >= 0 && A[j - 1] > A[i] - A[j])
                    best = max(best, A[i] + A[j] + A[j - 1]);
                else
                    break;
            }
        return best;
    }

