int countPS(string str, int i, int j, vector<vector<int>> &dp)
{
  if (i > j)
    return 0;

  if (dp[i][j] != -1)
    return dp[i][j];

  if (i == j)
    return dp[i][j] = 1;

  else if (str[i] == str[j])
    return dp[i][j] = countPS(str, i + 1, j, dp) + countPS(str, i, j - 1, dp) + 1;

  else
    return dp[i][j] = countPS(str, i + 1, j, dp) + countPS(str, i, j - 1, dp) - countPS(str, i + 1, j - 1, dp);
}

