int nearestPow(int x,int y) {
    if(y==1)return 1;
    int k=log10(x)/ log10(y);
    if(abs(pow(y,k)- x)< abs(pow(y ,(k+1))-x)) return pow(y,k);
    return pow(y ,(k+1)) ;
}
void replacebyNearestPower(vector<int>arr) {
    int prev=arr[arr.size()-1];
    int lastNext=arr[0];
    int next=0;
    for(int i=0;i<arr.size();i ++) {
        int temp=arr[i];
        if(i==arr.size()-1)next=lastNext;
        else next=arr[( i+1)% arr.size()];
        int prevPow=nearestPow(arr[i], prev);
        int nextPow=nearestPow(arr[i], next);
        if(abs(arr[i]- prevPow)< abs(arr[i]- nextPow)) arr[i]= prevPow;
        else arr[i]= nextPow;
        prev=temp ;
    }
    for(int i=0;i<arr.size();i ++)cout<<arr[i]<< " ? ";
}

