int binary_search(const vector<vector<int>>& v, const vector<int>& e){

        int l = 0, r = v.size();
        while(l != r){
            int mid = (l + r) / 2;
            if(v[mid][0] >= e[0] && v[mid][1] >= e[1] && v[mid][2] >= e[2])
                r = mid;
            else
                l = mid + 1;
        }
        return l == v.size() ? -1 : l;
    }

