        vector<int> f(30, 0);
        for(int e: nums){
            for(int p = 0; p < 30; p ++) if(e & (1 << p)) f[p] ++;
        }

        long long res = 0;
        for(int e: nums){
            for(int p = 0; p < 30; p ++) if(e & (1 << p)) f[p] --;

            long long tres = e;
            tres <<= k;
            for(int p = 0; p < 30; p ++) if(f[p]) tres |= (1ll << p);
