long long int productPrimeFactors(int n) {
    long long int product=1;
    if(n%2==0) {
        product*=2;
        while(n%2==0)n=n/2 ;
    }
    for(int i=3;i<=sqrt(n); i=i+2) {
        if(n%i==0) {
            product=product*i;
            while(n%i==0)n=n/i ;
        }
    }
    if(n>2)product=product*n;
    return product;
}

