int bestTeamScore(vector<int>& scores, vector<int>& ages) {

        int n = scores.size();
        vector<pair<int, int>> v(n);
        for(int i = 0; i < n; i ++) v[i].first = ages[i], v[i].second = scores[i];
        sort(v.begin(), v.end());

        vector<int> dp(n, 0);
        dp[0] = v[0].second;
        for(int i = 1; i < n; i ++){
            dp[i] = v[i].second;
            for(int j = i - 1; j >= 0; j --)
