    }

int maxSeg1(int N, int x, int y, int z) {
    int maxR = 0;
    for(int a = 0; a<=N; a++) {
        for(int b = 0; b<=N; b++) {
            int cz    = N-(a*x + b*y);
            if(cz < 0) {
                break;
            }
            double c  = double(cz)/double(z);
            if(c == int(c)) {
                maxR = max(maxR, a+b+(int)c);
            }
        }
    }
    return maxR;
}

int getKthMagicNumber(int k) {

        priority_queue<long long, vector<long long>, greater<long long>> pq;
        pq.push(1);

        set<long long> visited;

        long long res = -1;
        while(k){
            res = pq.top(); pq.pop();
            if(visited.count(res)) continue;

            visited.insert(res);

            k --;
            pq.push(res * 3);
            pq.push(res * 5);
            pq.push(res * 7);
        }
        return res;
    }

