int numberOfArithmeticSlices(vector<int>& A) {

        int n = A.size();
        if(n < 3) return 0;

        vector<map<long long, int>> dp(n);
        for(int i = 1; i < n; i ++){
            for(int j = i - 1; j >= 0; j --){
                long long d = (long long)A[i] - A[j];
                if(dp[j].count(d))
                    dp[i][d] += dp[j][d] + 1;
                else
                    dp[i][d] += 1;
//                cout << i << " " << d << " : " << dp[i][d] << endl;
            }
        }

        int res = 0;
        for(int i = 0; i < n; i ++)
            for(const pair<long long, int>& p: dp[i]) res += p.second;

        return res - n * (n - 1) / 2;
    }

