int CyclicShifts(string str) {
    int n=str.length();
    int left=0;
    int right=n-1;
    str=str+str;
    int cnt=0;
    while(right<2*n-1) {
        if(isPalindrome(str,left,right)) break;
        cnt ++;
        left ++;
        right++;
    }
    return cnt;
}

