void findTilt(TreeNode *root, int &ans)
  {
    if (!root)
      return;

    int lVal = root->left ? treeSum(root->left) : 0;
    int rVal = root->right ? treeSum(root->right) : 0;

    int newVal = abs(lVal - rVal);
    root->val = newVal;
    ans += newVal;

    if (root->left)
      findTilt(root->left, ans);
    if (root->right)
      findTilt(root->right, ans);
  }

