ListNode *detectCycle(ListNode *head)
  {
    auto fast = head, slow = head;
    while (fast && fast->next)
    {
      fast = fast->next->next;
      slow = slow->next;

      if (fast == slow)
        break;
    }

    if (fast == NULL || fast->next == NULL)
      return NULL;

    fast = head;
    while (fast != slow)
    {
      fast = fast->next;
      slow = slow->next;
    }

    return slow;
  }

