int dfs(const vector<int>& boxes, int l, int r, int k, vector<vector<vector<int>>>& dp){

        if(l > r) return 0;

        if(dp[l][r][k] != -1) return dp[l][r][k];

        int res = dfs(boxes, l, r - 1, 0, dp) + (k + 1) * (k + 1);

        for(int i = l; i < r; i ++)
            if(boxes[i] == boxes[r])
                res = max(res, dfs(boxes, l, i, k + 1, dp) + dfs(boxes, i + 1, r - 1, 0, dp));
        return dp[l][r][k] = res;
    }

