    int sum_even=0;
    int sum_odd=0;
    while(n%2==0) {
        sum_even+=2;
        n=n/2 ;
    }
    for(int i=3;i<=sqrt(n); i=i+2) {
        while(n%i==0) {
            sum_odd+=i;
            n=n/i ;
        }
    }
    if(n>2)sum_odd+=n;
    return sum_even==sum_odd;
