int dfs(vector<int>& f, int k, map<long long, int>& dp){

        long long h = 0;
        for(int e: f) h = h * 10ll + e;

        auto iter = dp.find(h);
        if(iter != dp.end()) return iter->second;

        int pre = f[0];
        int res = 0;
        for(int i = 1; i < f.size(); i ++)
            if(f[i]){
                f[i] --;
                f[0] = (pre + i) % k;
                res = max(res, (pre == 0) + dfs(f, k, dp));
                f[0] = pre;
                f[i] ++;
            }
        return dp[h] = res;
    }

