        vector<vector<int>> t(n+1, vector<int>(amount+1));

        for(int i = 0; i<n+1; i++) {
            for(int j = 0; j<amount+1; j++) {
                if(j == 0) {
                    t[i][j] = 1;
                } else if(i == 0) {
                    t[i][j] = 0;
                } else if(coins[i-1] <= j) {
                    t[i][j] = t[i][j-coins[i-1]] + t[i-1][j];
                } else {
                    t[i][j] = t[i-1][j];
                }
            }
        }

        return t[n][amount];
    }

