string ConstructBinaryString(int N,int M,int K) {
    if(M <(N-1)|| M>K *(N+1)) return " - 1";
    string ans=" ";
    int l=min(K,M /(N-1));
    int temp=N;
    while(temp --) {
        ans+='0';
        if(temp==0)break;
        for(int i=0;i<l;i ++) {
            ans+='1' ;
        }
    }
    M -=(N-1)* l;
    if(M==0)return ans;
    l=min(M,K);
    for(int i=0;i<l;i ++)ans+='1';
    M-=l;
    while(M>0) {
        ans='1'+ans;
        M--;
    }
    return ans;
}

