        stack<pair<char, int>> stack;
        for(char c: s){
            if(!stack.empty() && stack.top().first == c)
                stack.top().second ++;
            else
                stack.push(make_pair(c, 1));

            if(stack.top().second == k)
                stack.pop();
        }

        string res = "";
        while(!stack.empty())
            res += string(stack.top().second, stack.top().first), stack.pop();
        reverse(res.begin(), res.end());
        return res;
    }

