void KPrimeDivisors(int N,int K) {
    int maximum_split=0;
    while(N%2==0) {
        maximum_split ++;
        N/=2 ;
    }
    for(int i=3;i*i<=N;i=i+2) {
        while(N%i==0) {
            N=N/i;
            maximum_split++;
        }
    }
    if(N>2)maximum_split ++;
    if(maximum_split<K) {
        printf(" No STR");
        return ;
    }
    printf(" Yes STR");
}

string getHint(string secret, string guess) {
        unordered_map<char, int> lookup;
        int A = 0, B = 0;
        for (int i = 0; i < size(secret); ++i) {
            const char s = secret[i];
            const char g = guess[i];
            if (s == g) {
                ++A;
            } else {
                B += int(lookup[s]++ < 0) + int(lookup[g]-- > 0);
             }
        }
        return to_string(A).append("A").append(to_string(B)).append("B");
    }

using namespace std;
int maximumSum(vector<int>A,int N,int K,int D) {
    int ans=0;
    for(int i=0;i <(1<<N); i ++) {
        int sum=0;
        int c=0;
        for(int j=0;j<N;j ++) {
            if(i>>j&1) {
                sum+=A[j];
                c++;
            }
        }
        if(sum%D==0&&c<=K)ans=max(ans,sum);
    }
    return ans;
}

