double Probability(double p[],int n) {
    double dp[n+1 ][n+1];
    memset(dp,0.0,sizeof(dp));
    dp[0 ][0]= 1.0;
    for(int i=1;i<=n;i+=1) {
        for(int j=0;j<=i;j+=1) {
            if(j==0)dp[i ][j]= dp[i-1 ][j]*(1.0-p[i]);
            else dp[i ][j]= dp[i-1 ][j]*(1.0-p[i])+dp[i-1 ][j-1]* p[i];
        }
    }
    double ans=0.0;
    for(int i =(n+1)/ 2;i<=n;i+=1)ans+=dp[n ][i];
    return ans;
}

