        if(!node) return {0, 0};

        int sum = node->val, cnt = 1;
        pair<int, int> left_res = dfs(node->left, res);
        pair<int, int> right_res = dfs(node->right, res);
        sum += left_res.first + right_res.first;
        cnt += left_res.second + right_res.second;

