int binarySearch(vector<int>& nums, int n, int target) {
        int l = 0, r = n-1;
        int mid;
        int result_idx = -1;

        while(l <= r) {
            mid = l + (r-l)/2;
            if(nums[mid] <= target) {
                result_idx = mid;
                l = mid+1;
            } else if(nums[mid] > target) {
                r = mid-1;
            }
        }
        return result_idx+1;
    }

