ListNode* removeNodes(ListNode* head) {
        // Base case: If the list is empty or has only one node, return it as is
        if (head == NULL || head->next == NULL) {
            return head;
        }

        // Recursively process the next node
        ListNode* nextNode = removeNodes(head->next);

        // If the current node's value is less than the next node's value, skip it
        if (head->val < nextNode->val) {
            return nextNode;
        }

        // Otherwise, retain the current node and link it to the modified next node
        head->next = nextNode;
        return head;
    }

int subsetSum(vector<int>& nums, int s) {
        int n = nums.size();
        vector<vector<int>> t(n+1, vector<int>(s+1));

        for(int col = 0; col < s+1; col++) t[0][col] = 0;
        for(int row = 0; row < n+1; row++) t[row][0] = 1;

        for(int i = 1; i<n+1; i++) {
            for(int j = 1; j<s+1; j++) {
                if(nums[i-1] == 0)
                    t[i][j] = t[i-1][j];
                else if(nums[i-1] <= j)
                    t[i][j] = t[i-1][j-nums[i-1]] + t[i-1][j];
                else
                    t[i][j] = t[i-1][j];
            }
        }

