            int end   = trip[2];

            events[start] += count;
            events[end] -= count;
        }

        int passCount = 0;

        for(auto &it : events) {
            passCount += it.second;

            if(passCount > capacity)
                return false;
        }

        return true;
    }

int solve(int n, const vector<int>& v){

        int res = 0;
        for(int start = 0, end = 0; start < n; start ++){
            if(v[start] == 0) continue;
            if(end < start) end = start;
            while(end < n && v[end] >= end - start + 1) end ++;
            if(end - start > 1) res += end - start - 1;
        }
        return res;
    }

