int MinimumOperationReq(int N) {
    int cntDecr=0;
    int temp=N;
    while(temp>0) {
        int X=sqrt(temp);
        if(X*X==temp) {
            break ;
        }
        temp=temp-2;
        cntDecr+=1 ;
    }
    int cntIncr=0;
    while(true) {
        int X=sqrt(N);
        if(X*X==N) {
            break ;
        }
        N=N+2;
        cntIncr+=1 ;
    }
    return min(cntIncr,cntDecr);
}

