ll query (node *at, int i, int j, int a, int b, int val) {
    prop (at, i, j);
    if (j < a or i > b)    return 0;

    if (i >= a and j <= b) {
        at->lazy += val;
        prop (at, i, j);
        return at->val;
    } else {
        int mid = (i + j)>>1;

        if (!at->l)    at->l = new node();
        if (!at->r) at->r = new node();

        ll L = query (at->l, i, mid, a, b, val);
        ll R = query (at->r, mid + 1, j, a, b, val);
        at->val = at->l->val + at->r->val;
        return L + R;
    }
}

