int dfs(vector<int> &nums, int tar, unordered_map<int, int> &memo)
  {
    if (tar < 0)
      return 0;
    if (tar == 0)
      return 1;

    if (memo.find(tar) != memo.end())
      return memo[tar];

    int ans = 0;
    for (int i = 0; i < nums.size(); ++i)
    {
      ans += dfs(nums, tar - nums[i], memo);
    }

    memo[tar] = ans;
    return ans;
  }

