int countPrimesInRange_sieve(int n)    // Backward thinking
{
    vector<bool> isPrime(n+1, true);    // set all of them to primes
    isPrime[0] = isPrime[1] = 0;        // 0, 1 are not primes

    for (ll i = 2; i*i <= n; ++i) {
        if (isPrime[i]) {
            for (int j = i * 2; j <= n; j += i)
                isPrime[j] = 0;
        }
    }

    int cnt = 0;

    for (int i = 0; i < (int)isPrime.size(); ++i)
        if(isPrime[i])
            cnt++;

    return cnt;
}

string stoneGameIII(vector<int>& stoneValue) {

        int n = stoneValue.size();
        vector<int> dp(4, 0);
        for(int start = n - 1; start >= 0; start --){
            int sum = 0;
            dp[start % 4] = INT_MIN;
            for(int i = 0; i < 3 && start + i < n; i ++){
                sum += stoneValue[start + i];
                dp[start % 4] = max(dp[start % 4], sum - (start + i + 1 < n ? dp[(start + i + 1) % 4] : 0));
            }
        }

        if(dp[0] > 0) return "Alice";
        else if(dp[0] < 0) return "Bob";
        return "Tie";
    }

