int floorSqrt(int x)
{
    // Base cases
    if (x == 0 || x == 1)
    return x;

    // Staring from 1, try all numbers until
    // i*i is greater than or equal to x.
    int i = 1, result = 1;
    while (result <= x)
    {
      i++;
      result = i * i;
    }
    return i - 1;
}

vector<int> shuffle(vector<int>& nums, int n) {

        for(int i = 0; i < 2 * n; i ++)
            if(nums[i] > 0){
                int j = i;
                while(nums[i] > 0){
                    j = j < n ? 2 * j : 2 * (j - n) + 1;
                    swap(nums[i], nums[j]);
                    nums[j] = -nums[j];
                }
         }

        for(int& e: nums) e = -e;
        return nums;
    }

int search(const vector<int>& arr, int l, int r,
               vector<vector<int>>& maxv, vector<vector<int>>& dp){

        if(l == r)
            return 0;

        if(dp[l][r] != -1) return dp[l][r];

        int res = INT_MAX;
        for(int mid = l; mid < r; mid ++){
            int lres = search(arr, l, mid, maxv, dp);
            int rres = search(arr, mid + 1, r, maxv, dp);
            res = min(res, lres + rres + maxv[l][mid] * maxv[mid + 1][r]);
        }

        return dp[l][r] = res;
    }

double diagonal_length(const Bbox_3& bbox)
{
  double dx = bbox.xmax() - bbox.xmin();
  double dy = bbox.ymax() - bbox.ymin();
  double dz = bbox.zmax() - bbox.zmin();

  double diag = dx * dx + dy * dy + dz * dz;
  return std::sqrt(diag);
}

