        int l = 0, r = -1, cur = 0, res = 0; // Sliding Window : [l, r]
        while(l < s.size()){
            if(cur <= maxCost) res = max(res, r - l + 1);

            if(cur <= maxCost && r + 1 < s.size()) cur += abs(s[++ r] - t[r]);
            else cur -= abs(s[l] - t[l ++]);
        }
        return res;
    }

