                  vector<vector<vector<long long>>>& dp){

        if(left == 0) return 1;
        if(index == n) return 0;
        if(dp[select][left][index] != -1) return dp[select][left][index];

        long long res = dfs(n, s, select, left, index + 1, dp);
        if(s[index] == (char)('0' + select))
