int bfs(int n, const vector<vector<int>>& g, int s){

        vector<int> dis(n, -1);
        queue<int> q;
        q.push(s);
        dis[s] = 0;
        int res = 0;
        while(!q.empty()){
            int u = q.front(); q.pop();

            for(int v: g[u])
                if(dis[v] == -1){
                    dis[v] = dis[u] + 1;
                    res = max(res, dis[v]);
                    q.push(v);
                }
        }
        return res;
    }

