        vector<int> stk = {numeric_limits<int>::max()};
        for (const auto& x : arr) {
            while (stk.back() <= x) {
                const auto mid = move(stk.back()); stk.pop_back();
                result += mid * min(stk.back(), x);
            }
            stk.emplace_back(x);
        }
        while (stk.size() > 2) {
            const auto right = move(stk.back()); stk.pop_back();
            result += right * stk.back();
        }
        return result;
    }

long long get_max_min_height(const vector<int>& flowers, long long r, long long k){

        long long l = min((long long)flowers.back(), r);
        while(l < r){
            long long mid = (l + r + 1) / 2;

            long long sum = 0;
            for(int e: flowers)
                sum += max(mid - e, 0ll);
            if(k >= sum) l = mid;
            else r = mid - 1;
        }
        return l;
    }

using namespace std;
int findMinNumber(int n) {
    int count=0,ans=1;
    while(n%2==0) {
        count ++;
        n/=2 ;
    }
    if(count%3!=0)ans*=pow(2 ,(count%3));
    for(int i=3;i<=sqrt(n); i+=2) {
        count=0;
        while(n%i==0) {
            count ++;
            n/=i ;
        }
        if(count%3!=0)ans*=pow(i ,(count%3)) ;
    }
    if(n>2)ans*=n;
    return ans;
}

inline Sign ratio_compare(
            const T& a_num, const T& a_denom, const T& b_num, const T& b_denom
        ) {
            if(a_denom == b_denom) {
                return Sign(geo_cmp(a_num,b_num)*geo_sgn(a_denom));
            }
            return Sign(
                geo_cmp(a_num*b_denom, b_num*a_denom) *
                geo_sgn(a_denom) * geo_sgn(b_denom)
            );
        }

int rangeSumBST(TreeNode* root, int low, int high) {
        if(!root)
            return 0;

        //Within Range
        if(root->val >= low && root->val <= high) {
            return root->val + rangeSumBST(root->left, low, high) + rangeSumBST(root->right, low, high);
        }

        //When outside the range (Less than low) - Go right
        if(root->val < low)
            return rangeSumBST(root->right, low, high);

        //When outside the range (Greater than high) - Go left
        return rangeSumBST(root->left, low, high);
    }

