}
int minOperations(int A,int B) {
    int cnt1=0,cnt2=0;
    cnt1+=countSetBits(A);
    cnt2+=countSetBits(B);
    if(( cnt1+cnt2)% 2!=0)return -1;
    int oneZero=0,zeroOne=0;
    int ans=0;
    for(int i=0;i<max(cnt1,cnt2); i ++) {
        int bitpos=1<<i;
        if(( !(bitpos&A)) &&(bitpos&B)) zeroOne ++;
        if(( bitpos&A)&&(!(bitpos&B)))oneZero++;
    }
    ans =(zeroOne/2)+(oneZero/2);
    if(zeroOne%2!=0)ans+=2;
    return ans;
}

