    for(int i=0;i<n;i ++)x=max(x,arr[i]);
    int ans=0;
    for(int i=0;i<n;i ++) {
        if(arr[i]!= x)continue;
        int j=i;
        while(arr[j]== x)j ++;
        ans=max(ans,j-i);
    }
    return ans;
}

