int dfs(const vector<int>& nums, int l, int r, vector<vector<int>>& dp){

        if(l == r) return dp[l][r] = 0;
        if(dp[l][r] != -1) return dp[l][r];

        int res = 0;
        for(int k = l + 1; k <= r - 1; k ++)
            res = max(res, dfs(nums, l, k, dp) + dfs(nums, k, r, dp) + nums[l] * nums[k] * nums[r]);
        return dp[l][r] = res;
    }

