inline double triangle_area(vec3 p1, vec3 p2, vec3 p3) {
        double Ux = p2.x - p1.x;
        double Uy = p2.y - p1.y;
        double Uz = p2.z - p1.z;
        double Vx = p3.x - p1.x;
        double Vy = p3.y - p1.y;
        double Vz = p3.z - p1.z;
        double Wx = Uy * Vz - Uz * Vy;
        double Wy = Uz * Vx - Ux * Vz;
        double Wz = Ux * Vy - Uy * Vx;
        return 0.5 * ::sqrt(Wx*Wx + Wy*Wy + Wz*Wz);
    }

