int hammingWeight(uint32_t n) {
        n = (n & 0x55555555) + ((n >> 1) & 0x55555555);
        n = (n & 0x33333333) + ((n >> 2) & 0x33333333);
        n = (n & 0x0F0F0F0F) + ((n >> 4) & 0x0F0F0F0F);
        n = (n & 0x00FF00FF) + ((n >> 8) & 0x00FF00FF);
        n = (n & 0x0000FFFF) + ((n >> 16) & 0x0000FFFF);
        return n;
    }

vector<long long int> productExceptSelf(vector<long long int> &nums, int n)
{
  vector<long long int> left(n), right(n), ans(n);

  long long prod = 1;
  for (int i = 0; i < n; ++i)
  {
    left[i] = prod;
    prod *= nums[i];
  }

  prod = 1;
  for (int i = n - 1; i >= 0; --i)
  {
    right[i] = prod;
    prod *= nums[i];
  }

  for (int i = 0; i < n; ++i)
    ans[i] = left[i] * right[i];
  return ans;
}

int fourSumCount(vector<int>& A, vector<int>& B, vector<int>& C, vector<int>& D) {

        unordered_map<int,int> hashtable1;
        unordered_map<int,int> hashtable2;

        for(int i = 0 ; i < A.size() ; i ++)
            for(int j = 0 ; j < B.size() ; j ++)
                hashtable1[A[i]+B[j]] += 1;

        for(int i = 0 ; i < C.size() ; i ++)
            for(int j = 0 ; j < D.size() ; j ++)
                hashtable2[C[i]+D[j]] += 1;

        int res = 0;
        for(unordered_map<int,int>::iterator iter = hashtable1.begin() ; iter != hashtable1.end() ; iter ++)
            if(hashtable2.find(-(iter->first)) != hashtable2.end())
                res += iter->second * hashtable2[-(iter->first)];

        return res;
    }

int numberOfArithmeticSlices(vector<int>& A) {
        int n = A.size();
        //min size is 3 for a series
        if(n < 3)
            return 0;
        int count = 0;

        vector<int> t(n, 0);

        for(int i = 2; i<n; i++) {
            if(A[i]-A[i-1] == A[i-1]-A[i-2]) {
                t[i] = 1 + t[i-1];
                count += t[i];
            }
        }

        return count;
    }

int maxDistance(vector<vector<int>>& arrays) {
        int MIN = arrays[0].front();
        int MAX = arrays[0].back();

        int result = 0;

        for(int i = 1; i < arrays.size(); i++) {
            int currMin = arrays[i].front();
            int currMax = arrays[i].back();

            result = max({result, abs(currMin - MAX), abs(currMax - MIN)});

            MAX = max(MAX, currMax);
            MIN = min(MIN, currMin);
        }
        return result;
    }

