int minLength(string str,int len) {
    stack<char>s;
    for(int i=0;i<len;i ++) {
        if(s.empty()) {
            s.push(str[i]) ;
        }
        else {
            char c=s.top();
            if(c!=str[i]&& toupper(c)== toupper(str[i])) {
                s.pop() ;
            }
            else {
                s.push(str[i]) ;
            }
        }
    }
    return s.size();
}

