float cal_cos(float n) {
    float accuracy=0.0001,x1,denominator,cosx,cosval;
    n=n *(3.142/180.0);
    x1=1;
    cosx=x1;
    cosval=cos(n);
    int i=1;
    do {
        denominator=2*i *(2*i-1);
        x1 =-x1*n*n/denominator;
