vector<vector<int>> findRLEArray(vector<vector<int>>& encoded1, vector<vector<int>>& encoded2) {

        vector<vector<int>> res;
        int i = 0, j = 0;
        while(i < encoded1.size() && j < encoded2.size()){

            int f = min(encoded1[i][1], encoded2[j][1]);
            int v = encoded1[i][0] * encoded2[j][0];
            if(!res.empty() && res.back()[0] == v) res.back()[1] += f;
            else res.push_back({v, f});

            encoded1[i][1] -= f;
            if(encoded1[i][1] == 0) i ++;

            encoded2[j][1] -= f;
            if(encoded2[j][1] == 0) j ++;
        }
        return res;
    }

int findTheLongestSubstring(string s) {

        unordered_map<char, int> vowels = {{'a', 0}, {'e', 1}, {'i', 2}, {'o', 3}, {'u', 4}};

        int state = 0;
        vector<int> pos(1 << 5, -1);
        vector<bool> visited(1 << 5, false);
        visited[0] = true;
        int res = 0;
        for(int i = 0; i < s.size(); i ++){
            if(vowels.count(s[i])) {
                if(state & (1 << vowels[s[i]])) state -= (1 << vowels[s[i]]);
                else state += (1 << vowels[s[i]]);
            }
            if(visited[state]) res = max(res, i - pos[state]);
            else pos[state] = i, visited[state] = true;
        }
        return res;
    }

