vector<int> under(const vector<int>& A, double x){
        int res = 0;
        double max_frac = 0.0;
        int num, denom;
        for(int j = 1 ; j < A.size() ; j ++)
            for(int i = 0 ; i < j ; i ++){
                double frac = (double)A[i] / A[j];
                if(frac < x){
                    res ++;
                    if(frac > max_frac){
                        max_frac = frac;
                        num = A[i];
                        denom = A[j];
                    }
                }
                else
                    break;
            }

        return {res, num, denom};
    }

bool isMonotonic(vector<int>& A) {

        int trend = 0;
        for(int i = 1; i < A.size() ; i ++)
            if(trend == 0){
                if(A[i] > A[i - 1]) trend = 1;
                else if(A[i] < A[i - 1]) trend = -1;
            }
            else{
                if(A[i] > A[i - 1] && trend == -1) return false;
                else if(A[i] < A[i - 1] && trend == 1) return false;
            }

        return true;
    }

