int minCostII(vector<vector<int>>& costs) {

        int n = costs.size(), k = costs[0].size();

        vector<vector<int>> dp(n, vector<int>(k, INT_MAX));
        dp[0] = costs[0];
        for(int i = 1; i < n; i ++)
            for(int j = 0; j < k; j ++){
                for(int kk = 0; kk < k; kk ++)
                    if(kk != j) dp[i][j] = min(dp[i][j], dp[i - 1][kk] + costs[i][j]);
            }
        return *min_element(dp.back().begin(), dp.back().end());
    }

int meetRequirement(int n, vector<vector<int>>& lights, vector<int>& requirement) {

        vector<int> diff(n + 1, 0);
        for(const vector<int>& light: lights){
            int pos = light[0], range = light[1];
            int l = max(0, pos - range), r = min(n - 1, pos + range);

            diff[l] += 1, diff[r + 1] -= 1;
        }

        int cur = 0, res = 0;
        for(int i = 0; i < n; i ++){
            cur += diff[i];
            res += (cur >= requirement[i]);
        }
        return res;
    }

