bool validateStackSequences(vector<int> &pushed, vector<int> &popped)
  {
    stack<int> s;
    int i = 0, j = 0, n = pushed.size();

    while (i < n)
    {
      s.push(pushed[i]);
      i++;

      while (s.size() && j >= 0 && j < n && s.top() == popped[j])
      {
        s.pop();
        j++;
      }
    }

    while (s.size() && j >= 0 && j < n && s.top() == popped[j])
    {
      s.pop();
      j++;
    }

    return s.size() == 0;
  }

