int candy(vector<int> &A)
  {
    int n = A.size(), ans = 0;
    vector<int> candies(n, 1);

    for (int i = 1; i < n; ++i)
    {
      if (A[i] > A[i - 1])
        candies[i] = 1 + candies[i - 1];
    }

    for (int i = n - 2; i >= 0; --i)
    {
      if (A[i] > A[i + 1])
        candies[i] = max(candies[i], candies[i + 1] + 1);
    }

    for (auto &i : candies)
      ans += i;
    return ans;
  }

