int solve(int n, const string& s, char max_c, char min_c, bool reverse = false){

        vector<int> v(n);
        if(!reverse){
            for(int i = 0; i < n; i ++)
                v[i] = ((s[i] == max_c ? 1 : (s[i] == min_c ? -1 : 0)));
        }
        else{
            for(int i = n - 1; i >= 0; i --)
                v[n - 1 - i] = (s[i] == max_c ? 1 : (s[i] == min_c ? -1 : 0));
        }

        int res = 0, cur = 0;
        bool hit_neg = false;
        for(int e: v){
            if(cur + e >= 0){
                cur += e;
                if(e < 0) hit_neg = true;
                if(hit_neg) res = max(res, cur);
            }
            else cur = 0, hit_neg = false;
        }
        return res;
    }

std::vector<uint64_t> N_bonacci(const uint64_t &n, const uint64_t &m) {
    std::vector<uint64_t> a(
        m, 0);  // we create an array of size m filled with zeros
    if (m < n || n == 0) {
        return a;
    }

    a[n - 1] = 1;  /// we initialise the (n-1)th term as 1 which is the sum of
                   /// preceding N zeros
    if (n == m) {
        return a;
    }
    a[n] = 1;  /// similarily the sum of preceding N zeros and the (N+1)th 1 is
               /// also 1
    for (uint64_t i = n + 1; i < m; i++) {
        // this is an optimized solution that works in O(M) time and takes O(M)
        // extra space here we use the concept of the sliding window the current
        // term can be computed using the given formula
        a[i] = 2 * a[i - 1] - a[i - 1 - n];
    }
    return a;
}

int countLatticePoints(vector<vector<int>>& circles) {

        int minx = INT_MAX, maxx = INT_MIN, miny = INT_MAX, maxy = INT_MIN;
        for(const vector<int>& circle: circles){
            int x = circle[0], y = circle[1], r = circle[2];
            minx = min(minx, x - r), maxx = max(maxx, x + r);
            miny = min(miny, y - r), maxy = max(maxy, y + r);
        }

        int res = 0;
        for(int x = minx; x <= maxx; x ++)
            for(int y = miny; y <= maxy; y ++){
                bool ok = false;
                for(const vector<int>& circle: circles){
                    int x0 = circle[0], y0 = circle[1], r0 = circle[2];
                    if((x - x0) * (x - x0) + (y - y0) * (y - y0) <= r0 * r0){
                        ok = true;
                        break;
                    }
                }
                res += ok;
            }
        return res;
    }

int minFallingPathSum(vector<vector<int>>& A) {

        int m = A.size();
        if(m == 0) return 0;

        int n = A[0].size();
        vector<vector<int>> dp(m, vector<int>(n, INT_MAX));

        dp[0] = A[0];
        for(int i = 1; i < m; i ++)
            for(int j = 0; j < n; j ++)
                for(int k = max(j - 1, 0); k <= min(n - 1, j + 1); k ++)
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + A[i][j]);

        return *min_element(dp[m - 1].begin(), dp[m - 1].end());
    }

inline
Gmpzf approximate_sqrt(const Gmpzf &f)
{
  // is there a well-defined sqrt at all?? Here we do the
  // following: write *this as m * 2 ^ e with e even, and
  // then return sqrt(m) * 2 ^ (e/2)
  Gmpzf result;
  // make exponent even
  if (f.exp() % 2 == 0) {
    mpz_set (result.man(), f.man());
  } else {
    mpz_mul_2exp (result.man(), f.man(), 1);
  }
  mpz_sqrt(result.man(), result.man());
  result.e = f.exp() / 2;
  result.canonicalize();
  return result;
}

