int maxTurbulenceSize(vector<int>& arr) {
        int n = arr.size();

        // dp[i] -> { current is lesser than prev, current is bigger than prev  }
        vector<vector<int>> dp(n, vector<int> (2, 1));
        int ans = 1;

        for(int i = 1; i < n; ++i) {
            if(arr[i] < arr[i-1]) dp[i][0] = 1 + dp[i-1][1];
            if(arr[i] > arr[i-1]) dp[i][1] = 1 + dp[i-1][0];

            ans = max({ans, dp[i][0], dp[i][1]});
        }

        return ans;
    }

int minOperations(vector<int>& nums, int k) {
        vector<bool> lookup(k);
        int i = size(nums) - 1;
        for (; i >= 0; --i) {
            if (nums[i] > size(lookup) || lookup[nums[i] - 1]) {
                continue;
            }
            lookup[nums[i] - 1] = true;
            if (!--k) {
                break;
            }
        }
        return size(nums) - i;
    }

int maxSumAfterPartitioning(vector<int>& A, int K) {

        vector<int> dp(A.size());
        for(int i = 0; i < A.size(); i ++){

            int curMax = 0;
            for(int k = 1; k <= K && i - k + 1 >= 0; k ++){
                curMax = max(curMax, A[i - k + 1]);
                dp[i] = max(dp[i], (i >= k ? dp[i - k] : 0) + curMax * k);
            }
        }
        return dp[A.size() - 1];
    }

