int MFS(vector<vector<int>>& A, int row, int col, vector<vector<int>>& t) {
        if(row == A.size()-1)
            return A[row][col];
        if(t[row][col] != -1)
            return t[row][col];

        int minSum = INT_MAX;

        for(int shift = -1; shift<=1; shift++) {
            if(col + shift >=0 && col+shift < A[row].size()) {
                minSum = min(minSum, A[row][col] + MFS(A, row+1, col+shift, t));
            }
        }

        return t[row][col] = minSum;
    }

int surfaceArea(vector<vector<int>>& grid) {
        int result = 0;
        for (int i = 0; i < grid.size(); ++i) {
            for (int j = 0; j < grid.size(); ++j) {
                if (grid[i][j]) {
                    result += grid[i][j] * 4 + 2;
                }
                if (i) {
                    result -= min(grid[i][j], grid[i - 1][j]) * 2;
                }
                if (j) {
                    result -= min(grid[i][j], grid[i][j - 1]) * 2;
                }
            }
        }
        return result;
    }

int minOperations(vector<int>& nums) {
        stack<int> st;

        int ops = 0;

        for(int i = 0; i < nums.size(); i++) {
            while(!st.empty() && st.top() > nums[i]) {
                st.pop();
            }

            if(nums[i] == 0)
                continue;

            if(st.empty() || st.top() < nums[i]) {
                st.push(nums[i]);
                ops++;
            }
        }

        return ops;
    }

