bool IsWellFormed(const string& s) {
  stack<char> left_chars;
  const unordered_map<char, char> kLookup = {
      {'(', ')'}, {'{', '}'}, {'[', ']'}};
  for (int i = 0; i < size(s); ++i) {
    if (kLookup.count(s[i])) {
      left_chars.emplace(s[i]);
    } else {
      if (empty(left_chars) || kLookup.at(left_chars.top()) != s[i]) {
        // Unmatched right char or mismatched chars.
        return false;
      }
      left_chars.pop();
    }
  }
  return empty(left_chars);
}

int maximumSum(vector<int>& arr) {

        int n = arr.size();
        if(n == 1) return arr[0];

        int undropped = max(arr[0] + arr[1], arr[1]);
        int dropped = max(arr[0], arr[1]);
        int res = max(undropped, dropped);
        for(int i = 2; i < n; i ++){
            dropped = max(undropped, dropped + arr[i]);
            res = max(res, dropped);

            if(undropped <= 0) undropped = arr[i];
            else undropped = arr[i] + undropped;
            res = max(res, undropped);
        }
        return res;
    }

