void nextPermutation(vector<int>& nums) {
        int N = nums.size();
        int id = -1;
        for(int i=N-2; i >= 0; i--) {
            if(nums[i] < nums[i+1]) {
                id = i;
                break;
            }
        }

        // it is already decreasing order
        reverse(nums.begin() + id + 1, nums.end());

        // we have whole array as decreasing
        if(id == -1) return;

        auto it = upper_bound(nums.begin() + id + 1, nums.end(), nums[id]);
        swap(nums[id], *it);

        return;
    }

