std::uint16_t KnapSackFilling(std::uint16_t i, std::uint16_t W,
                              const std::vector<std::uint16_t>& val,
                              const std::vector<std::uint16_t>& wt,
                              std::vector<std::vector<int>>& dp) {
    if (i == 0) {
        if (wt[0] <= W) {
            return (W / wt[0]) *
                   val[0];  // Take as many of the first item as possible
        } else {
            return 0;  // Can't take the first item
        }
    }
    if (dp[i][W] != -1)
        return dp[i][W];  // Return result if available

    int nottake =
        KnapSackFilling(i - 1, W, val, wt, dp);  // Value without taking item i
    int take = 0;
    if (W >= wt[i]) {
        take = val[i] + KnapSackFilling(i, W - wt[i], val, wt,
                                        dp);  // Value taking item i
    }
    return dp[i][W] =
               std::max(take, nottake);  // Store and return the maximum value
}

inline bool open_or_create_shared_directory(const char *path)
{
   const ::mode_t m = ::mode_t(01777);
   const bool created = ::mkdir(path, m) == 0;
   const bool created_or_exists = created || (errno == EEXIST);
   //Try to maximize the chance that the sticky bit is set in shared dirs
   //created with old versions that did not set it (for security reasons)
   const bool chmoded = ::chmod(path, m) == 0;
   return created ? chmoded : created_or_exists;
}

TreeNode *deleteNode(TreeNode *root, int key)
  {
    if (!root)
      return root;
    else if (root->val > key)
      root->left = deleteNode(root->left, key);
    else if (root->val < key)
      root->right = deleteNode(root->right, key);
    else
    {
      if (!root->left)
        return root->right;
      if (!root->right)
        return root->left;

      auto curr = root->right;
      while (curr->left)
        curr = curr->left;

      root->val = curr->val;
      root->right = deleteNode(root->right, root->val);
    }

    return root;
  }

