int findLengthOfShortestSubarray(vector<int>& arr) {

        int n = arr.size();

        int j = n - 1;
        while(j - 1 >= 0 && arr[j - 1] <= arr[j]) j --;

        int res = n - j;
        for(int i = 0; i < n && (i == 0 || arr[i] >= arr[i - 1]); i ++){
            res = max(res, i + 1);
            while(j < n && (i == j || arr[i] > arr[j])) j ++;
            if(j < n) res = max(res, i + 1 + (n - j));
        }
        return n - res;
    }

