int solve(vector<int> &nums, int s, int e)
  {
    int n = e - s + 1;

    if (n == 0)
      return 0;
    vector<int> dp(n, 0);

    dp[0] = nums[s];
    dp[1] = max(nums[s], nums[s + 1]);

    for (int i = s + 2; i <= e; ++i)
      dp[i - s] = max(dp[i - s - 1], dp[i - s - 2] + nums[i]);

    return dp[e - s];
  }

