int largestAltitude(int L,int B) {
    if(L>B) {
        swap(B,L);
    }
    int low=0,high=L;
    int res=0;
    while(low<=high) {
        int mid=low +(high-low)/ 2;
        if(mid <=(B/2)) {
            res=mid;
            low=mid+1 ;
        }
        else high=mid-1 ;
    }
    return res;
}

TreeNode* insertIntoBST(TreeNode* root, int val) {

        if(!root) return new TreeNode(val);

        TreeNode* p = root;
        while(true){
            if(val < p->val){
                if(!p->left){
                    p->left = new TreeNode(val);
                    break;
                }
                p = p->left;
            }
            else{
                if(!p->right){
                    p->right = new TreeNode(val);
                    break;
                }
                p = p->right;
            }
        }
        return root;
    }

void bfs(int start, unordered_map<int, vector<int>> &adj, int id,
             vector<int>& nodeId, unordered_map<int, set<int>>& mp,
             vector<bool>& visited) {

        queue<int> q;
        q.push(start);
        visited[start] = true;
        nodeId[start] = id;
        mp[id].insert(start);

        while (!q.empty()) {
            int node = q.front();
            q.pop();

            for (int &ngbr : adj[node]) {
                if (!visited[ngbr]) {
                    visited[ngbr] = true;
                    nodeId[ngbr] = id;
                    mp[id].insert(ngbr);
                    q.push(ngbr);
                }
            }
        }
    }

