int NumberOfWaysSpaceEfficient(int n, int m) {
  if (n < m) {
    swap(n, m);
  }

  vector<int> table(m, 1);
  for (int i = 1; i < n; ++i) {
    int prev_res = 0;
    if (n < m) {
      swap(n, m);
    }
    for (int j = 0; j < m; ++j) {
      table[j] = table[j] + prev_res;
      prev_res = table[j];
    }
  }
  return table[m - 1];
}

