int islandPerimeter(vector<vector<int>>& grid) {
        int ans = 0;
        const int dirx[] = {0, 0, -1, 1}, diry[] = {-1, 1, 0, 0};

        for (int i = 0; i < grid.size(); ++i) {
            for (int j = 0; j < grid[0].size(); ++j) {
                if (grid[i][j]) {
                    int cnt = 0;

                    for (int k = 0; k < 4; ++k) {
                        int x = i+dirx[k], y = j+diry[k];

                        if (x >= 0 && x < grid.size() &&
                           y >= 0 && y < grid[0].size() &&
                           grid[x][y])
                            ++cnt;
                    }

                    ans += 4-cnt;
                }
            }
        }

        return ans;
    }

