int longestMonotonicSubarray(vector<int>& nums) {
        int n = nums.size();

        int result = 1;
        int increasing = 1;
        int decreasing = 1;
        //{3, 2, 1}
        for(int i = 1; i < n; i++) {
            if(nums[i] > nums[i-1]) {
                increasing++;
                decreasing = 1;
                result = max(result, increasing);
            } else if(nums[i] < nums[i-1]) {
                decreasing++;
                increasing = 1;
                result = max(result, decreasing);
            } else {
                increasing = 1;
                decreasing = 1;
            }
        }

        return result;
    }

uint64_t bit_twiddle_permute(uint64_t v) {
  uint64_t t = v | (v - 1);
  uint64_t u = ((~t & -~t) - 1);
  int shift = __builtin_ctzl(v) + 1;
  // Shifting by 64 bits or more is undefined behaviour, so we must avoid it.
  // See for example: http://c0x.coding-guidelines.com/6.5.7.html (1185).
  u = (shift < 64) ? (u >> shift) : 0;
  uint64_t w = (t + 1) | u;
  return w;
}

