    int l=0;
    int r=k;
    int ans=0;
    while(l<=r) {
        int mid=l +(r-l)/ 2;
        if(pow(((mid *(mid+1))/2), 2)>= k) {
            ans=mid;
            r=mid-1 ;
        }
        else {
            l=mid+1 ;
        }
    }
    return ans;
