const char * str_token(const char ** str, const char * space)
{
    unsigned span;
    char * token;
    for (; **str != 0; *str += 1)
    {
        if (0 == strchr(space, **str))
        {
            break;
        }
    }
    span = strcspn(*str, space);
    token = (char *)malloc(span+1);
    strncpy(token, *str, span);
    token[span] = 0;
    for (*str += span; **str != 0; *str += 1)
    {
        if (0 == strchr(space, **str))
        {
            break;
        }
    }
    return token;
}

