int findMaxForm(vector<string>& strs, int m, int n) {

        vector<vector<int>> dp(m + 1 , vector<int>(n + 1, 0));
        for(int i = 0 ; i < strs.size() ; i ++){
            int mcost = 0, ncost = 0;
            for(char c: strs[i])
                if(c == '0')
                    mcost ++;
                else
                    ncost ++;

            for(int u = m ; u >= mcost ; u --)
                for(int v = n ; v >= ncost ; v --)
                    dp[u][v] = max(dp[u][v] , 1 + dp[u - mcost][v - ncost]);
        }
        return dp[m][n];
    }

