int maxNormalSubstring(string&P,set<char>Q,int K,int N) {
    if(K==0)return 0;
    int count=0;
    int left=0,right=0;
    int ans=0;
    while(right<N) {
        while(right<N&&count<=K) {
            if(Q.find(P[right])!=Q.end()) {
                if(count+1>K)break;
                else count++;
            }
            right ++;
            if(count<=K)ans=max(ans,right-left);
        }
        while(left<right) {
            left ++;
            if(Q.find(P[left-1])!=Q.end())count --;
            if(count<K)break ;
        }
    }
    return ans;
}

