int maximumProfit(vector<int>& present, vector<int>& future, int budget) {

        int n = present.size();

        vector<int> values, weight;
        for(int i = 0; i < n; i ++)
            if(future[i] > present[i] && present[i] <= budget){
                values.push_back(future[i] - present[i]);
                weight.push_back(present[i]);
            }

        vector<int> dp(budget + 1, 0);
        for(int i = 0; i < values.size(); i ++){
            vector<int> tdp = dp;
            for(int j = budget; j >= weight[i]; j --)
                tdp[j] = max(tdp[j], tdp[j - weight[i]] + values[i]);
            dp = tdp;
        }
        return dp.back();
    }

void addValue(int pos, float val, float* vals, T* point, T* points, int n)
{
    vals[pos] = val;
    for (int i=0; i<n; ++i) {
        points[pos*n+i] = point[i];
    }

    // bubble down
    int j=pos;
    while (j>0 && vals[j]<vals[j-1]) {
        swap(vals[j],vals[j-1]);
        for (int i=0; i<n; ++i) {
            swap(points[j*n+i],points[(j-1)*n+i]);
        }
        --j;
    }
}

