Node *findIntersection(Node *head1, Node *head2)
{
  auto curr1 = head1, curr2 = head2;
  Node *newHead = new Node(-1);
  auto temp = newHead;

  while (curr1 && curr2)
  {
    if (curr1->data == curr2->data)
    {
      Node *newNode = new Node(curr1->data);
      temp->next = newNode;
      temp = temp->next;
      curr1 = curr1->next;
      curr2 = curr2->next;
    }
    else if (curr1->data < curr2->data)
      curr1 = curr1->next;
    else
      curr2 = curr2->next;
  }

  return newHead->next;
}

