bool containsNearbyDuplicate(vector<int>& nums, int k) {
        unordered_map<int, int> lookup;
        for (int i = 0; i < nums.size(); ++i) {
            if (lookup.find(nums[i]) == lookup.end()) {
                lookup[nums[i]] = i;
            } else {
                // If the value occurs before, check the difference.
                if (i - lookup[nums[i]] <= k) {
                    return true;
                }
                // Update the index of the value.
                lookup[nums[i]] = i;
            }
        }
        return false;
    }

int dfs(TreeNode* node, int t){

        if(!node) return 0;

        int rsum = dfs(node->right, t);
        int lsum = dfs(node->left, node->val + rsum + t);
        int ret = lsum + rsum + node->val;
        node->val += rsum + t;
        return ret;
    }

