int minimumCost(int N, vector<vector<int>>& connections) {

        vector<unordered_map<int, int>> g(N);
        for(vector<int>& c: connections){
            g[--c[0]].count(--c[1]);
            if(!g[c[0]].count(c[1]) || c[2] < g[c[0]][c[1]]){
                g[c[0]][c[1]] = c[2];
                g[c[1]][c[0]] = c[2];
            }
        }

        sort(connections.begin(), connections.end(),
             [](const vector<int>& e1, const vector<int>& e2){
                 return e1[2] < e2[2];
        });

        int res = 0;
        UF uf(N);
        for(const vector<int>& e: connections)
            if(!uf.isConnected(e[0], e[1])){
                uf.unionElements(e[0], e[1]);
                res += e[2];
            }
        return uf.size() == 1 ? res : -1;
    }

int search(vector<int>& nums, int target) {
        int left = 0, right = nums.size() - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                return mid;
            } else if ((nums[mid] >= nums[left] && nums[left] <= target && target < nums[mid]) ||
                       (nums[mid] < nums[left] && !(nums[mid] < target && target <= nums[right]))) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return -1;
    }

