int minCost(vector<int>a,int i,int j,int k,vector<int>prefix,vector<vector<int>>dp) {
    if(i>=j)return 0;
    if(dp[i ][j]!= -1)return dp[i ][j];
    int best_cost=inf;
    for(int pos=i;pos<j;pos ++) {
        int left=minCost(a,i,pos,k,prefix,dp);
        int right=minCost(a,pos+1,j,k,prefix,dp);
        best_cost=min(best_cost,left+right +(k*Combine(prefix,i,j)));
    }
    return dp[i ][j]= best_cost;
}

