int maxResult(vector<int>& nums, int k) {

        int n = nums.size();
        vector<int> dp(n, nums[0]);

        deque<int> q;
        q.push_back(0);

        for(int i = 1; i < nums.size(); i ++){

            dp[i] = nums[i] + dp[q.front()];
            while(!q.empty() && dp[q.back()] <= dp[i]) q.pop_back();
            q.push_back(i);

            while(!q.empty() && q.front() <= i - k)
                q.pop_front();
        }
        return dp.back();
    }

