int maximumLength(vector<int>& nums, int k) {
        vector<unordered_map<int, int>> dp(k + 1);
        vector<int> result(k + 1);
        for (const auto& x : nums) {
            for (int i = k; i >= 0; --i) {
                dp[i][x] = max(dp[i][x], i - 1 >= 0 ? result[i - 1] : 0) + 1;
                result[i] = max(result[i], dp[i][x]);
            }
        }
        return result[k];
    }

