void dfs2(const vector<vector<int>>& g, int u, int p, const vector<int>& dp, const string& s,
              int& res){

        vector<int> len;
        for(int v: g[u]){
            if(v == p) continue;
            dfs2(g, v, u, dp, s, res);
            if(s[u] != s[v])
                len.push_back(dp[v]);
        }

        if(len.size() == 0)
            res = max(res, 1);
        else if(len.size() == 1)
            res = max(res, len[0] + 1);
        else{
            sort(len.begin(), len.end(), greater<int>());
            res = max(res, len[0] + len[1] + 1);
        }
    }

