bool isValidSerialization(string preorder) {

        vector<int> data;
        for(int start = 0, i = 1; i <= preorder.size(); i ++)
            if(i == preorder.size() || preorder[i] == ','){
                if(preorder[start] == '#')
                    data.push_back(-1);
                else
                    data.push_back(atoi(preorder.substr(start, i - start).c_str()));

                start = i + 1;
                i = start;
            }

        int slots = 1;
        for(int e: data){
            slots --;
            if(slots < 0) return false;

            if(e != -1) slots += 2;

        }
        return slots == 0;
    }

string crackSafe(int n, int k) {
        const int M = pow(k, n - 1);
        vector<int> P;
        for (int i = 0; i < k; ++i) {
            for (int q = 0; q < M; ++q) {
                P.emplace_back(q * k + i);  // rotate: i*k^(n-1) + q => q*k + i
            }
        }
        const int total = pow(k, n);
        string result(n - 1, '0' + k - 1);
        for (int i = 0; i < total; ++i) {
            int j = i;
            // concatenation in lexicographic order of Lyndon words
            while (P[j] >= 0) {
                result.push_back('0' + j / M);
                auto Pj = P[j];
                P[j] = -1;
                j = Pj;
            }
        }
        return result;
    }

int gcd_impl(int a, int b) {
    if (b == 0) {
        return a;
    }
    if (b == 1) {
        return 1;
    }
    int remainder = a % b;

    if (remainder == 0) {
        return b;
    }
