int sb(int arr[], int n, int x)
{
  int curr_sum = 0, min_len = n + 1;
  int start = 0, end = 0;

  while (end < n)
  {
    while (curr_sum <= x && end < n)
    {
      curr_sum += arr[end];
      end++;
    }

    while (curr_sum > x && start < n)
    {
      min_len = min(min_len, end - start);
      curr_sum -= arr[start];
      start++;
    }
  }
  return min_len;
}

