        vector<vector<int>> dp(2, vector<int>(n + 1, 0));

        dp[0][0] = s[0] == 'b', dp[1][0] = s[0] == 'a';
        for(int i = 1; i < n; i ++){
            if(s[i] == 'a')
                dp[0][i] = dp[0][i - 1], dp[1][i] = dp[1][i - 1] + 1;
            else
                dp[0][i] = dp[0][i - 1] + 1, dp[1][i] = min(dp[0][i - 1], dp[1][i - 1]);
        }
        return min(dp[0][n - 1], dp[1][n - 1]);
    }

