    color[curr] = 1;

    while (pending.size())
    {
      auto curr = pending.front();
      pending.pop();
      for (auto &i : graph[curr])
      {
        if (color[i] != -1 && color[i] != 1 - color[curr])
          return false;
        else if (color[i] == -1)
        {
          color[i] = 1 - color[curr];
          pending.push(i);
        }
      }
    }
    return true;
  }

