bool dfs(map<int, vector<int>>& mp, int source, int destination, vector<bool>& inStack, vector<bool>& visited) {
        if(mp[source].size() == 0) {
            return source==destination;
        }
        inStack[source] = true;
        visited[source] = true;

        for(int &x : mp[source]) {
            if(inStack[x])
                return false;
            else if(!visited[x] && !dfs(mp, x, destination, inStack, visited))
                return false;
        }

        inStack[source] = false;
        return true;
    }

