int SpiralElement(int x,int y) {
    int r;
    if(x<y) {
        if(y%2==1) {
            r=y*y;
            return(r-x+1);
        }
        else {
            r =(y-1)*(y-1);
            return(r+x);
        }
    }
    else {
        if(x%2==0) {
            r=x*x;
            return(r-y+1);
        }
        else {
            r =(x-1)*(x-1);
            return(r+y);
        }
    }
}

