int maxSeg3(int a, int b, int c, int N) {
    vector<int> t(N+1, -1);
    //t[i] = max # of segments from ribbon of length i
    t[0] = 0;
    for(int i = 0; i<N+1; i++) {
        if(t[i] == -1)
            continue;
        if(i+a < N+1)
            t[i+a] = max(t[i+a], 1 + t[i]);
        if(i+b < N+1)
            t[i+b] = max(t[i+b], 1 + t[i]);
        if(i+c < N+1)
            t[i+c] = max(t[i+c], 1 + t[i]);
    }
    return t[N];
}

