void findMinRemove(const string& s, int *left_removed, int *right_removed) {
        // Calculate the minimum left and right parantheses to remove.
        for (const auto& c : s) {
            if (c == '(') {
                ++(*left_removed);
            } else if (c == ')') {
                if (!(*left_removed)) {
                    ++(*right_removed);
                } else {
                    --(*left_removed);
                }
            }
        }
    }

void selectionSort(node*head) {
    node*temp=head;
    while(temp) {
        node*min=temp;
        node*r=temp->next;
        while(r) {
            if(min->data>r->data)min=r;
            r=r->next ;
        }
        int x=temp->data;
        temp->data=min->data;
        min->data=x;
        temp=temp->next ;
    }
}

