bool searchMatrix(vector<vector<int>> &matrix, int target)
  {
    if (!matrix.size() || !matrix[0].size())
      return false;
    int n = matrix.size(), m = matrix[0].size();
    int r = 0, c = m - 1;

    while (r < n && c >= 0)
    {
      if (matrix[r][c] == target)
        return true;
      else if (matrix[r][c] > target)
        c--;
      else
        r++;
    }

    return false;
  }

std::size_t longest_common_string_length(const std::string& string_a,
                                         const std::string& string_b) {
    const auto size_a = string_a.size();
    const auto size_b = string_b.size();
    std::vector<std::vector<std::size_t>> sub_sols(
        size_a + 1, std::vector<std::size_t>(size_b + 1, 0));

    const auto limit = static_cast<std::size_t>(-1);
    for (std::size_t pos_a = size_a - 1; pos_a != limit; --pos_a) {
        for (std::size_t pos_b = size_b - 1; pos_b != limit; --pos_b) {
            if (string_a[pos_a] == string_b[pos_b]) {
                sub_sols[pos_a][pos_b] = 1 + sub_sols[pos_a + 1][pos_b + 1];
            } else {
                sub_sols[pos_a][pos_b] = std::max(sub_sols[pos_a + 1][pos_b],
                                                  sub_sols[pos_a][pos_b + 1]);
            }
        }
    }

    return sub_sols[0][0];
}

int MaximumRevenueAlternativeHelper(
    const vector<int>& coins, int a, int b, const vector<int>& prefix_sum,
    vector<vector<int>>* maximum_revenue_for_range_ptr) {
  if (a > b) {
    return 0;
  } else if (a == b) {
    return coins[a];
  }

  vector<vector<int>>& maximum_revenue_for_range =
      *maximum_revenue_for_range_ptr;
  if (maximum_revenue_for_range[a][b] == -1) {
    maximum_revenue_for_range[a][b] =
        max(coins[a] + prefix_sum[b] - (a + 1 > 0 ? prefix_sum[a] : 0) -
                MaximumRevenueAlternativeHelper(coins, a + 1, b, prefix_sum,
                                                maximum_revenue_for_range_ptr),
            coins[b] + prefix_sum[b - 1] - (a > 0 ? prefix_sum[a - 1] : 0) -
                MaximumRevenueAlternativeHelper(coins, a, b - 1, prefix_sum,
                                                maximum_revenue_for_range_ptr));
  }
  return maximum_revenue_for_range[a][b];
}

