        vector<vector<int>> result;
        for (int i = 0; i < size(land); ++i) {
            for (int j = 0; j < size(land[0]); ++j) {
                if (land[i][j] != 1) {
                    continue;
                }
                int ni = i, nj = j;
                while (ni + 1 < size(land) && land[ni + 1][j]) {
                    ++ni;
                }
                while (nj + 1 < size(land[0]) && land[i][nj + 1]) {
                    ++nj;
                }
                for (int r = i; r <= ni; ++r) {
                    for (int c = j; c <= nj; ++c) {
                        land[r][c] = -1;
                    }
                }
                result.push_back({i, j, ni, nj});
            }
        }
        return result;
    }

bool isIsomorphic(Node *root1, Node *root2)
{
  if (!root1 && !root2)
    return true;
  if (!root1 || !root2 || root1->data != root2->data)
    return false;

  auto l1 = root1->left, r1 = root1->right;
  auto l2 = root2->left, r2 = root2->right;

  return (isIsomorphic(l1, l2) && isIsomorphic(r1, r2)) ||
         (isIsomorphic(l1, r2) && isIsomorphic(r1, l2)) ||
         (isIsomorphic(r1, l2) && isIsomorphic(l1, r2));
}

