        for(int i = 0; i<n-1; i++) {
            pairSum[i] = weights[i] + weights[i+1];
        }

        sort(begin(pairSum), end(pairSum));
        long maxSum = 0;
        long minSum = 0;

        for(int i = 0; i<k-1; i++) {
