long long minimumReplacement(vector<int>& nums) {

        int n = nums.size();

        long long res = 0;
        int p = nums.back();
        for(int i = n - 2; i >= 0; i --){
            if(nums[i] <= p){
                p = min(p, nums[i]);
                continue;
            }

            int cnt = nums[i] / p;
            int mod = nums[i] % p;
            if(mod) cnt ++;

            res += (cnt - 1);
            p = min(p, nums[i] / cnt);
        }
        return res;
    }

