int largestInteger(int num) {
        const auto& count = [](auto num) {
            vector<int> cnt(10);
            for (; num; num /= 10) {
                ++cnt[num % 10];
            }
            return cnt;
        };

        auto cnt = count(num);
        int result = 0;
        vector<int> digit = {0, 1};
        for (int64_t base = 1; num; num /= 10, base *= 10) {
            const auto parity = (num % 10) % 2;
            for (; !cnt[digit[parity]] ; digit[parity] += 2);
            --cnt[digit[parity]];
            result += digit[parity] * base;
        }
        return result;
    }

int minimumDeviation(vector<int> &A)
  {
    int N = A.size();
    set<int> s;

    for (int i = 0; i < N; i++)
    {
      if (A[i] % 2 == 0)
        s.insert(A[i]);
      else
        s.insert(2 * A[i]);
    }

    int diff = *s.rbegin() - *s.begin();

    while ((int)s.size() && *s.rbegin() % 2 == 0)
    {
      int maxEl = *s.rbegin();
      s.erase(maxEl);
      s.insert(maxEl / 2);
      diff = min(diff, *s.rbegin() - *s.begin());
    }

    return diff;
  }

