int dfs(int l, int r, vector<vector<int>>& dp){

        if(l == r) return 0;
        if(l + 1 == r) return l;
        if(l + 2 == r) return l + 1;
        if(dp[l][r] != -1) return dp[l][r];

        int res = INT_MAX;
        for(int root = l + 1; root < r; root ++){
            res = min(res, root + max(dfs(l, root - 1, dp), dfs(root + 1, r, dp)));
        }
        return dp[l][r] = res;
    }

