int smallestNth(int A,int B,int N) {
    int res=INT_MAX;
    for(int i=1;i<N;i ++) {
        for(int j=N;j>i;j --) {
            if(( B-A)%(j-i)== 0) {
                int D =(B-A)/(j-i);
                int FirstTerm=A -(i-1)* D;
                int NthTerm=FirstTerm +(N-1)* D;
                if(FirstTerm>0)res=min(res,NthTerm);
            }
        }
    }
    return res;
}

