        if(max_value <= 0) return max_value;

        int n = nums.size(), res = 0;
        vector<int> dp(n);
        SegmentTree tree(n);
        for(int i = 0; i < n; i ++){
            dp[i] = nums[i];
            if(i) dp[i] = max(dp[i], nums[i] + tree.query(max(0, i - k), i - 1));
