        reverse(num2.begin(), num2.end());

        if(num1.size() < num2.size()) swap(num1, num2);
        while(num2.size() <= num1.size()) num2 += "0";

        string res = "";
        int carry = 0;
        for(int i = 0; i < num1.size(); i ++){
            int x = (num1[i] - '0') + (num2[i] - '0') + carry;
            res += string(1, '0' + x % 10);
