int maxTwoEvents(vector<vector<int>>& events) {

        sort(events.begin(), events.end());

        int n = events.size();
        vector<int> max_value(n, events.back()[2]);
        for(int i = n - 2; i >= 0; i --)
            max_value[i] = max(events[i][2], max_value[i + 1]);

        int res = 0;
        for(int i = 0; i < n; i ++){
            res = max(res, events[i][2]);

            vector<int> t = {events[i][1] + 1, INT_MIN, INT_MIN};
            vector<vector<int>>::iterator iter = lower_bound(events.begin(), events.end(), t);
            if(iter != events.end()){
                int index = iter - events.begin();
                res = max(res, events[i][2] + max_value[index]);
            }
        }
        return res;
    }

int dfs(const vector<int>& A, const vector<int>& B, int ai, int bj,
            unordered_map<int, vector<int>>& Apos,
            unordered_map<int, vector<int>>& Bpos,
            vector<vector<int>>& dp){

        if(ai >= A.size() || bj >= B.size())
            return 0;

        if(dp[ai][bj] != -1) return dp[ai][bj];

        int res = dfs(A, B, ai + 1, bj, Apos, Bpos, dp);
        for(int j: Bpos[A[ai]])
            if(j >= bj)
                res = max(res, 1 + dfs(A, B, ai + 1, j + 1, Apos, Bpos, dp));

        return dp[ai][bj] = res;
    }

