int sum_of_4_squares(int n) {
    int i,odd=0,even=0;
    for(i=1;i<=sqrt(n); i ++) {
        if(n%i==0) {
            if(i%2==0)even+=i;
            else odd+=i;
            if(( n/i)!= i) {
                if(( n/i)% 2==0)even +=(n/i);
                else odd +=(n/i);
            }
        }
    }
    if(n%2==1)return 8 *(odd+even);
    else return 24 *(odd);
}

