int mosaic(int n) {
    int i,ans=1;
    for(i=2;i<=n;i ++) {
        if(n%i==0&&n>0) {
            int count=0;
            while(n%i==0) {
                n/=i;
                count++;
            }
            ans*=count*i ;
        }
    }
    return ans ;
}
