string shiftingLetters(string s, vector<int> shifts) {
        shifts[shifts.size()-1] %= 26;

        for (int i = shifts.size()-2; i >= 0; --i) {
            shifts[i] = (shifts[i] % 26 + shifts[i+1] % 26) % 26;
        }

        for (int i = 0; i < s.size(); ++i) {
            int num = s[i] - 'a';
            num += shifts[i];
            num %= 26;
            s[i] = (num + 'a');
        }

        return s;
    }

