set<int> bfs(const vector<set<int>>& g, int s, int k){

        queue<int> q;
        vector<bool> visited(g.size(), false);
        vector<int> step(g.size(), 0);
        set<int> res;

        q.push(s);
        visited[s] = true;
        while(!q.empty()){
            int cur = q.front();
            q.pop();

            for(int next: g[cur])
                if(!visited[next]){
                    step[next] = step[cur] + 1;
                    visited[next] = true;
                    if(step[next] == k) res.insert(next);
                    q.push(next);
                }
        }
        return res;
    }

