const int INF=1e7;
int min_op(int cur,int M) {
    if(cur>M)return INF;
    if(cur==M)return 0;
    int op=INF;
    for(int i=2;i*i<=cur;i ++) {
        if(cur%i==0) {
            if(i%2==0) {
                op=min(op,1+min_op(cur+i,M)) ;
            }
            if(( cur/i)!= i &&(cur/i)% 2==0) {
                op=min(op,1+min_op(cur +(cur/i), M)) ;
            }
        }
    }
    return op ;
}
int min_operations(int N,int M) {
    int op=min_op(N,M);
    if(op>=INF)cout<<" - 1";
    else cout<<op<<" STR";
}

inline double sc_loop1(int32 in, int32 lo, int32 hi) {
    // avoid the divide if possible
    if (in >= hi) {
        in -= hi;
        if (in < hi)
            return in;
    } else if (in < lo) {
        in += hi;
        if (in >= lo)
            return in;
    } else
        return in;

    int32 range = hi - lo;
    return lo + range * (in - lo) / range;
}

void recurse(string s, int curr, vector<string> &ans)
  {
    if (curr == s.size())
    {
      ans.push_back(s);
      return;
    }

    if (isalpha(s[curr]))
    {
      string n1 = s, n2 = s;
      n1[curr] = toupper(n1[curr]);
      n2[curr] = tolower(n2[curr]);
      recurse(n2, curr + 1, ans);
