vector<int> maxSlidingWindow1(vector<int>& nums, int k) {
    vector<int> ret;

    if ((int)nums.size() < k)
        return ret;

    multiset<int> st;
    for (int i = 0; i < k; ++i) {
        st.insert(-nums[i]);
    }
    ret.push_back(-*st.begin());

    for (int i = k; i < (int)nums.size(); ++i) {
        st.erase(st.find(-nums[i-k]));
        st.insert(-nums[i]);
        ret.push_back(-*st.begin());
    }
    return ret;
}

