void copySetBitsInaRange(unsigned int &a, unsigned int b, unsigned int l, unsigned int r) {

    // assuming ints are stored using 32 bits
    if (l < 1 || r > 32) {
        return;
    }

    // for a given range
    for(int i=l; i<=r; i++){
        // Find a mask (a number whose only set bit is at i'th position)
        int mask = 1 << (i-1);

        // if i'th bit is set in y, set i'th bit in x also
        if (b & mask) {
            a = a | mask;
        }
    }
}

bool static IsCompressedOrUncompressedPubKey(const valtype &vchPubKey) {
    if (vchPubKey.size() < 33) {
        //  Non-canonical public key: too short
        return false;
    }
    if (vchPubKey[0] == 0x04) {
        if (vchPubKey.size() != 65) {
            //  Non-canonical public key: invalid length for uncompressed key
            return false;
        }
    } else if (vchPubKey[0] == 0x02 || vchPubKey[0] == 0x03) {
        if (vchPubKey.size() != 33) {
            //  Non-canonical public key: invalid length for compressed key
            return false;
        }
    } else {
        //  Non-canonical public key: neither compressed nor uncompressed
        return false;
    }
    return true;
}

int largestValsFromLabels(vector<int>& values, vector<int>& labels, int num_wanted, int use_limit) {

        vector<pair<int, int>> vec;
        for(int i = 0; i < values.size(); i ++)
            vec.push_back(make_pair(values[i], labels[i]));
        sort(vec.begin(), vec.end(), greater<pair<int, int>>());

        unordered_map<int, int> freq;
        int sum = 0, num = 0;
        for(const pair<int, int>& p: vec)
            if(freq[p.second] < use_limit){

                sum += p.first;
                num ++;
                freq[p.second] ++;
                if(num == num_wanted)
                    break;
            }
        return sum;
    }

