void setZeroes(vector<vector<int>>& matrix) {

        int m = matrix.size();
        if(!m) return;

        int n = matrix[0].size();
        if(!n) return;

        int sentinel = 2e9;
        for(int i = 0; i < m; i ++)
            for(int j = 0; j < n; j ++)
                if(matrix[i][j] == 0){
                    for(int k = 0; k < n; k ++)
                        if(matrix[i][k] != 0)
                            matrix[i][k] = sentinel;
                    for(int k = 0; k < m; k ++)
                        if(matrix[k][j] != 0)
                            matrix[k][j] = sentinel;
                }

        for(int i = 0; i < m; i ++)
            for(int j = 0; j < n; j ++)
                if(matrix[i][j] == sentinel)
                    matrix[i][j] = 0;
    }

