void sortColors(vector<int> &arr)
  {
    int i = 0, j = 0, k = arr.size() - 1;
    int n = arr.size();
    while (i < k && j <= k)
    {
      if (i < n && arr[i] == 0)
        i++;
      j = i;
      if (j > k)
        break;
      while (j < n && arr[j] == 1)
        j++;
      if (j > k)
        break;
      if (j < n && arr[j] == 0)
        swap(arr[i++], arr[j]);
      else if (j < n && arr[j] == 2)
        swap(arr[j], arr[k--]);
    }
  }

