void prop (node *at, int i, int j) {
    at->val += at->lazy * (j - i + 1);

    if (i != j) {
        if (!at->l)    at->l = new node();
        if (!at->r)    at->r = new node();

        at->l->lazy += at->lazy;
        at->r->lazy += at->lazy;
    }

    at->lazy = 0;
}

void rec(int from, int to, F& f, G& g, int& i, T& p, T q) {
    if (p == q) return;
    if (from == to) {
        g(i, to, p);
        i = to; p = q;
    } else {
        int mid = (from + to) >> 1;
        rec(from, mid, f, g, i, p, f(mid));
        rec(mid+1, to, f, g, i, p, q);
    }
}

