    if (length <= 0x7f)
    {
        bt.Put(byte(length));
        i++;
    }
    else
    {
        bt.Put(byte(BytePrecision(length) | 0x80));
        i++;
        for (int j=BytePrecision(length); j; --j)
        {
            bt.Put(byte(length >> (j-1)*8));
            i++;
        }
    }
    return i;
}

