int sqrtSearch(int low,int high,int N) {
    if(low<=high) {
        int mid =(low+high)/ 2;
        if(( mid*mid<=N)&&(( mid+1)*(mid+1)> N)) {
            return mid ;
        }
        else if(mid*mid<N) {
            return sqrtSearch(mid+1,high,N);
        }
        else {
            return sqrtSearch(low,mid-1,N);
        }
    }
    return low;
}

static void add_partial(int size, float* data, double partial, double amp, double phase) {
    if (amp == 0.0)
        return;
    double w = (partial * 2.0 * 3.1415926535897932384626433832795) / (double)size;
    for (int i = 0; i < size; ++i) {
        data[i] += amp * sin(phase);
        phase += w;
    }
}

