ll fib(ll n, ll mod) {
  if (n <= 1) return n;
  ll a = 0;
  ll b = 1;
  ll i = 1ll << (63 - __builtin_clzll(n) - 1);
  for (; i; i >>= 1) {
    ll na = (__int128(a) * a % mod + __int128(b) * b % mod) % mod;
    ll nb = __int128(2ll * a + b) * b % mod;
    a = na;
    b = nb;
    if (n & i) {
      ll c = a + b; if (c >= mod) c -= mod;
      a = b;
      b = c;
    }
  }
  return b;
}

