double largestSumOfAverages(vector<int>& nums, int k) {

        int n = nums.size();
        vector<vector<double>> dp(k + 1, vector<double>(n, 0.0));

        int sum = 0;
        for(int i = n - 1; i >= 0; i --){
            sum += nums[i];
            dp[1][i] = (double)sum / (n - i);
        }

        for(int seg = 2; seg <= k; seg ++){
            for(int l = 0; n - l >= seg; l ++){
                int sum = 0;
                for(int r = l; n - r >= seg; r ++){
                    sum += nums[r];
                    dp[seg][l] = max(dp[seg][l], (double)sum / (r - l + 1) + dp[seg - 1][r + 1]);
                }
            }
        }

        double res = dp[1][0];
        for(int seg = 2; seg <= k; seg ++) res = max(res, dp[seg][0]);
        return res;
    }

int play(const vector<int>& piles, int l, int r,
             vector<vector<int>>& dp){

        if(l == r) return piles[l];

        if(dp[l][r] != INT_MIN)
            return dp[l][r];

        int res = max(piles[l] - play(piles, l + 1, r, dp),
                      piles[r] - play(piles, l, r - 1, dp));
        return dp[l][r] = res;
    }

