int lengthOfLongestSubstring(string s) {

        int freq[256] = {0};

        int l = 0, r = -1; // sliding window: s[l...r]
        int res = 0;

        while(r + 1 < s.size()){

            if( freq[s[r + 1]] == 0 )
                freq[s[++r]] ++;
            else    //freq[s[r+1]] == 1
                freq[s[l++]] --;

            res = max(res, r - l + 1);
        }

        return res;
    }

using namespace std;
int exactPrimeFactorCount(int n) {
    int count=0;
    if(n%2==0) {
        count ++;
        while(n%2==0)n=n/2 ;
    }
    for(int i=3;i<=sqrt(n); i=i+2) {
        if(n%i==0) {
            count ++;
            while(n%i==0)n=n/i ;
        }
    }
    if(n>2)count ++;
    return count;
}

double myPow(double x, int n)
  {
    long long N = abs(n);
    double ans = 1.0;
    while (N > 0)
    {
      if (N % 2 == 1)
      {
        ans = ans * x;
        N--;
      }
      else
      {
        x = x * x;
        N = N / 2;
      }
    }

    if (n < 0)
      return 1.0 / ans;
    else
      return ans;
  }

