int rearrange(int n) {
    vector<int>hash_n(10,0);
    storeDigitCounts(n,hash_n);
    for(int mult=2;mult<10;mult ++) {
        int curr=n*mult;
        vector<int>hash_curr(10,0);
        storeDigitCounts(curr,hash_curr);
        if(equal(hash_n.begin(),hash_n.end(),hash_curr.begin())) return curr ;
    }
    return -1;
}

