using namespace std;
int findLongestSubstring(int posA,int posB,string&A,string&B,bool canSkip,int n,vector<vector<vector<int>>>&dp) {
    if(posA>=n posB>=n) {
        return 0 ;
    }
    if(dp[posA ][posB ][canSkip]!= -1) {
        return dp[posA ][posB ][canSkip];
    }
    int op1=0;
    int op2=0;
    int op3=0;
    if(A[posA]== B[posB]) {
        op1=1+findLongestSubstring(posA+1,posB+1,A,B,0,n,dp);
    }
    if(canSkip) {
        op2=findLongestSubstring(posA+1,posB,A,B,canSkip,n,dp);
    }
    op3=findLongestSubstring(posA,posB+1,A,B,canSkip,n,dp);
    return dp[posA ][posB ][canSkip]= max(op1,max(op2,op3)) ;
}
