int maxProfit(vector<int>& prices) {

        int n = prices.size();

        if(n <= 1)
            return 0;

        int hold = -prices[0], sell = 0, unhold = 0;

        for(int i = 1 ; i < n ; i ++){
            hold = max(hold, unhold - prices[i]);
            unhold = max(sell, unhold);
            sell = hold + prices[i];
        }

        return max(unhold, sell);
    }

