int maxResult(vector<int>& nums, int k) {

        int n = nums.size();
        vector<int> dp(n, nums[0]);

        map<int, int> tree;
        tree[nums[0]] ++;

        for(int i = 1; i < nums.size(); i ++){

            dp[i] = nums[i] + tree.rbegin()->first;
            tree[dp[i]] ++;

            if(i >= k){
                tree[dp[i - k]] --;
                if(tree[dp[i - k]] == 0) tree.erase(dp[i - k]);
            }
        }
        return dp.back();
    }

