ListNode *reverse(ListNode *head, ListNode *tail)
  {
    if (head == tail || !head || head->next == tail)
      return head;
    auto curr = head, prev = tail;
    while (curr && curr != tail)
    {
      auto next = curr->next;
      curr->next = prev;
      prev = curr;
      curr = next;
    }
    return prev;
  }

