void FloydWarshall(vector<vector<int>>* G_ptr) {
  vector<vector<int>>& graph = *G_ptr;
  for (int k = 0; k < size(graph); ++k) {
    for (int i = 0; i < size(graph); ++i) {
      for (int j = 0; j < size(graph); ++j) {
        if (graph[i][k] != numeric_limits<int>::max() &&
            graph[k][j] != numeric_limits<int>::max()) {
          graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j]);
        }
      }
    }
  }
}

vector<int> maxSlidingWindow(vector<int>& nums, int k) {

        if(k == 0 || nums.size() == 0)
            return vector<int>();

        if(k == 1) return nums;

        map<int, int> window;
        for(int i = 0; i < k - 1; i ++)
            window[nums[i]] ++;

        vector<int> res;
        for(int i = k - 1 ; i < nums.size() ; i ++){

            window[nums[i]] ++;
            res.push_back(window.rbegin()->first);

            window[nums[i - k + 1]] --;
            if(window[nums[i - k + 1]] == 0) window.erase(nums[i - k + 1]);
        }

        return res;
    }

