inline __attribute__((always_inline)) void AdjustScaleShlSaturate(TypeA* A, MYINT I, MYINT J, MYINT scale, MYINT saturate) {
    for (MYITE i = 0; i < I; i++) {
        for (MYITE j = 0; j < J; j++) {
            TypeA a = A[i * J + j];
            a = (a < saturate && a > -saturate) ? a : (a > 0 ? saturate : -saturate);
            A[i * J + j] = a * scale;
        }
    }
    return;
}

