int minDays(vector<int >&arr,int n,int k) {
    int l=arr.size(),left=1,right=1e9;
    if(n*k>l)return -1;
    while(left<right) {
        int mid =(left+right)/ 2,cnt=0,product=0;
        for(int j=0;j<l;++ j) {
            if(arr[j]> mid) {
                cnt=0 ;
            }
            else if(++ cnt>=k) {
                product ++;
                cnt=0 ;
            }
        }
        if(product<n) {
            left=mid+1 ;
        }
        else {
            right=mid ;
        }
    }
    return left;
}

