int maximumBeauty(vector<int>& nums, int k) {
        vector<pair<int, int>> ranges;
        for (int num : nums) {
            ranges.push_back({num - k, num + k});
        }

        sort(ranges.begin(), ranges.end());

        int maxBeauty = 0;
        deque<int> deq; //You can use queue as well - See my video above

        //NOTE : The intervals have equal size and hence this approach works like a charm.
        //If the intervals didn't have equal size, then it will fail in some cases.
        for (const auto& range : ranges) {
            while (!deq.empty() && deq.front() < range.first) {
                deq.pop_front();
            }

            deq.push_back(range.second);

            maxBeauty = max(maxBeauty, (int)deq.size());
        }

        return maxBeauty;
    }

TreeNode *trimBST(TreeNode *root, int low, int high)
  {
    if (!root)
      return root;

    auto left = trimBST(root->left, low, high);
    auto right = trimBST(root->right, low, high);

    root->left = left;
    root->right = right;

    if (root->val < low)
      return right;
    else if (root->val > high)
      return left;

    return root;
  }

int maximalRectangle(vector<vector<char>>& matrix) {

        if(!matrix.size() || !matrix[0].size()) return 0;

        int R = matrix.size(), C = matrix[0].size();
        vector<vector<int>> dp(R, vector<int>(C, 0));
        for(int i = 0; i < matrix.size(); i ++){
            dp[i][0] = matrix[i][0] - '0';
            for(int j = 1; j < C; j ++)
                if(matrix[i][j] == '1')
                    dp[i][j] = dp[i][j - 1] + 1;
        }

        int res = *max_element(dp[0].begin(), dp[0].end());

        for(int i = 1; i < R; i ++)
            for(int j = 0; j < C; j ++){
                int w = dp[i][j];
                for(int k = i; k >= 0 && w; k --){
                    w = min(w, dp[k][j]);
                    res = max(res, w * (i - k + 1));
                }
            }
        return res;
    }

