void fourDistinctFactors() {
    bool primeAll[N+1];
    memset(primeAll,true,sizeof(primeAll));
    for(int p=2;p*p<=N;p ++) {
        if(primeAll[p]== true) {
            for(int i=p*2;i<=N;i+=p)primeAll[i]= false ;
        }
    }
    vector<int>prime;
    for(int p=2;p<=N;p ++)if(primeAll[p]) prime.push_back(p);
    for(int i=0;i<prime.size();++ i) {
        int p=prime[i];
        if(1LL*p*p*p<=N)fourDiv[p*p*p]= true;
        for(int j=i+1;j<prime.size();++ j) {
            int q=prime[j];
            if(1LL*p*q>N)break;
            fourDiv[p*q]= true ;
        }
    }
}

