int maximumSubarraySum(vector<int >&arr) {
    int N=arr.size();
    unordered_map<int,int>memo;
    int res=INT_MIN;
    int currsum=0,currval=0;
    for(int i=0;i<N;++ i) {
        currval=arr[i];
        currsum=currsum+currval;
        if(memo.count(currval)!= 0) {
            if(currval>0)res=max(res,currsum-memo[currval]+ currval);
            else res=max(res,currsum-memo[currval]+ 2*currval);
        }
        else memo[currval]= currsum;
        if(currval<0)currsum=currsum-currval ;
    }
    return res;
}

