        int res = 0;
        for(int start = 0; start < s.size(); start ++){
            for(int c = 0; c < 26; c ++){
                int a = indexes[c];
                if(a >= pos[c].size()) continue;

                if(a + 1 >= pos[c].size()) res += (s.size() - pos[c][a]);
