int dfs(const string& s, int a, int b, vector<vector<int>>& dp){

        if(a >= b) return 0;
        if(dp[a][b] != INT_MAX) return dp[a][b];

        int res = INT_MAX;
        if(s[a] == s[b]) res = min(res, dp[a][b] = dfs(s, a + 1, b - 1, dp));
        res = min(res, 1 + min(dfs(s, a + 1, b, dp), dfs(s, a, b - 1, dp)));
        return dp[a][b] = res;
    }

