        vector<int> t = arr;
        bool change = false;
        do{
            change = false;
            arr = t;
            for(int i = 1; i < arr.size() - 1; i ++)
                if(t[i - 1] > t[i] && t[i + 1] > t[i]){arr[i] ++; change = true;}
                else if(t[i - 1] < t[i] && t[i + 1] < t[i]){arr[i] --; change = true;}
            t = arr;
        }while(change);
        return arr;
    }

