int triangleNumber(vector<int> &A)
  {
    sort(A.begin(), A.end());
    int ans = 0;

    for (int i = 0; i < A.size(); ++i)
    {
      for (int j = i + 1; j < A.size(); ++j)
      {
        int sum = A[i] + A[j];
        auto it = lower_bound(A.begin() + j + 1, A.end(), sum) - A.begin();
        it--;
        ans += (it - j);
      }
    }

    return ans;
  }

