int check(int n, const vector<int>& a, const vector<int>& b){

        int ares = 0;
        for(int i = 0; i < n; i += 2){
            if(a[i] != 0) ares ++;
            if(i + 1 < n && a[i + 1] != 1) ares ++;
        }

        int bres = 0;
        for(int i = 0; i < n; i += 2){
            if(b[i] != 0) bres ++;
            if(i + 1 < n && b[i + 1] != 1) bres ++;
        }

        if(ares % 2 || (n % 2 == 0 && n - ares < ares)) ares = n - ares;
        if(bres % 2 || (n % 2 == 0 && n - bres < bres)) bres = n - bres;
        return (ares + bres) / 2;
    }

