int stoneGameVIII(vector<int>& stones) {

        int n = stones.size();
        vector<int> sum(n, stones[0]);
        for(int i = 1; i < n; i ++)
            sum[i] = sum[i - 1] + stones[i];

        vector<int> dp(n, INT_MIN);
        dp[n - 2] = sum[n - 1];
        for(int i = n - 3; i >= 0; i --)
            dp[i] = max(sum[i + 1] - dp[i + 1], dp[i + 1]);
        return dp[0];
    }

int dfs(vector<int>& pos, int index, vector<int>& neg){

        if(index == pos.size()) return 0;

        int res = INT_MAX;
        for(int& e: neg){
            if(e){
                int t = min(pos[index], e);
                pos[index] -= t;
                e -= t;
                res = min(res, 1 + dfs(pos, index + (pos[index] == 0), neg));
                pos[index] += t;
                e += t;
            }
        }
        return res;
    }

using namespace std;
int getMinJumps(string s) {
    vector<int>ones;
    int jumps=0,median=0,ind=0;
    for(int i=0;i<s.length();i ++) {
        if(s[i]== '1')ones.push_back(i);
    }
    if(ones.size()==0)return jumps;
    median=ones[ones.size()/2];
    ind=median;
    for(int i=ind;i>=0;i --) {
        if(s[i]== '1') {
            jumps+=ind-i;
            ind--;
        }
    }
    ind=median;
    for(int i=ind;i<s.length();i ++) {
        if(s[i]== '1') {
            jumps+=i-ind;
            ind++;
        }
    }
    return jumps;
}

int RomanToInteger(const string& s) {
  unordered_map<char, int> T = {{'I', 1},   {'V', 5},   {'X', 10},  {'L', 50},
                                {'C', 100}, {'D', 500}, {'M', 1000}};

  int sum = T[s.back()];
  for (int i = s.length() - 2; i >= 0; --i) {
    if (T[s[i]] < T[s[i + 1]]) {
      sum -= T[s[i]];
    } else {
      sum += T[s[i]];
    }
  }
  return sum;
}

