int minMoves(vector<int>& nums, int limit) {

        vector<int> diff(limit * 2 + 2, 0);

        int n = nums.size();
        for(int i = 0; i < n / 2; i ++){
            int A = nums[i], B = nums[n - 1 - i];

            int l = 2, r = 2 * limit;
            diff[l] += 2, diff[r + 1] -= 2;

            l = 1 + min(A, B), r = limit + max(A, B);
            diff[l] += -1, diff[r + 1] -= -1;

            l = A + B, r = A + B;
            diff[l] += -1, diff[r + 1] -= -1;
        }

        int res = n, sum = 0;
        for(int i = 2; i <= 2 * limit; i ++){
            sum += diff[i];
            res = min(res, sum);
        }
        return res;
    }

