int count_primes(int n) {
        if (n <= 1) {
            return 0;
        }
        vector<bool> is_primes((n + 1) / 2, true);
        int cnt = is_primes.size();
        for (int i = 3; i * i <= n; i += 2) {
            if (!is_primes[i / 2]) {
                continue;
            }
            for (int j = i * i; j <= n; j += 2 * i) {
                if (!is_primes[j / 2]) {
                    continue;
                }
                --cnt;
                is_primes[j / 2] = false;
            }
        }
        return cnt;
    }

