vector<int> getSumAbsoluteDifferences(vector<int>& nums) {

        int n = nums.size();

        int front = 0, tail = 0;
        for(int i = 1; i < n; i ++) tail += nums[i] - nums[0];

        vector<int> res(n, tail);
        for(int i = 1; i < nums.size(); i ++){
            int diff = nums[i] - nums[i - 1];
            tail -= (nums.size() - i) * diff;
            front += i * diff;
            res[i] = front + tail;
        }
        return res;
    }

