        int n = timeSeries.size();
        int start = timeSeries[0], end = timeSeries[0] + duration, res = 0;
        for(int i = 1; i <= n; i ++)
            if(i == n || timeSeries[i] > end){
                res += end - start;
                if(i < n) start = timeSeries[i], end = timeSeries[i] + duration;
                else break;
            }
            else end = timeSeries[i] + duration;
