            if(S[i]== '1')dp[1 ][i]= 1;
            else dp[0 ][i]= 1 ;
        }
        else {
            if(S[i]== '0')dp[0 ][i]= 1+dp[1 ][i+1];
            else dp[1 ][i]= 1+dp[0 ][i+1];
        }
