int maxLen(int A[], int n)
{
  vector<int> prefix(n, 0);
  prefix[0] = A[0];
  for (int i = 1; i < n; ++i)
    prefix[i] = prefix[i - 1] + A[i];

  unordered_map<int, int> m;
  int ans = 0;
  for (int i = 0; i < n; ++i)
  {
    if (prefix[i] == 0)
      ans = max(ans, i + 1);
    if (m.find(prefix[i]) != m.end())
    {
      ans = max(ans, i - m[prefix[i]]);
    }
    else
      m[prefix[i]] = i;
  }

  return ans;
}

