        int res = A[0] + A[n - 1] - (n - 1), maxv = A[n - 1] - (n - 1);
        for(int i = n - 2; i >= 0; i --){
            res = max(res, A[i] + i + maxv);
            maxv = max(maxv, A[i] - i);
        }
        return res;
    }

int minUnlockedIndices(vector<int>& nums, vector<int>& locked) {
        int result = 0;
        for (int i = 0, mx = 0, cnt = 0; i < size(nums); ++i) {
            if (mx < nums[i]) {
                mx = nums[i];
                cnt = 0;
            } else if (mx > nums[i]) {
                if (mx != nums[i] + 1) {
                    return -1;
                }
                result += cnt;
                cnt = 0;
            }
            cnt += locked[i];
        }
        return result;
    }

bool dfs(string a, string b, string c, int ia, int ib, int ic, vector<vector<int>> &memo)
  {
    if (ic == c.size())
    {
      if (ia == a.size() && ib == b.size())
        return true;
      return false;
    }

    if (memo[ia][ib] != -1)
      return memo[ia][ib];

    if (a[ia] == c[ic] && dfs(a, b, c, ia + 1, ib, ic + 1, memo))
      return memo[ia][ib] = true;
    if (b[ib] == c[ic] && dfs(a, b, c, ia, ib + 1, ic + 1, memo))
      return memo[ia][ib] = true;
    return memo[ia][ib] = false;
  }

