        vector<int> lis = {obstacles[0]};
        vector<int> res = {1};
        for(int i = 1; i < obstacles.size(); i ++){
            vector<int>::iterator iter = upper_bound(lis.begin(), lis.end(), obstacles[i]);
            int k = iter - lis.begin();
            if(iter == lis.end())
                lis.push_back(obstacles[i]);
            else
                lis[k] = obstacles[i];
            res.push_back(k + 1);
        }
        return res;
    }

