int getMinSteps(string str,int i,int j,int n) {
    if(j<i) {
        int temp=i;
        i=j;
        j=temp ;
    }
    int stepsToRight=getSteps(str,i,j,n);
    int stepsToLeft=getSteps(str,0,i,n)+ getSteps(str,j,n-1,n);
    if(str[0]!= str[n-1]) stepsToLeft ++;
    return min(stepsToLeft,stepsToRight);
}

