int reachNumber(int target) {

        if(target < 0) target = -target;

        int sum = 0, k = 1;
        while(sum < target) sum += k ++;

        if(sum == target || (sum - target) % 2 == 0) return k - 1;
        for(;;){
            sum += k ++;
            if((sum - target) % 2 == 0) return k - 1;
        }
        return -1;
    }

