        long long mid =(low+high)/ 2;
        if(f(mid)< x)low=mid+1;
        else if(f(mid)> x)high=mid-1;
        else return true ;
    }
    return false ;
}
bool isStellaOctangula(int x) {
    if(x==0)return true;
    int i=1;
    while(f(i)< x)i=i*2;
    if(f(i)== x)return true;
    return binarySearch(i/2,i,x);
}

