         key_mid = key_next;
      }
   }
}

bool isPalindrome(ListNode *head)
  {
    auto slow = head, fast = head;
    while (fast && fast->next)
    {
      slow = slow->next;
      fast = fast->next->next;
    }
    auto head2 = reverse(slow);
    auto head1 = head;
    while (head2 && head1)
    {
      if (head1->val != head2->val)
        return false;
      head1 = head1->next;
      head2 = head2->next;
    }
    return true;
  }

