void countSort(int arr[], int n, int exp)
{
    // Count[i] array will be counting the number of array values having that 'i' digit at their (exp)th place.
    int output[n], i, count[10] = {0};

    // Count the number of times each digit occurred at (exp)th place in every input.
    for (i = 0; i < n; i++)
        count[(arr[i] / exp) % 10]++;

    // Calculating their cumulative count.
    for (i = 1; i < 10; i++)
        count[i] += count[i-1];

    // Inserting values according to the digit '(arr[i] / exp) % 10' fetched into count[(arr[i] / exp) % 10].
    for (i = n - 1; i >= 0; i--)
    {
        output[count[(arr[i] / exp) % 10] - 1] = arr[i];
        count[(arr[i] / exp) % 10]--;
    }

    // Assigning the result to the arr pointer of main().
    for (i = 0; i < n; i++)
        arr[i] = output[i];
}

int stoneGameVI(vector<int>& aliceValues, vector<int>& bobValues) {

        int n = aliceValues.size();

        vector<vector<int>> data(n);
        for(int i = 0; i < n; i ++)
            data[i] = {aliceValues[i] + bobValues[i], aliceValues[i], bobValues[i]};

        sort(data.begin(), data.end(), greater<vector<int>>());

        int ascore = 0, bscore = 0;
        for(int i = 0; i < n; i ++)
            if(i % 2 == 0) ascore += data[i][1];
            else bscore += data[i][2];

        return ascore == bscore ? 0 : ascore > bscore ? 1 : -1;
    }

