using namespace std;
int Solution(vector<int>A) {
    int ans=2;
    int n=A.size();
    if(n<=2)return n;
    vector<int>llap(n,2);
    sort(A.begin(),A.end());
    for(int j=n-2;j>=0;j --) {
        int i=j-1;
        int k=j+1;
        while(i>=0&&k<n) {
            if(A[i]+ A[k]== 2*A[j]) {
                llap[j]= max(llap[k]+ 1,llap[j]);
                ans=max(ans,llap[j]);
                i-=1;
                k+=1 ;
            }
            else if(A[i]+ A[k]< 2*A[j]) k+=1;
            else i-=1 ;
        }
    }
    return ans;
}

ListNode *reverse(ListNode *mid)
  {
    if (!mid || !mid->next)
      return mid;
    auto curr = mid, next = curr->next;
    curr->next = NULL;
    while (next)
    {
      auto nextNext = next->next;
      next->next = curr;
      curr = next;
      next = nextNext;
    }

    return curr;
  }

bool checkAlmostEquivalent(string word1, string word2) {
        static const int K = 3;

        unordered_map<char, int> cnt1;
        for (const auto& c : word1) {
            ++cnt1[c];
        }
        unordered_map<char, int> cnt2;
        for (const auto& c : word2) {
            ++cnt2[c];
        }
        for (const auto& [k, v] : cnt1) {
            if (abs(cnt2[k] - v) > K) {
                return false;
            }
        }
        for (const auto& [k, v] : cnt2) {
            if (abs(cnt1[k] - v) > K) {
                return false;
            }
        }
        return true;
    }

