bool predecessor(string& prev, string& curr) {
        int M = prev.length();
        int N = curr.length();

        if(M >= N || N-M != 1)
            return false;

        int i = 0, j = 0;
        while(i < M && j < N) {
            if(prev[i] == curr[j]) {
                i++;
            }
            j++;
        }
        return i==M;
    }

