bool productSumDivisible(int n,int size) {
    int sum=0,product=1;
    while(n>0) {
        if(size%2==0) {
            product*=n%10 ;
        }
        else {
            sum+=n%10 ;
        }
        n=n/10;
        size--;
    }
    if(product%sum==0)return true;
    return false;
}

