int minCost(string s, vector<int>& cost) {
        stack<pair<char, int>> st;

        int n = s.length();
        int price = 0;
        for(int i = 0; i<n; i++) {
            if(st.empty() || st.top().first != s[i]) {
                st.push({s[i], cost[i]});
            } else {
                price += min(st.top().second, cost[i]);
                if(st.top().second < cost[i]) {
                    st.pop();
                    st.push({s[i], cost[i]});
                }
            }
        }

        return price;
    }

