bool isMonotonic(vector<int>& nums) {
        int n = nums.size();

        bool increasing = false;
        bool decreasing = false;

        for(int i = 0; i < n-1; i++) {
            if(nums[i] < nums[i+1]) increasing = true;

            if(nums[i] > nums[i+1]) decreasing = true;

        }

        if(increasing == true && decreasing == true)
                return false;

        return true;
    }

int longestMonotonicSubarray(vector<int>& nums) {
        int n = nums.size();

        int result = 0;
        for(int i = 0; i < n; i++) {
            int increasing = 1;
            int j = i+1;
            while(j < n && nums[j] > nums[j-1]) {
                increasing++;
                j++;
            }

            int decreasing = 1;
            j = i+1;

            while(j < n && nums[j] < nums[j-1]) {
                decreasing++;
                j++;
            }

            result = max({result, increasing, decreasing});
        }

        return result;
    }

vector<int> pivotArray(vector<int>& nums, int pivot) {

        vector<int> pre, middle, post;
        for(int e: nums)
            if(e < pivot) pre.push_back(e);
            else if(e == pivot) middle.push_back(e);
            else post.push_back(e);

        pre.insert(pre.end(), middle.begin(), middle.end());
        pre.insert(pre.end(), post.begin(), post.end());
        return pre;
    }

