int solve(vector<vector<int>>& D,int N,int X,int Y) {
    vector<double>T;
    for(int i=0;i<N;i ++) {
        int x=D[i ][0];
        int y=D[i ][1];
        double speed=D[i ][2];
        double time =(( x*x-X*X)+(y*y-Y*Y)) /(speed*speed);
        T.push_back(time);
    }
    sort(T.begin(),T.end());
    int i=0;
    int total=0;
    while(i<T.size()-1) {
        int count=1;
        while(i<T.size()-1 and T[i]== T[i+1]) {
            count+=1;
            i+=1 ;
        }
        total +=(count *(count-1))/2;
        i+=1 ;
    }
    return total;
}

bool isBST(Node *root)
{
  if (!root)
    return true;

  bool ans = true;
  ans = isBST(root->left) && isBST(root->right);

  auto left = root->left, right = root->right;
  if (left)
  {
    while (left->right)
      left = left->right;
    ans = ans && (left->data < root->data);
  }

  if (right)
  {
    while (right->left)
      right = right->left;
    ans = ans && (right->data > root->data);
  }

  return ans;
}

