int binaryGap(int N) {

        int last = -1;
        int res = 0, index = 0;
        while(N){
            int bit = N & 1;
            if(bit){
                if(last != -1)
                    res = max(res, index - last);
                last = index;
            }

            index ++;
            N >>= 1;
        }

        return res;
    }

int dfs(int n, int index, vector<bool>& used){

        if(index == n + 1) return 1;

        int res = 0;
        for(int num = 1; num <= n; num ++)
            if(!used[num] && (num % index == 0 || index % num == 0)){
                used[num] = true;
                res += dfs(n, index + 1, used);
                used[num] = false;
            }
        return res;
    }

