int max_length_substring(string st,int n,int k) {
    int max_len=0;
    int len=0;
    for(int i=0;i<n;++ i) {
        if(st[i]== '0')len ++;
        else len=0;
        max_len=max(max_len,len);
    }
    if(max_len==n)return n*k;
    int pref=0,suff=0;
    for(int i=0;st[i]== '0';++ i,++ pref);
