int findPeakElement(vector<int> &nums)
  {
    if (nums.size() <= 1)
      return 0;
    if (nums.size() == 2)
      return nums[0] > nums[1] ? 0 : 1;

    int n = nums.size();
    int left = 0, right = n - 1;
    while (left < right)
    {
      int mid = (left + right) / 2;
      if (nums[mid] > nums[mid + 1])
        right = mid;
      else
        left = mid + 1;
    }

    return left;
  }

