bool canMakeEqual(vector<int>& nums, int k) {
        const auto& check = [&](int target) {
            int parity = 0;
            for (int i = 0, cnt = 0; i < size(nums); ++i) {
                if (nums[i] == target) {
                    continue;
                }
                cnt += parity ? i : -i;
                if (cnt > k) {
                    return false;
                }
                parity ^= 1;
            }
            return parity == 0;
        };

        return check(1) || check(-1);
    }

