int maximizeAnd(int i,int mask,int*A,int*B,int N,vector<vector<int>>& dp) {
    if(i==N)return 0;
    if(dp[i ][mask]!= -1)return dp[i ][mask];
    for(int j=0;j<N;++ j) {
        if(!(mask &(1<<j))) {
            dp[i ][mask]= max(dp[i ][mask],(A[i]& B[j])+maximizeAnd(i+1,mask |(1<<j), A,B,N,dp)) ;
        }
    }
    return dp[i ][mask];
}
