int numSubarrayBoundedMax(vector<int> &nums, int left, int right)
  {
    int ans = 0;
    int i = 0, j = 0, count = 0;

    while (j < nums.size())
    {
      if (nums[j] >= left && nums[j] <= right)
      {
        count = (j - i + 1);
        ans += count;
      }
      else if (nums[j] < left)
        ans += count;
      else
      {
        i = j + 1;
        count = 0;
      }
      j++;
    }
    return ans;
  }

