        int n = A.size();
        //min size is 3 for a series
        if(n < 3)
            return 0;

        int count = 0;
        for(int start = 0; start <= n-3; start++) {
            int diff = A[start+1]-A[start];

            for(int end = start+2; end<n; end++) {
                if(A[end]-A[end-1] == diff)
