        int minPosition = -1;
        int maxPosition = -1;
        int leftBound   = -1;

        for(int i = 0; i < nums.size(); i++) {

            if(nums[i] < minK || nums[i] > maxK)
                leftBound = i;

            if(nums[i] == minK)
                minPosition = i;
            if(nums[i] == maxK)
