int findSum(int n,int k) {
    int val =(k /(n-1))*n;
    int rem=k %(n-1);
    if(rem==0) {
        val=val-1 ;
    }
    else {
        val=val+rem ;
    }
    int sum =(val *(val+1))/2;
    int x=k /(n-1);
    int sum_of_multiples =(x *(x+1)* n)/ 2;
    sum-=sum_of_multiples;
    return sum;
}

