    for(int i=0;i<arr.size();i ++) {
        if(arr[i]== i) {
            res=max(res,1);
        }
        else {
            int count=0;
            int curr_index=i;
            while(arr[curr_index]!= curr_index) {
                int next_index=arr[curr_index];
