    int diff=Y-X;
    if(diff==1)return -1;
    if(diff%2==0)return(diff/2);
    return(1 +(( diff-3)/ 2));
}

using namespace std;
long long int smallestNumber(int n) {
    if(n>=0&&n<=9)return n;
    stack<int>digits;
    for(int i=9;i>=2&&n>1;i --) {
        while(n%i==0) {
            digits.push(i);
            n=n/i ;
        }
    }
    if(n!=1)return -1;
    long long int k=0;
    while(! digits.empty()) {
        k=k*10+digits.top();
        digits.pop() ;
    }
    return k;
}

