int solve(int n, int total, const vector<int>& g, const vector<int>& travel){

        if(total == 0) return 0;

        int res = g[0];
        total -= g[0];
        for(int i = 1; i < n && total; i ++){
            res += travel[i - 1];
            res += g[i];
            total -= g[i];
        }
        return res;
    }

