using namespace std;
long findWays(int f,int d,int s) {
    long mem[d+1 ][s+1];
    memset(mem,0,sizeof mem);
    mem[0 ][0]= 1;
    for(int i=1;i<=d;i ++) {
        for(int j=i;j<=s;j ++) {
            mem[i ][j]= mem[i ][j-1]+ mem[i-1 ][j-1];
            if(j-f-1>=0)mem[i ][j]-= mem[i-1 ][j-f-1];
        }
    }
    return mem[d ][s];
}

