bool ok(int n, vector<double> B, double t, double p){

        for(int i = 0, j = 0; i < n;)
            if(B[i] < t){
                while(j < n && B[j] <= t) j ++;
                if(j == n) return false;

                double need = t - B[i];
                double can_pour = (B[j] - t) * p;
                if(need >= can_pour){
                    B[i] += can_pour;
                    B[j] = t;
                    if(B[i] >= t) i ++;
                }
                else{
                    B[i] = t;
                    B[j] -= need / p;
                    i ++;
                }
            }
            else i ++;
        return true;
    }

int triangleNumber(vector<int>& nums) {

        sort(nums.begin(), nums.end());

        int n = nums.size(), res = 0;
        for(int i = 0; i < n; i ++)
            for(int j = i + 1; j < n; j ++){
                int a = nums[i], b = nums[j];
                vector<int>::iterator iter1 = upper_bound(nums.begin() + (j + 1), nums.end(), b - a);
                int l = iter1 - nums.begin();

                vector<int>::iterator iter2 = lower_bound(nums.begin() + (j + 1), nums.end(), b + a);
                iter2 --;
                int r = iter2 - nums.begin();

//                cout << i << ' ' << j << " : " << l << ' ' << r << endl;
                if(l <= r) res += (r - l + 1);
            }
        return res;
    }

using namespace std;
int countTriplets(int*arr,int N) {
    vector<int>zero_i;
    vector<int>one_i;
    unordered_map<int,int>mp;
    for(int i=0;i<N;i ++) {
        if(arr[i]== 0)zero_i.push_back(i+1);
        else if(arr[i]== 1)one_i.push_back(i+1);
        else mp[i+1]= 1 ;
    }
    int total=zero_i.size()*one_i.size()*mp.size();
    for(int i=0;i<zero_i.size();i ++) {
        for(int j=0;j<one_i.size();j ++) {
            int p=zero_i[i];
            int q=one_i[j];
            int r=2*p-q;
            if(mp[r]> 0)total --;
            r=2*q-p;
            if(mp[r]> 0)total --;
            r =(p+q)/ 2;
            if(mp[r]> 0&&abs(r-p)== abs(r-q)) total--;
        }
    }
    cout<<total;
}

