int solve(const string& s, int k, char c){

        int n = s.size();
        vector<int> presum(n + 1, 0);
        for(int i = 0; i < n; i ++)
            presum[i + 1] = presum[i] + (s[i] == c);

        int l = 0, r = 0, res = 0;
        while(l <= n){
            if(r + 1 <= n && presum[r + 1] - presum[l] + k >= r + 1 - l)
                r ++, res = max(res, r - l);
            else
                l ++;
        }
        return res;
    }

