long long dfs(int m, int n, vector<vector<long long>>& dp, vector<vector<bool>>& visited){

        if(visited[m][n]) return dp[m][n];

        long long res = dp[m][n];
        for(int top = 1; top <= m - 1; top ++)
            res = max(res, dfs(top, n, dp, visited) + dfs(m - top, n, dp, visited));
        for(int left = 1; left <= n - 1; left ++)
            res = max(res, dfs(m, left, dp, visited) + dfs(m, n - left, dp, visited));

        visited[m][n] = true;
        return dp[m][n] = res;
    }

int findMaxValueOfEquation(vector<vector<int>>& points, int k) {

        set<pair<int, int>> tree;

        // 初始放入第一个点的信息
        tree.insert({points[0][1] - points[0][0], points[0][0]});

        int res = INT_MIN, j = 0;
        for(int i = 1; i < points.size(); i ++){

            // 删除红黑树中不满足条件的数据
            while(j < i && points[i][0] - points[j][0] > k){
                tree.erase({points[j][1] - points[j][0], points[j][0]});
                j ++;
            }

            // 使用红黑树最大元素信息更新解
            if(!tree.empty())
                res = max(res, points[i][1] + points[i][0] + tree.rbegin()->first);

            // 将当前点的信息放入红黑树
            tree.insert({points[i][1] - points[i][0], points[i][0]});
        }
        return res;
    }

void dfs(int node, unordered_map<int, vector<int>>& adj, vector<int>& visited,
             stack<int>& st, bool& hasCycle) {

        visited[node] = 1;  // Mark node as visiting
        //First, visit node's children
        for (int& nbr : adj[node]) {
            if (visited[nbr] == 0) {
                dfs(nbr, adj, visited, st, hasCycle);
            } else if (visited[nbr] == 1) {
                // Cycle detected
                hasCycle = true;
                return;
            }
        }

        visited[node] = 2; //visited
        st.push(node); //Now node can be added
    }

