double probabilityOfHeads(vector<double>& prob, int target) {

        int n = prob.size();
        vector<double> dp(target + 1, 0.0);

        if(target) dp[1] = prob[0];
        dp[0] = 1.0 - prob[0];
        for(int i = 1; i < n; i ++){
            for(int j = target; j >= 1; j --)
                dp[j] = dp[j] * (1 - prob[i]) + dp[j - 1] * prob[i];
            dp[0] = dp[0] * (1 - prob[i]);
        }
        return dp[target];
    }

int countDistinct(vector<int>& nums, int k, int p) {

        int n = nums.size();
        vector<int> k_divisible(n, 0);
        for(int i = 0; i < n; i ++) k_divisible[i] = (nums[i] % p == 0);

        vector<int> presum(n + 1, 0);
        for(int i = 0; i < n; i ++) presum[i + 1] = presum[i] + k_divisible[i];

        Trie trie;
        for(int l = 0; l < n; l ++){
            auto iter = upper_bound(presum.begin(), presum.end(), presum[l] + k);
            int index = iter - presum.begin() - 1;
            int r = index - 1;
            if(l <= r)
                trie.insert(nums, l, r);
        }
        return trie.size();
    }

