ListNode* reverse(ListNode* head, int& k, int times) {
        if(!head || times <= 0)
            return head;

        ListNode* next = NULL;
        ListNode* prev = NULL;
        ListNode* curr = head;
        int c = 1;

        while(curr && c <= k) {
            next = curr->next;
            curr->next = prev;
            prev = curr;
            curr = next;
            c++;
        }

        if(next) {
            head->next = reverse(next, k, times-1);
        }

        return prev;

    }

