int dfs(const vector<int>& nums, int index, int S,
            map<pair<int, int>, int>& dp){

        if(index == nums.size())
            return S == 0;

        pair<int, int> p = make_pair(index, S);
        if(dp.count(p))
            return dp[p];

        int ret = 0;
        ret += dfs(nums, index + 1, S - nums[index], dp);
        ret += dfs(nums, index + 1, S + nums[index], dp);
        return dp[p] = ret;
    }

