char* win32_basename(char* path) {
    int pathLen = strlen(path);
    int lastPathSepFoundPos = -1;
    int pos = 0;
    while (path[pathLen - 1] == '\\' || path[pathLen - 1] == '/') {
        path[pathLen - 1] = 0;
        pathLen--;
    };
    while (path[pos] != 0) {
        if (path[pos] == '\\' || path[pos] == '/') {
            lastPathSepFoundPos = pos;
        }
        pos++;
    }
    if (lastPathSepFoundPos == -1)
        return path;
    else
        return path + lastPathSepFoundPos + 1;
}

long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {
        uint64_t result = 0, curr = 0;
        vector<pair<int, int>> nums;
        for (int i = 0; i < size(nums1); ++i) {
            nums.emplace_back(nums1[i], nums2[i]);
        }
        sort(begin(nums), end(nums), [](const auto& a, const auto& b) {
            return a.second > b.second;
        });
        priority_queue<int, vector<int>, greater<int>> min_heap;
        for (const auto& [a, b] : nums) {
            curr += a;
            min_heap.emplace(a);
            if (size(min_heap) > k) {
                curr -= min_heap.top(); min_heap.pop();
            }
            if (size(min_heap) == k) {
                result = max(result, curr * b);
            }
        }
        return result;
    }

