int countCollisions(string directions) {

        int res = 0;
        string stack = "";
        for(char c: directions)
            if(c == 'R') stack += c;
            else if(c == 'L'){
                if(stack.empty()) continue;
                else if(stack.back() == 'R'){
                    res += 2, stack.pop_back();
                    while(!stack.empty() && stack.back() == 'R') res ++, stack.pop_back();
                    stack += 'S';
                }
                else res ++;
            }
            else if(c == 'S'){
                if(stack.empty()) stack += 'S';
                else if(stack.back() == 'R'){
                    while(!stack.empty() && stack.back() == 'R') res ++, stack.pop_back();
                    stack += 'S';
                }
            }
        return res;
    }

