int minIncrementForUnique(vector<int>& A) {

        if(A.size() == 0)
            return 0;

        sort(A.begin(), A.end());
        int res = 0, left = 0;
        for(int i = 1; i < A.size(); i ++)
            if(A[i] == A[i - 1]){
                left ++;
                res -= A[i];
            }
            else{
                int seg = min(left, A[i] - A[i - 1] - 1);
                res += (A[i - 1] + 1 + A[i - 1] + seg) * seg / 2;
                left -= seg;
            }

        if(left)
            res += (A.back() + 1 + A.back() + left) * left / 2;
        return res;
    }

