        vector<int> dp(4, 0);
        for(int start = n - 1; start >= 0; start --){
            int sum = 0;
            dp[start % 4] = INT_MIN;
            for(int i = 0; i < 3 && start + i < n; i ++){
                sum += stoneValue[start + i];
                dp[start % 4] = max(dp[start % 4], sum - (start + i + 1 < n ? dp[(start + i + 1) % 4] : 0));
            }
        }

        if(dp[0] > 0) return "Alice";
        else if(dp[0] < 0) return "Bob";
        return "Tie";
    }

