int dfs(int n, const vector<vector<int>>& grid, int row, int last_c, vector<vector<int>>& dp) {

        if (row == n) return 0;
        if (dp[row][last_c] != -1) return dp[row][last_c];

        int res = INT_MAX;
        for (int j = 0; j < n; j ++) {
            if (j == last_c) continue;
            res = min(res, grid[row][j] + dfs(n, grid, row + 1, j, dp));
        }
        return dp[row][last_c] = res;
    }

void BFS(Graph& g, int source) {
  vector<bool> visited(g.adj_list.size(), false);
  queue<int> q;
  q.push(source);
  // initialize visited and dist vector
  visited[source] = true;
  g.dist[source] = 0;

  while(!q.empty()) {
    int cur_node = q.front();
    vector<int> cur_node_adj = g.adj_list[cur_node];
    // iterate through cur_node's adj_list
    for (unsigned int i = 0; i < cur_node_adj.size(); ++i) {
      int adj_node = cur_node_adj[i];
      if (visited[adj_node] == false) {
        visited[adj_node] = true;
        g.dist[adj_node] = g.dist[cur_node] + 1;
        q.push(adj_node);
      }
    }
    q.pop();
  } // end while q is not empty
}

