using namespace std;
long max_gcd(long n,long p) {
    int count=0;
    long gcd=1;
    while(p%2==0) {
        p >>= 1;
        count++;
    }
    if(count>0)gcd *=(long)pow(2,count/n);
    for(long i=3;i<=sqrt(p); i+=2) {
        count=0;
        while(p%i==0) {
            count ++;
            p=p/i ;
        }
        if(count>0) {
            gcd *=(long)pow(i,count/n);
        }
    }
    if(p>2)gcd *=(long)pow(p,1/n);
    return gcd;
}

