int findMaxLen(string s)
{
  stack<int> si;
  si.push(-1);

  int ans = 0;

  for (int i = 0; i < s.size(); ++i)
  {
    if (s[i] == '(')
      si.push(i);
    else
    {
      si.pop();
      if (si.size())
      {
        int curr = i - si.top();
        ans = max(ans, curr);
      }
      else
        si.push(i);
    }
  }
  return ans;
}

