int minSwaps(vector<int>arr,int N) {
    int ans=0;
    vector<int>temp=arr;
    map<int,int>h;
    sort(temp.begin(),temp.end());
    for(int i=0;i<N;i ++) {
        h[arr[i]]=i ;
