vector<int> get_divisors(int num){

        vector<int> res;
        if(!(num & 1)){
            res.push_back(2);
            while(!(num & 1)) num >>= 1;
        }

        for(int d = 3; d * d <= num; d += 2)
            if(num % d == 0){
                res.push_back(d);
                while(num % d == 0) num /= d;
            }

        if(num != 1) res.push_back(num);
        return res;
    }

bool dfs(const vector<int>& nums, int index, vector<int>& cur){

        if(index == nums.size()){
            for(int e: cur)
                if(e)
                    return false;
            return true;
        }

        for(int i = 0; i < cur.size() ; i ++)
            if(cur[i] >= nums[index]){
                cur[i] -= nums[index];
                if(dfs(nums, index + 1, cur))
                    return true;
                cur[i] += nums[index];
            }
        return false;
    }

