int maxCount(vector<int >&freq,int mini,int maxi) {
    int n=freq.size()-1;
    int ans=0;
    for(int sum=2*mini;sum<=2*maxi;++ sum) {
        int possiblePair=0;
        for(int firElement=1;firElement <(sum+1)/ 2;firElement ++) {
            if(sum-firElement<=maxi) {
                possiblePair+=min(freq[firElement], freq[sum-firElement]) ;
            }
        }
        if(sum%2==0) {
            possiblePair+=freq[sum/2]/ 2 ;
        }
        ans=max(ans,possiblePair);
    }
    return ans ;
}
