vector<int> findPrevGreater(vector<int>& primeScores) {
        int n = primeScores.size();
        vector<int> prevGreator(n, -1);
        stack<int> st;

        for(int i = 0; i < n; i++) {
            while(!st.empty() && primeScores[st.top()] < primeScores[i]) {
                st.pop();
            }

            prevGreator[i] = st.empty() ? -1 : st.top();
            st.push(i);
        }

        return prevGreator;
    }

