bool isPalindrome(ListNode *head)
  {
    auto slow = head, fast = head;
    while (fast && fast->next)
    {
      slow = slow->next;
      fast = fast->next->next;
    }

    auto reversedMid = reverse(slow);
    while (reversedMid)
    {
      if (reversedMid->val != head->val)
        return false;
      reversedMid = reversedMid->next;
      head = head->next;
    }

    return true;
  }

