            vector<vector<int>>& dp){

        if(index == s.size()) return 0;
        if(dp[pre][index] != -1) return dp[pre][index];

        int res = cost[index] + dfs(s, cost, pre, index + 1, dp);
        if(pre != s[index] - 'a')
            res = min(res, dfs(s, cost, s[index] - 'a', index + 1, dp));
        return dp[pre][index] = res;
    }

