static void add_wpartial(int size, float* data, double partial, double amp, double phase) {
    if (amp == 0.0)
        return;
    int size2 = size >> 1;
    double w = (partial * 2.0 * 3.1415926535897932384626433832795) / (double)size2;
    double cur = amp * sin(phase);
    phase += w;
    for (int i = 0; i < size; i += 2) {
        double next = amp * sin(phase);
        data[i] += 2 * cur - next;
        data[i + 1] += next - cur;
        cur = next;
        phase += w;
    }
}

void updateSegmentTree(int i, int l, int r, int updateIndex, vector<long long>& segmentTree) {
        if (l == r) {
            segmentTree[i] = 1;
            return;
        }

        int mid = l + (r - l) / 2;
        if (updateIndex <= mid) {
            updateSegmentTree(2 * i + 1, l, mid, updateIndex, segmentTree);
        } else {
            updateSegmentTree(2 * i + 2, mid + 1, r, updateIndex, segmentTree);
        }

        segmentTree[i] = segmentTree[2 * i + 1] + segmentTree[2 * i + 2];
    }

