ListNode *reverseKGroup(ListNode *head, int k)
  {
    auto curr = head;
    int count = 0;
    while (curr && count != k)
    {
      count++;
      curr = curr->next;
    }

    if (count == k)
    {
      auto prev_ans = reverseKGroup(curr, k);
      while (count-- > 0)
      {
        auto temp = head->next;
        head->next = prev_ans;
        prev_ans = head;
        head = temp;
      }
      head = prev_ans;
    }
    return head;
  }

