            pos[nums[i]] = i;

        for(const vector<int>& op: operations){
            int from_num = op[0], to_num = op[1];
            int from_index = pos[from_num];
            nums[from_index] = to_num;

            pos[from_num] = -1;
            pos[to_num] = from_index;
        }
        return nums;
    }

