bool isDecomposable(string s) {
        if (size(s) % 3 != 2) {
            return false;
        }
        int left;
        for (left = 0; left < size(s); left += 3) {
            if (std::adjacent_find(cbegin(s) + left, cbegin(s) + min(left + 3, int(size(s))),
                                   std::not_equal_to<>()) != cbegin(s) + min(left + 3, int(size(s)))) {
                break;
            }
        }
        int right;
        for (right = size(s) - 1; right >= left + 1  ; right -= 3) {
            if (std::adjacent_find(cbegin(s) + max(right - 2, left), cbegin(s) + right + 1,
                                   std::not_equal_to<>()) != cbegin(s) + right + 1) {
                break;
            }
        }
        return (right + 3) - left == 1;
    }

void generateTernary_myStack(int len)
{
    stack< pair<int, string> > st;    // create stack consist of recursion state
    st.push( make_pair(len, "") );

    while(!st.empty())
    {
        int len = st.top().first;
        string cur = st.top().second;
        st.pop();

        if(len == 0) {
            cout<<cur<<"\n";
            continue;
        }

        st.push(make_pair(len-1, cur + "0"));
        st.push(make_pair(len-1, cur + "1"));
        st.push(make_pair(len-1, cur + "2"));

    }
}

int findMaxDiff(TreeNode* root, int minV, int maxV) {
        if(!root)
            return abs(minV-maxV);

        minV = min(root->val, minV);
        maxV = max(root->val, maxV);

        int l = findMaxDiff(root->left,  minV, maxV);
        int r = findMaxDiff(root->right, minV, maxV);


        return max(l, r);

    }

vector<int> zigzagTraversal(vector<vector<int>>& grid) {
        vector<int> result;
        for (int i = 0; i < size(grid); ++i) {
            if (i % 2 == 0) {
                for (int j = 0; j < size(grid[0]); j += 2) {
                    result.emplace_back(grid[i][j]);
                }
            } else {
                for (int j = (size(grid[0]) - 1) - size(grid[0]) % 2; j >= 0; j -= 2) {
                    result.emplace_back(grid[i][j]);
                }
            }
        }
        return result;
    }

