int findSum(int*a,int n,int L,int R) {
    int sum=0;
    for(int i=0;i<n;i ++) {
        if(L%a[i]== 0&&L!=0) {
            sum+=calcSum(a[i], R/a[i])-calcSum(a[i],(L-1)/ a[i]) ;
        }
        else {
            sum+=calcSum(a[i], R/a[i])-calcSum(a[i], L/a[i]) ;
        }
    }
    return sum;
}

