void Tanx_expansion(int terms,int x) {
    double sum=0;
    for(int i=1;i<=terms;i+=1) {
        double B=0;
        int Bn=2*i;
        for(int k=0;k<=Bn;k ++) {
            double temp=0;
            for(int r=0;r<=k;r ++)temp=temp+pow(-1,r)* fac(k)* pow(r,Bn)/(fac(r)* fac(k-r));
            B=B+temp /(( double )(k+1)) ;
        }
        sum=sum+pow(-4,i)*(1-pow(4,i))*B*pow(x,2*i-1)/ fac(2*i);
    }
    cout<<setprecision(10)<< sum;
}

