double arr_average(double arr[], int len) {
    if (len == 1)
        return arr[0];

    double sub_result = arr_average(arr, len - 1);
    // Now this was average of len-1. So sum / (len-1)
    sub_result = sub_result * (len-1);

    return (sub_result + arr[len - 1] ) / len;
}

bool circle_seg_intersect(long long x0, long long y0, long long r0,
                              long long x1, long long y1, long long x2, long long y2){

        bool flag1 = (x1 - x0) * (x1 - x0) + (y1 - y0) * (y1 - y0) <= r0 * r0;
        bool flag2 = (x2 - x0) * (x2 - x0) + (y2 - y0) * (y2 - y0) <= r0 * r0;

        if(flag1 && flag2) return false;
        if((flag1 && !flag2) || (!flag1 && flag2)) return true;

        long long A = y2 - y1;
        long long B = x1 - x2;
        long long C = x2 * y1 - y2 * x1;

        if((long double)(A * x0 + B * y0 + C) * (A * x0 + B * y0 + C) > (long double)r0 * r0 * (A * A + B * B))
            return false;

        long long a1 = (x0 - x1) * (x2 - x1) + (y0 - y1) * (y2 - y1);
        long long a2 = (x0 - x2) * (x1 - x2) + (y0 - y2) * (y1 - y2);
        if(a1 > 0 && a2 > 0) return true;
        return false;
    }

