int minTaps(int n, vector<int>& ranges) {

        vector<int> dp(n, INT_MAX / 2);
        for(int i = 0; i <= n; i ++){
            int l = max(0, i - ranges[i]), r = min(n, i + ranges[i]);
            for(int j = l; j < r; j ++)
                dp[j] = min(dp[j], (l - 1 >= 0 ? dp[l - 1] : 0) + 1);
        }
        return dp.back() == INT_MAX / 2 ? -1 : dp.back();
    }

