        memset(mapped, false, sizeof(mapped));

        for(int i = 0 ; i < s.size() ; i ++){
            if(map[s[i]] == -1){
                if(mapped[t[i]])
                    return false;
                map[s[i]] = t[i];
                mapped[t[i]] = true;
            }
            else if(map[s[i]] != t[i])
                return false;
        }
        return true;
    }

void solve(int n, string &curr, vector<string> &result) {
        if (curr.length() == n) {
            result.push_back(curr);
            return;
        }

        for (char ch = 'a'; ch <= 'c'; ch++) {
            if (!curr.empty() && curr.back() == ch)
                continue;

            // Do
            curr.push_back(ch);

            // Explore
            solve(n, curr, result);

            // Undo
            curr.pop_back();
        }
    }

