    else if(sum==target)return data.size();
    else if(data[0]>= target)return 1;
    else if(data[0]< target) {
        vector<int>temp;
        for(int i=1;i<data.size();i ++)temp.push_back(data[i]);
        return min(smallSumSubset(temp,target,maxVal), 1+smallSumSubset(temp,target-data[0], maxVal)) ;
    }
}

