        k2=h*dydx(x0+0.5*h,y+0.5*k1);
        k3=h*dydx(x0+0.5*h,y+0.5 *(-1+sqrt(2))*k1+k2 *(1-0.5*sqrt(2)));
        k4=h*dydx(x0+h,y -(0.5*sqrt(2))*k2+k3 *(1+0.5*sqrt(2)));
        y=y +(1.0/6)*(k1 +(2-sqrt(2))*k2 +(2+sqrt(2))*k3+k4);
        x0=x0+h ;
    }
    return y;
}

