int maxResult(vector<int> &nums, int k)
  {
    int n = nums.size();
    vector<int> dp(n, 0);

    // {max value, index}
    priority_queue<pair<int, int>> pq;
    dp[0] = nums[0];
    pq.push({nums[0], 0});
    for (int i = 1; i < n; ++i)
    {
      while (pq.size() && pq.top().second < i - k)
        pq.pop();

      auto curr = pq.top();
      dp[i] = curr.first + nums[i];
      pq.push({dp[i], i});
    }

    return dp[n - 1];
  }

