        for(int pile: piles) pq.push(pile);

        for(int i = 0; i < k && !pq.empty(); i ++){
            int e = pq.top(); pq.pop();
            pq.push(e - e / 2);
        }

        int res = 0;
        while(!pq.empty()){
            res += pq.top(); pq.pop();
        }
        return res;
    }

