ListNode* deleteNodes(ListNode* head, int m, int n) {

        ListNode* prev = head;
        while(prev){
            for(int i = 1; i < m && prev; i ++)
                prev = prev->next;
            if(!prev) break;

            ListNode* prev2 = prev->next;
            for(int i = 1; i < n && prev2; i ++)
                prev2 = prev2->next;
            if(!prev2){
                prev->next = nullptr;
                break;
            }
            prev->next = prev2->next;
            prev = prev2->next;
        }
        return head;
    }

int bestStartingPoint(string &word, int n) {
        int i = 0; //best starting point
        int j = 1; //keep moving to find the best starting point

        while(j < n) {
            int k = 0;

            //skipping equal characters
            while( j+k < n && word[i+k] == word[j+k]) {
                k++;
            }

            if(j+k < n && word[j+k] > word[i+k]) {
                i = j; //updating best starting point
                j = j+1;
            } else {
                j = j + k + 1; //skipping already checked characters
            }
        }

        return i;
    }

int eliminateMaximum(vector<int>& dist, vector<int>& speed) {

        int n = dist.size();
        vector<int> t(n);
        for(int i = 0; i < n; i ++)
            t[i] = dist[i] / speed[i] + !!(dist[i] % speed[i]);

        sort(t.begin(), t.end());

        int cur = 0;
        for(int i = 0; i < n; i ++, cur ++)
            if(cur >= t[i]) return i;
        return n;
    }

