        for(int i = 2; i < n; i ++){
            if(nums[i] == nums[i - 1] && dp[i - 2 + 1])
                dp[i + 1] = true;
            if(nums[i] == nums[i - 1] && nums[i - 1] == nums[i - 2] && dp[i - 3 + 1])
