        for(int i = 0; i < n; i ++) maxv[i][i] = arr[i];
        for(int d = 1; d < n; d ++)
            for(int i = 0; i + d < n; i ++)
                maxv[i][i + d] = max(maxv[i][i + d - 1], maxv[i + 1][i + d]);

        vector<vector<int>> dp(n, vector<int>(n, INT_MAX));
        for(int i = 0; i < n; i ++) dp[i][i] = 0;
        for(int d = 1; d < n; d ++)
