                for(int mid = i; mid < i + d; mid ++)
                    dp[i][i + d] = min(dp[i][i + d], dp[i][mid] + dp[mid + 1][i + d] + maxv[i][mid] * maxv[mid + 1][i + d]);
        return dp[0][n - 1];
    }

