vector<vector<int>> flipAndInvertImage(vector<vector<int>>& A) {

        int R = A.size();
        if(R == 0) return A;

        int C = A[0].size();
        if(C == 0) return A;

        for(int i = 0; i < R; i ++){

            int l = 0, r = C - 1;
            while(l < r) swap(A[i][l ++], A[i][r --]);

            for(int& e: A[i]) e = !e;
        }
        return A;
    }

int dfs(const vector<int>& arr, int d, int pos, vector<int>& dp){

        if(dp[pos] != -1) return dp[pos];

        int res = 1;
        for(int i = pos - 1; i >= 0 && i >= pos - d; i --)
            if(arr[i] < arr[pos])
                res = max(res, 1 + dfs(arr, d, i, dp));
            else break;

        for(int i = pos + 1; i < arr.size() && i <= pos + d; i ++)
            if(arr[i] < arr[pos])
                res = max(res, 1 + dfs(arr, d, i, dp));
            else break;

        return dp[pos] = res;
    }

bool canConstruct(string s, int k) {

        if(s.size() < k) return false;
        if(s.size() == k) return true;

        vector<int> freq(26, 0);
        for(char c: s) freq[c - 'a'] ++;

        int odd = 0;
        for(int e: freq) if(e % 2) odd ++;

        while(odd && k) k --, odd --;
        return odd < 1;
    }

