long long int findProduct(long long int N) {
    long long int product=1,fact=1;
    long long int MOD=1e9+7;
    for(int i=1;i<=N;i ++) {
        fact=mulmod(fact,i,MOD);
        product=mulmod(product,fact,MOD);
        if(product==0)return 0 ;
    }
    return product;
}

