int maxTwoEvents(vector<vector<int>>& events) {
        int n = events.size();
        int result = 0;

        for (int i = 0; i < n; i++) {
            result = max(result, events[i][2]); // Consider single event's value

            int val = events[i][2];
            for (int j = 0; j < n; j++) {
                if (i == j)
                    continue;

                if (events[j][0] <= events[i][1] && events[j][1] >= events[i][0])
                    continue;

                result = max(result, val + events[j][2]);
            }
        }
        return result;
    }

