int removeCoveredIntervals(vector<vector<int>> &intervals)
  {
    int n = intervals.size(), ans = 0;
    for (int i = 0; i < n; ++i)
    {
      int inside = 0;
      for (int j = 0; j < n; ++j)
      {
        if (i != j && intervals[j][0] <= intervals[i][0] && intervals[i][1] <= intervals[j][1])
          inside = 1;
      }
      if (!inside)
        ans++;
    }
    return ans;
  }

