int findPeakElement(vector<int>& nums) {

        if(nums.size() == 1) return 0;

        int n = nums.size();
        if(nums[0] > nums[1]) return 0;
        if(nums[n - 1] > nums[n - 2]) return n - 1;

        for(int i = 1; i + 1 < n; i ++)
            if(nums[i] > nums[i - 1] && nums[i] > nums[i + 1])
                return i;
        return -1;
    }

int largestCombination(vector<int>& candidates) {
        //vector<int> count(24, 0); //O(24)
        //count[i] = how many numbers have ith bit set

        int result = 0;

        for(int i = 0; i < 24; i++) { //O(24)
            int count_ith = 0;

            for(int &num : candidates) { //O(n)
                if((num & (1 << i)) != 0) {
                    count_ith += 1;
                }
            }

            result = max(result, count_ith);

        }

        return result;
    }

unsigned long long ClosestIntSameBitCount(unsigned long long x) {
  const static int kNumUnsignedBits = 64;
  for (int i = 0; i < kNumUnsignedBits - 1; ++i) {
    if (((x >> i) & 1) != ((x >> (i + 1)) & 1)) {
      x ^= (1UL << i) | (1UL << (i + 1));  // Swaps bit-i and bit-(i + 1).
      return x;
    }
  }

  // Throw error if all bits of x are 0 or 1.
  throw invalid_argument("All bits are 0 or 1");
}

