int minDistance(string A, string B)
  {
    vector<vector<int>> dp(A.size() + 1, vector<int>(B.size() + 1, 0));
    for (int i = 1; i <= A.size(); ++i)
    {
      for (int j = 1; j <= B.size(); ++j)
      {
        if (A[i - 1] == B[j - 1])
          dp[i][j] = 1 + dp[i - 1][j - 1];
        else
          dp[i][j] = max(dp[i][j - 1], dp[i - 1][j]);
      }
    }

    return A.size() + B.size() - 2 * dp[A.size()][B.size()];
  }

int triangleNumber(vector<int>& nums) {
        int n = nums.size();
        int count = 0;

        // check all triplets
        for(int i = 0; i < n; i++) {
            for(int j = i+1; j < n; j++) {
                for(int k = j+1; k < n; k++) {
                    if(nums[i] + nums[j] > nums[k] &&
                       nums[i] + nums[k] > nums[j] &&
                       nums[j] + nums[k] > nums[i]) {
                        count++;
                    }
                }
            }
        }

        return count;
    }

bool canReach(vector<int>& arr, int start) {

        queue<int> q;
        vector<bool> visited(arr.size(), false);

        q.push(start);
        visited[start] = true;
        while(!q.empty()){
            int cur = q.front();
            q.pop();

            if(!arr[cur]) return true;

            if(cur - arr[cur] >= 0 && !visited[cur - arr[cur]])
                q.push(cur - arr[cur]), visited[cur - arr[cur]] = true;
            if(cur + arr[cur] < arr.size() && !visited[cur + arr[cur]])
                q.push(cur + arr[cur]), visited[cur + arr[cur]] = true;
        }
        return false;
    }

int countStudents(vector<int>& students, vector<int>& sandwiches) {
        int len = students.size();
        queue<int> que;
        stack<int> st;

        for (int i = 0; i < len; i++) {
            st.push(sandwiches[len - i - 1]);
            que.push(students[i]);
        }

        int lastServed = 0;
        while (!que.empty() && lastServed < que.size()) {
            if (st.top() == que.front()) {
                st.pop();
                que.pop();
                lastServed = 0;
            } else {
                que.push(que.front());
                que.pop();
                lastServed++;
            }
        }

        return que.size();
    }

