int reachNumber(int target)
  {
    target = abs(target);
    long long n = ceil((-1.0 + sqrt(1 + 8.0 * target)) / 2);
    long long sum = n * (n + 1) / 2;
    if (sum == target)
      return n;
    long long res = sum - target;
    if ((res & 1) == 0)
      return n;
    else
      return n + ((n & 1) ? 2 : 1);
  }

int destroyTargets(vector<int>& nums, int space) {

        map<int, int> f;
        map<int, int> min_res;
        for(int e: nums){
            f[e % space] ++;

            if(min_res.count(e % space)) min_res[e % space] = min(min_res[e % space], e);
            else min_res[e % space] = e;
        }

        int maxf = 0;
        for(const pair<int, int>& p: f)
            maxf = max(maxf, p.second);

        int res = INT_MAX;
        for(const pair<int, int>& p: f)
            if(p.second == maxf)
                res = min(res, min_res[p.first]);

        return res;
    }

