int crossSum(const vector<int>& nums, int l, int mid, int r){

        int lres = nums[mid];
        int sum = lres;
        for(int i = mid - 1; i >= l; i --){
            sum += nums[i];
            lres = max(lres, sum);
        }

        int rres = nums[mid + 1];
        sum = rres;
        for(int i = mid + 2; i <= r; i ++){
            sum += nums[i];
            rres = max(rres, sum);
        }

        return lres + rres;
    }

