using namespace std;
int minSumProd(string S,int K) {
    int len=S.length();
    if(K>len)return -1;
    if(K==len)return 0;
    vector<int>dp(len);
    int count_zero=0,count_one=0;
    for(int j=0;j<len;j ++) {
        (S[j]== '0')? count_zero++: count_one ++;
        dp[j]= count_zero*count_one ;
    }
    for(int i=1;i<K;i ++) {
        for(int j=len;j>=i;j --) {
            count_zero=0,count_one=0;
            dp[j]= INT_MAX;
            for(int k=j;k>=i;k --) {
                (S[k]== '0')? count_zero++: count_one ++;
                dp[j]= min(dp[j], count_zero*count_one+dp[k-1]) ;
            }
        }
    }
    return dp[len-1];
}

TreeNode* buildTree(const vector<int>& nums, int l, int r){

        if(l > r) return NULL;
        if(l == r) return new TreeNode(nums[l]);

        int mid = (l + r) / 2;
        TreeNode* root = new TreeNode(nums[mid]);
        root->left = buildTree(nums, l, mid - 1);
        root->right = buildTree(nums, mid + 1, r);
        return root;
    }

