int dfs(const vector<int>& nums, int index, int res, int S){

        if(index == nums.size())
            return res == S;

        int ret = 0;
        ret += dfs(nums, index + 1, res - nums[index], S);
        ret += dfs(nums, index + 1, res + nums[index], S);
        return ret;
    }

int findTheWinner(int n, int k) {
        vector<int> arr;
        for(int i = 1; i <= n; i++) {
            arr.push_back(i);
        }

        int i = 0; //Game starts from 1st player which is sitting at index 0 in arr

        while(arr.size() > 1) {
            int idx = (i + k - 1) % arr.size();

            arr.erase(arr.begin() + idx);

            i = idx;
        }

        return arr[0];
    }

