double s2s2_alpha(double x0, double y0,
                  double x1, double y1,
                  double x2, double y2,
                  double x3, double y3)
{
  const double s1_dx = x0 - x1,
               s1_dy = y0 - y1,
               s2_dx = x3 - x2,
               s2_dy = y3 - y2,
               lx    = x3 - x1,
               ly    = y3 - y1;
  double val = std::fma(lx,s2_dy,-ly*s2_dx)/std::fma(s1_dx,s2_dy,-s1_dy*s2_dx);
  if (val!=val) return 0.5;
  if (val<0) return 0;
  if (val>1) return 1;
  return val;
}

