int maximumLength(vector<int>& nums) {
        unordered_map<int64_t, int> cnt;
        for (const auto& x : nums) {
            ++cnt[x];
        }
        int result = 0;
        for (const auto& k_v : cnt) {
            int64_t x = k_v.first;
            if (x == 1) {
                result = max(result, cnt[x] - (cnt[x] % 2 == 0 ? 1 : 0));
                continue;
            }
            int l = 0;
            for (; cnt.count(x) && cnt[x] >= 2; x *= x) {
                l += 2;
            }
            l += cnt.count(x) ? 1 : -1;
            result = max(result, l);
        }
        return result;
    }

