int minOperations(vector<int>& nums, int x) {
        int n    = nums.size();
        int sum  = 0;
        unordered_map<int, int> mp;
        mp[0] = -1;
        for(int i = 0; i<n; i++) {
            sum += nums[i];
            mp[sum] = i;
        }
        if(sum < x)
            return -1;
        int restSum  = sum-x;
        int longest  = INT_MIN;
        sum = 0;
        for(int i = 0; i<n; i++) {
            sum += nums[i];
            if(mp.count(sum-restSum)) {
                longest = max(longest, i-mp[sum-restSum]);
            }
        }

        return longest==INT_MIN?-1:n-longest;
    }

using namespace std;
int downToZero(int n) {
    if(n<=3)return n;
    vector<int>dp(n+1,-1);
    dp[0]= 0;
    dp[1]= 1;
    dp[2]= 2;
    dp[3]= 3;
    int sqr;
    for(int i=4;i<=n;i ++) {
        sqr=sqrt(i);
        int best=INT_MAX;
        while(sqr>1) {
            if(i%sqr==0) {
                best=min(best,1+dp[sqr]) ;
            }
            sqr--;
        }
        best=min(best,1+dp[i-1]);
        dp[i]= best ;
    }
    return dp[n];
}

int maxIncreasingGroups(vector<int>& usageLimits) {
