}

int maxResult(vector<int>& nums, int k) {

        int n = nums.size();
        vector<int> dp(n, nums[0]);

        priority_queue<pair<int, int>> pq;
        pq.push({nums[0], 0});

        for(int i = 1; i < nums.size(); i ++){

            dp[i] = nums[i] + pq.top().first;
            pq.push({dp[i], i});

            while(!pq.empty() && pq.top().second <= i - k)
                pq.pop();
        }
        return dp.back();
    }

