TreeNode* trimBST(TreeNode* root, int low, int high) {
        if(!root)
            return root;

        if(root->val < low) //because we need to look for higher values
            return trimBST(root->right, low, high);

        else if(root->val > high) //because we need to look for lower values
            return trimBST(root->left, low, high);

        //call inorder (DFS)
        root->left = trimBST(root->left, low, high);
        root->right = trimBST(root->right, low, high);

        return root;
    }

int findTheLongestBalancedSubstring(string s) {

        int n = s.size();

        vector<pair<int, int>> segs;
        for(int start = 0, i = 1; i <= n; i ++){
            if(i == n || s[i] != s[start]){
                segs.push_back({s[start] - '0', i - start});
                start = i;
            }
        }

        int res = 0;
        for(int i = 0; i + 1 < (int)segs.size(); i ++)
            if(segs[i].first == 0 && segs[i + 1].first == 1)
                res = max(res, 2 * min(segs[i].second, segs[i + 1].second));
        return res;
    }

