        for(int i = 1; i < r.size(); i ++){
            int p1 = r[i - 1][0], h1 = r[i - 1][1];
            int p2 = r[i][0], h2 = r[i][1];

            int x = ((long long)h2 - h1 + p1 + p2) / 2ll;
            res = max(res, h1 + x - p1);
        }
        return res;
    }

