int trap(vector<int>& height) {

        if(height.size() <= 2)
            return 0;

        int res = 0;
        for(int i = 1; i < height.size() - 1; i ++) {
            int lmax = height[i], rmax = height[i];
            for (int l = i - 1; l >= 0; l --)
                lmax = max(lmax, height[l]);
            for(int r = i + 1; r < height.size(); r ++)
                rmax = max(rmax, height[r]);
            res += min(lmax, rmax) - height[i];
        }
        return res;
    }

