TreeNode* inOrder(TreeNode* node, TreeNode* &tail){

        if(node->left == NULL && node->right == NULL){
            tail = node;
            return node;
        }

        TreeNode* ret;
        if(node->left){
            ret = inOrder(node->left, tail);
            tail->left = NULL;
            tail->right = node;
        }
        else
            ret = node;

        node->left = NULL;
        tail = node;
        if(node->right) {
            TreeNode *root = inOrder(node->right, tail);
            node->right = root;
        }

        return ret;
    }

