long long subArrayRanges(vector<int>& nums) {

        int n = nums.size();
        long long res = 0;
        for(int l = 0; l < n; l ++){
            int minv = nums[l], maxv = nums[l];
            for(int r = l + 1; r < n; r ++){
                minv = min(minv, nums[r]), maxv = max(maxv, nums[r]);
