vector<vector<int>> findMatrix(vector<int>& nums) {
        vector<vector<int>> result;
        unordered_map<int, int> cnt;
        for (const auto& x : nums) {
            ++cnt[x];
        }
        while (!empty(cnt)) {
            unordered_map<int, int> new_cnt;
            result.emplace_back();
            for (const auto& [k, v] : cnt) {
                result.back().emplace_back(k);
                if (v - 1) {
                    new_cnt[k] = v - 1;
                }
            }
            cnt = move(new_cnt);
        }
        return result;
    }

