vector<int> twoSum(vector<int> &nums, int target)
  {
    unordered_map<int, int> prev;
    for (int i = 0; i < nums.size(); ++i)
    {
      int tar = target - nums[i];
      if (prev.find(tar) != prev.end())
        return {prev[tar], i};
      else
        prev[nums[i]] = i;
    }
    return {-1, -1};
  }

