vector<int> xorQueries(vector<int>& arr, vector<vector<int>>& queries) {
        int n = arr.size();

        vector<int> cumXor(n, 0); //space : O(n)

        cumXor[0] = arr[0];
        for(int i = 1; i < n; i++) { //O(n)
            cumXor[i] = cumXor[i-1] ^ arr[i];
        }

        vector<int> result;
        for(vector<int>& query : queries) { //O(q)
            int L = query[0];
            int R = query[1];

            int xor_val = cumXor[R] ^ (L == 0 ? 0 : cumXor[L-1]);

            result.push_back(xor_val);
        }

        return result;
    }

int binarySearchableNumbers(vector<int>& nums) {

        int n = nums.size();
        vector<bool> left(n, true);

        int maxv = nums[0];
        for(int i = 1; i < n; i ++){
            left[i] = maxv < nums[i];
            maxv = max(maxv, nums[i]);
        }

        vector<bool> right(n, true);
        int minv = nums[n - 1];
        for(int i = n - 2; i >= 0; i --){
            right[i] = minv > nums[i];
            minv = min(minv, nums[i]);
        }

        int res = 0;
        for(int i = 0; i < n; i ++) res += (left[i] && right[i]);
        return res;
    }

std::int64_t binExpo(std::int64_t a, std::int64_t b, std::int64_t m) {
  a %= m;
  std::int64_t res = 1;
  while (b > 0) {
    if (b % 2 != 0) {
      res = res * a % m;
    }
    a = a * a % m;
    // Dividing b by 2 is similar to right shift by 1 bit
    b >>= 1;
  }
  return res;
}

int partition (int arr[], int low, int high) {
        int pivot      = arr[high];
        int pivotIndex = low;

        for(int i = low; i < high; i++) {
            if(arr[i] <= pivot) {
                swap(arr[i], arr[pivotIndex]);
                pivotIndex++;
            }
        }

        swap(arr[pivotIndex], arr[high]);

        return pivotIndex;
    }

