            // considering the suffix from pos i
            // [arr[i], arr[i+1], ... arr[n-1]]
               // 1         2
            for(int j = i; j < n; j++) {
                cur += (j-i+1) * arr[j];
            }
            ans = max(ans, cur);
        }
        return ans;
    }

