int maxUncrossedLines(vector<int>& A, vector<int>& B) {

        vector<int> dp(B.size() + 1, 0);
        for(int i = 1; i <= A.size(); i ++){
            for(int j = B.size(); j >= 1; j --)
                if(A[i - 1] == B[j - 1])
                    dp[j] = 1 + dp[j - 1];
            for(int j = 1; j <= B.size(); j ++)
                dp[j] = max(dp[j], dp[j - 1]);
        }

        return dp[B.size()];
    }

