int search(ArrayReader &reader, int l, int r){

        if(l == r) return l;

        int len = (r - l + 1);
        if(len & 1){
            int res = search(reader, l, r - 1);
            return res == -1 ? r : res;
        }

        int mid = (l + r) / 2;
        int x = reader.compareSub(l, mid, mid + 1, r);
        if(x == 1) return search(reader, l, mid);
        else if(x == 0) return -1;
        else return search(reader, mid + 1, r);
    }

