int search(vector<int>& nums, int target) {

        if(nums.size() == 0) return -1;
        int max_index = max_element(nums.begin(), nums.end()) - nums.begin();

        int l = 0, r = max_index;
        while(l <= r){
            int mid = l + (r - l) / 2;
            if(nums[mid] == target) return mid;
            if(target < nums[mid]) r = mid - 1;
            else l = mid + 1;
        }

        l = max_index + 1, r = nums.size() - 1;
        while(l <= r){
            int mid = l + (r - l) / 2;
            if(nums[mid] == target) return mid;
            if(target < nums[mid]) r = mid - 1;
            else l = mid + 1;
        }

        return -1;
    }

