long long factorial(int n) {
    long long ans=1;
    while(n>=1) {
        ans*=n;
        n--;
    }
    return ans ;
}
void Binary_Num(int n,int k) {
    long long num_even,num_odd;
    if(n-k-1>=0&&k-1>=0) {
        num_even=factorial(n-2)/(factorial(k-1)* factorial(n-k-1)) ;
    }
    else {
        num_even=0 ;
    }
    if(k-2>=0) {
        num_odd=factorial(n-2)/(factorial(k-2)* factorial(n-k)) ;
    }
    else {
        num_odd=0 ;
    }
    cout<<num_even<<" ? "<<num_odd<<endl;
}

