long long minOperations(vector<int>& nums1, vector<int>& nums2, int k) {
        int64_t cnt1 = 0, cnt2 = 0;
        for (int i = 0; i < size(nums1); ++i) {
            if (nums1[i] == nums2[i]) {
                continue;
            }
            if (k == 0 || (nums1[i] - nums2[i]) % k) {
                return -1;
            }
            if (nums1[i] < nums2[i]) {
                cnt1 += static_cast<int64_t>(nums2[i] - nums1[i]) / k;
            } else {
                cnt2 += static_cast<int64_t>(nums1[i] - nums2[i]) / k;
            }
        }
        return cnt1 == cnt2 ? cnt1 : -1;
    }

void twoSum(vector<vector<int>>& result, vector<int>& nums, int i, int j, int n, int target) {
        int k = j+1, l = n-1;
        while(k<l) {
            if(nums[k] + nums[l] > target)
                l--;
            else if(nums[k] + nums[l] < target)
                k++;
            else {
                result.push_back({nums[i], nums[j], nums[k], nums[l]});
                while( k < n-1 && nums[k] == nums[k+1]) k++;
                while(l  > 0 && nums[l] == nums[l-1]) l--;
                k++;
                l--;
            }
        }
    }

bool check(long long mid, vector<long long>& diff, int r, int k, int n) {
        vector<long long> tempDiff = diff;

        long long cumSum = 0; //it will give power of a city at any point of time

        for(int i = 0; i < n; i++) {
            cumSum += tempDiff[i];

            if(cumSum < mid) {
                long long need = mid - cumSum;
                if(need > k) {
                    return false;
                }

                k -= need;
                cumSum += need; //gredily I had chosen to add station on the city which can cover more range

                //i......X.....i+2*r
                if(i + 2*r + 1 < n)
                    tempDiff[i+2*r+1] -= need; //applying difference array technique
            }
        }

        return true;
    }

double getDelta(double avg, const vector<int>& nums, int k) {
        vector<double> accu(nums.size() + 1);
        int minval_pos = -1;
        double delta = 0.0;
        for (int i = 0; i < nums.size(); ++i) {
            accu[i + 1] = nums[i] + accu[i] - avg;
            if (i >= k - 1) {
                if (minval_pos == -1 || accu[i - k + 1] < accu[minval_pos]) {
                    minval_pos = i - k + 1;
                }
                if (accu[i+1] - accu[minval_pos] >= 0) {
                    delta = max(delta, (accu[i + 1] - accu[minval_pos]) / (i + 1 - minval_pos));
                }
            }
        }
        return delta;
    }

void dfs(TreeNode *root, vector<vector<int>> &ans, vector<int> &path, int target, int curr)
    {
        if (!root->left && !root->right)
        {
            path.push_back(root->val);
            if (curr + root->val == target)
                ans.push_back(path);
            path.pop_back();
            return;
        }

        path.push_back(root->val);
        if (root->left)
            dfs(root->left, ans, path, target, curr + root->val);
        if (root->right)
            dfs(root->right, ans, path, target, curr + root->val);
        path.pop_back();
    }

