void bfs(int i, unordered_map<int, vector<int>>& adj, vector<bool>& visited, int& v, int &e) {
        queue<int> que;
        que.push(i);
        visited[i] = true;

        while(!que.empty()) {
            int curr = que.front();
            que.pop();
            v++;
            e += adj[curr].size();

            for(int &ngbr : adj[curr]) {
                if(!visited[ngbr]) {
                    visited[ngbr] = true;
                    que.push(ngbr);
                }
            }
        }
    }

inline int matrix_log_get_pade_degree(double normTminusI)
{
  const double maxNormForPade[] = { 1.6206284795015624e-2 /* degree = 3 */ , 5.3873532631381171e-2,
            1.1352802267628681e-1, 1.8662860613541288e-1, 2.642960831111435e-1 };
  const int minPadeDegree = matrix_log_min_pade_degree<double>::value;
  const int maxPadeDegree = matrix_log_max_pade_degree<double>::value;
  int degree = minPadeDegree;
  for (; degree <= maxPadeDegree; ++degree)
    if (normTminusI <= maxNormForPade[degree - minPadeDegree])
      break;
  return degree;
}

int findDuplicate(vector<int> &nums)
  {
    int slow = nums[0], fast = nums[0];
    do
    {
      slow = nums[slow];
      fast = nums[nums[fast]];
    } while (slow != fast);

    fast = nums[0];
    while (slow != fast)
    {
      slow = nums[slow];
      fast = nums[fast];
    }
    return fast;
  }

