inline int sc_mod_seaside(int in, int hi) {
    // avoid the divide if possible
    const int lo = 0;
    if (in >= hi) {
        in -= hi;
        if (in < hi)
            return in;
    } else if (in < lo) {
        in += hi;
        if (in >= lo)
            return in;
    } else
        return in;


    int c;
    c = in % hi;
    if (c < 0)
        c += hi;
    return c;
}

