int getPrefixLength(string srcStr,string targetStr) {
    if(targetStr.length()==0)return 0;
    transform(srcStr.begin(),srcStr.end(),srcStr.begin() ,::tolower);
    transform(targetStr.begin(),targetStr.end(),targetStr.begin() ,::tolower);
    map<char,int>dictCount;
    int nUnique=0;
    for(char ch:targetStr) {
        if(dictCount.find(ch)== dictCount.end()) {
            nUnique+=1;
            dictCount[ch]= 0 ;
        }
        dictCount[ch]+= 1 ;
    }
    for(int i=0;i<srcStr.length();i ++) {
        char ch=srcStr[i];
        if(dictCount.find(ch)== dictCount.end())continue;
        dictCount[ch]-= 1;
        if(dictCount[ch]== 0)nUnique-=1;
        if(nUnique==0)return(i+1);
    }
    return -1;
}

