int minOperationsMaxProfit(vector<int>& customers, int boardingCost, int runningCost) {

        int k = 0, kres = -1, cp = 0, maxres = 0, curres = 0, waiting = 0;
        while(cp < customers.size() || waiting){
            if(cp < customers.size()) waiting += customers[cp];
            cp ++;

            int num = min(4, waiting);
            curres += boardingCost * num - runningCost;
            waiting -= num;

            k ++;
            if(curres > maxres){
                maxres = curres;
                kres = k;
            }
        }
        return kres;
    }

vector<int> sortArrayByParityII(vector<int>& A) {

        for(int i = 0; i < A.size(); i ++)
            if(i % 2 == 0 && A[i] % 2){
                int j = i + 1;
                for(; j < A.size(); j += 2)
                    if(A[j] % 2 == 0)
                        break;
                swap(A[i], A[j]);
            }
            else if(i % 2 && A[i] % 2 == 0){
                int j = i + 1;
                for(; j < A.size(); j += 2)
                    if(A[j] % 2)
                        break;
                swap(A[i], A[j]);
            }
        return A;
    }

int partitionArray(vector<int>& nums, int k) {

        sort(nums.begin(), nums.end());

        int res = 0;
        for(int start = 0, i = 1; i <= nums.size(); i ++)
            if(i == nums.size() || nums[i] - nums[start] > k){
                res ++;
                start = i;
            }
        return res;
    }

bool canArrange(vector<int>& arr, int k) {

        for(int& e: arr) e = (e % k + k) % k;
        sort(arr.begin(), arr.end());

        int l = 0;
        for(; l < arr.size() && arr[l] % k == 0; l ++);
        if(l % 2) return false;

        int r = arr.size() - 1;
        while(l < r){
            if((arr[l]  + arr[r]) % k) return false;
            l ++, r --;
        }
        return l > r;
    }

