        for(int i = 0; i < 9; i ++)
            if(cost[i] <= target) dp[cost[i]] = string(1, '0' + (1 + i));

        for(int k = 1; k <= target; k ++)
            for(int i = 8; i >= 0; i --)
                if(k > cost[i] && dp[k - cost[i]] != "" && 1 + dp[k - cost[i]].size() > dp[k].size())
                    dp[k] = string(1, '0' + (1 + i)) + dp[k - cost[i]];
        return dp[target].size() ? dp[target] : "0";
    }

