int LCS(vector<int>& nums1, vector<int>& nums2) {
        int m = nums1.size();
        int n = nums2.size();

        vector<vector<int>> t(m+1, vector<int>(n+1));
        //if length of nums1/num2 is 0, then LCS is 0
        for(int j = 0; j<n; j++) {
            t[0][j] = 0;
        }
        for(int i = 0; i<n; i++) {
            t[i][0] = 0;
        }

        for(int i = 1; i<m+1; i++) {
            for(int j = 1; j<n+1; j++) {
                if(nums1[i-1] == nums2[j-1])
                    t[i][j] = 1 + t[i-1][j-1];
                else
                    t[i][j] = max(t[i-1][j], t[i][j-1]);
            }
        }

        return t[m][n];
    }

int lengthOfLIS(vector<int>& nums) {
        int n = nums.size();
        vector<int> sorted;

        for(int i = 0; i<n; i++) {
            /*
                 Why lower bound ?
                 We want increasing subsequence and  hence
                 we want to eliminate the duplicates as well.
                 lower_bound returns iterator to "next greater or equal to"
            */
            auto it = lower_bound(begin(sorted), end(sorted), nums[i]);

            if(it == end(sorted))
                sorted.push_back(nums[i]); //greatest : so insert it
            else
                *it = nums[i]; //replace
        }

        return (int)sorted.size();
    }

bool check(unordered_map<int, vector<int>>& mp, int node, int dest, vector<bool>& visited) {
        if(node == dest)
            return true;

        if(visited[node])
            return false;

        visited[node] = true;
        for(auto &it : mp[node]) {
            if(check(mp, it, dest, visited))
                return true;
        }
        return false;
    }

