void split(node *cur, int pos, node *&l, node *&r, int add = 0) {
  node* t;
  copy(t, cur);
  if (t == nullptr) {
    l = r = nullptr;
    return;
  }
  int id = add + size(t -> l);
  if (id <= pos) {
    split(t->r, pos, l, r, id + 1);
    t->r = l;
    l = t;
  } else {
    split(t->l, pos, l, r, add);
    t->l = r;
    r = t;
  }
  update_size(t);
}

