  {
    for (int r = 0; r < A.size(); ++r)
    {
      int i = 0, j = A[r].size() - 1;
      while (i <= j)
      {
        A[r][i] ^= 1;
        if (i != j)
          A[r][j] ^= 1;
        swap(A[r][i], A[r][j]);
        i++;
        j--;
      }
    }
    return A;
  }

