        for(int i = 0; i < n; i++) pq.push({nums[i], i});

        while(!pq.empty()) {
            auto [val, idx] = pq.top();
            pq.pop();

            if(visited[idx]) continue;
            visited[idx] = true;
            if(idx > 0) visited[idx - 1] = true;
            if(idx + 1 < n) visited[idx + 1] = true;

            score += val;
        }
        return score;
    }

