int win(int need, int state, int M, int total, unordered_map<long long, int>& dp){

        if(need <= 0) return 1;
        if(total < need) return 0;

        long long hash = (1ll << M) * need + state;
        auto iter = dp.find(hash);
        if(iter != dp.end()) return iter->second;

        int w = 0, all = 0;
        for(int i = M; i >= 1; i --)
            if((state & (1 << (i - 1)))){
                all ++;
                int tres = win(need - i, state - (1 << (i - 1)), M, total - i, dp);
                if(tres == 1) return dp[hash] = 2;

                w += (tres == 2);
            }

        return dp[hash] = (all && w == all);
    }

int64_t find_non_repeating_integer(const std::vector<int>& nums) {
    // The idea is based on the property of XOR.
    // We know that 'a' XOR 'a' is '0' and '0' XOR 'b'
    // is b.
    // Using this, if we XOR all the elements of the array,
    // the repeating elements will give '0' and this '0'
    // with the single number will give the number itself.

    int _xor = 0;

    for (const int& num: nums) {
        _xor ^= num;
    }

    return _xor;
}

