        vec.push_back(node ? node->val : -1);
        if(!node)
            return;

        int L = node->left ? node->left->val : -1;
        int R = node->right ? node->right->val : -1;
        if(L <= R)
            dfs(node->left, vec), dfs(node->right, vec);
        else
            dfs(node->right, vec), dfs(node->left, vec);
    }

