bool isValidBST(TreeNode* node, int min, int max){

        if(node == NULL)
            return true;

        if(node->val < min || node->val > max)
            return false;

        if(node->left != NULL && node->left->val >= node->val)
            return false;

        if(node->right != NULL && node->right->val <= node->val)
            return false;

        return isValidBST(node->left, min, node->val - 1) && isValidBST(node->right, node->val + 1, max);
    }

string pushDominoes(string dominoes) {
        string s = "L" + dominoes + "R";
        int n    = s.length();
        string result = "";
        for(int i = 0, j = 1; j<n; j++) {
            if(s[j] == '.') continue;

            int midPartLength = j-i-1;
            if(i > 0)
                result.push_back(s[i]);

            if(s[i] == s[j])
                result += string(midPartLength, s[i]);
            else if(s[i] == 'L' && s[j] == 'R')
                result += string(midPartLength, '.');
            else
                result += string(midPartLength/2, 'R') + string(midPartLength%2, '.') + string(midPartLength/2, 'L');
            i = j;
        }

        return result;
    }

ListNode* mergeNodes(ListNode* head) {
        ListNode* P1 = head->next;
        ListNode* P2 = P1;

        while(P2 != NULL) {
            int sum = 0;
            while(P2 != NULL && P2->val != 0) {
                sum += P2->val;
                P2 = P2->next;
            }

            P1->val = sum;
            P2 = P2->next;
            P1->next = P2;
            P1 = P1->next;
        }

        return head->next;
    }

