int countBinarySubstrings(string s) {
        int n = s.length();
        vector<int> groups(n); //max there can be n groups (every consecutive character are different)
        int t = 0;
        groups[t] = 1;
        for(int i = 1; i<n; i++) {
            if(s[i-1] != s[i]) {
                groups[++t] = 1;
            } else {
                groups[t]++;
            }
        }

        int ans = 0;
        for(int  i = 1; i<=t; i++) {
            ans += min(groups[i-1], groups[i]);
        }

        return ans;
    }

