int minFlips(int a, int b, int c) {

        int res = 0;
        while(a || b || c){
            int abit  = a & 1, bbit = b & 1, cbit = c & 1;
            a >>= 1, b >>= 1, c >>= 1;

            if(cbit == 0) res += abit + bbit;
            else res += (abit | bbit) ? 0 : 1;
        }
        return res;
    }

int upper(const vector<int>& v, int t, int L, int R){

        if(L > R) return R + 1;
        int l = L, r = R + 1;
        while(l < r){
            int mid = (l + r) / 2;
            if(v[mid] > t) r = mid;
            else l = mid + 1;
        }
        return l;
    }

