ListNode *swapNodes(ListNode *head, int k)
  {
    int size = 0;
    auto temp = head;
    while (temp)
    {
      temp = temp->next;
      size++;
    }

    auto front = head, back = head;
    for (int i = 0; i < k - 1; ++i)
      front = front->next;
    for (int i = 0; i < size - k; ++i)
      back = back->next;
    swap(front->val, back->val);
    return head;
  }

