  {
    vector<long long> ans(n, -1);
    stack<long long> st;

    for (int i = n - 1; i >= 0; --i)
    {
      while (st.size() && st.top() <= arr[i])
      {
        st.pop();
      }

      if (!st.size())
        ans[i] = -1;
      else
        ans[i] = st.top();
      st.push(arr[i]);
    }
    return ans;
  }

