bool isSafe(vector<vector<int>> &board, int r, int c)
  {
    int n = board.size();
    for (int i = 0; i < n; ++i)
    {
      if (board[r][i] == 1)
        return false;
      if (board[i][c] == 1)
        return false;
    }

    for (int i = r, j = c; i >= 0 && j >= 0; --i, --j)
    {
      if (board[i][j] == 1)
        return false;
    }

    for (int i = r, j = c; i >= 0 && j < n; --i, ++j)
    {
      if (board[i][j] == 1)
        return false;
    }
    return true;
  }

