        int res = nums[l], cur = nums[l];
        for(int i = l + 1; i <= r; i ++){
            cur *= nums[i];
            res = max(res, cur);
        }

        res = max(res, nums[r]);
        cur = nums[r];
        for(int i = r - 1; i >= l; i --){
            cur *= nums[i];
            res = max(res, cur);
        }
