Vec_f calc_s(Vec_f x, Vec_f y){
    Vec_f ds;
    Vec_f out_s{0};
    Vec_f dx = vec_diff(x);
    Vec_f dy = vec_diff(y);

    for(unsigned int i=0; i<dx.size(); i++){
      ds.push_back(std::sqrt(dx[i]*dx[i] + dy[i]*dy[i]));
    }

    Vec_f cum_ds = cum_sum(ds);
    out_s.insert(out_s.end(), cum_ds.begin(), cum_ds.end());
    return out_s;
  }

bool canJump(vector<int> &nums)
  {
    if (nums.size() <= 1)
      return true;

    int n = nums.size();
    int last_reachable = n - 1;

    for (int i = n - 2; i >= 0; --i)
    {
      if (i + nums[i] >= last_reachable)
        last_reachable = i;
    }

    return last_reachable == 0;
  }

