        cout<<0;
        return ;
    }
    int maxfreq=INT_MIN;
    char maxchar;
    unordered_map<char,int>um;
    for(int i=0;i<N;i ++) {
        um[S[i]] ++;
        if(um[S[i]]>maxfreq) {
            maxfreq=um[S[i]];
            maxchar=S[i];
        }
