bool isCyclicUtil(vector<int> g[], int V, int start, vector<bool>& visited) {
    vector<int> parent(V, -1);
    queue<int> que;
    que.push(start);
    visited[start] = true;
    while(!que.empty()) {
        int curr = que.front();
        que.pop();

        for(auto x : g[curr]) {
            if(visited[x] == false) {
                que.push(x);
                visited[x] = true;
                parent[x] = curr;
            }
            else if(parent[curr] != x)
                return true;
        }
    }

    return false;
}

vector<int> findFactors(int number){
  vector<int> factors;
  stack<int> other_factors;
  double midroot = floor(sqrt(number)) + 1;
  for(int guess = 1; guess < midroot; guess++){
    if(guess == 1 || number % guess == 0){
      factors.push_back(guess);
      int other_factor = number / guess;
      if(guess != other_factor){
        other_factors.push(other_factor);
      }
    }
  }
  while(!other_factors.empty()){
    factors.push_back(other_factors.top());
    other_factors.pop();
  }
  return factors;
}

