        int k = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (nums[mid] < target) {
                k = mid;         // mid is valid
                l = mid + 1;     // try to go right
            } else {
                r = mid - 1;     // go left
            }
        }
        return k;
    }

