int cntRotations(char s[],int n) {
    int lh=0,rh=0,i,ans=0;
    for(i=0;i<n/2;++ i)if(s[i]== ' a ' s[i]== ' e ' s[i]== ' i ' s[i]== ' o ' s[i]== ' u ') {
        lh++;
    }
    for(i=n/2;i<n;++ i)if(s[i]== ' a ' s[i]== ' e ' s[i]== ' i ' s[i]== ' o ' s[i]== ' u ') {
        rh++;
    }
    if(lh>rh)ans ++;
    for(i=1;i<n;++ i) {
        if(s[i-1]== ' a ' s[i-1]== ' e ' s[i-1]== ' i ' s[i-1]== ' o ' s[i-1]== ' u ') {
            rh ++;
            lh--;
        }
        if(s[( i-1+n/2)% n]== ' a '||s[( i-1+n/2)% n]== ' e '||s[( i-1+n/2)% n]== ' i '||s[( i-1+n/2)% n]== ' o '||s[( i-1+n/2)% n]== ' u ') {
            rh --;
            lh++;
        }
        if(lh>rh)ans++;
    }
    return ans;
}

