string breakPalindrome(string palindrome) {

        if(palindrome == "a") return "";

        int n = palindrome.size();
        for(int i = 0; i < n; i ++)
            if(palindrome[i] > 'a'){
                if(n % 2 == 1 && i == n / 2) continue;
                palindrome[i] = 'a';
                return palindrome;
            }

        for(int i = palindrome.size() - 1; i >= 0; i --)
            if(palindrome[i] < 'z'){
                if(n % 2 == 1 && i == n / 2) continue;
                palindrome[i] = 'b';
                return palindrome;
            }

        return "";
    }

int findMaxForm(int k, int m, int n, vector<vector<vector<int>>>& dp,
                    const vector<int>& mcost, const vector<int>& ncost){

        if(k < 0)
            return 0;

        if(dp[k][m][n] != -1)
            return dp[k][m][n];

        dp[k][m][n] = findMaxForm(k - 1, m, n, dp, mcost, ncost);
        if(m >= mcost[k] && n >= ncost[k])
            dp[k][m][n] = max(1 + findMaxForm(k - 1, m - mcost[k], n - ncost[k], dp, mcost, ncost),
                              dp[k][m][n]);

        return dp[k][m][n];
    }

