long long countGood(vector<int>& nums, int k) {

        map<int, int> f;
        long long cur = 0, res = 0;
        int n = nums.size(), l = 0, r = -1;
        while(l < n){
            if(r + 1 < n && cur < k){
                cur += f[nums[r + 1]];
                f[nums[r + 1]] ++;
                r ++;
            }
            else{
                f[nums[l]] --;
                cur -= f[nums[l]];
                l ++;
            }
            if(cur >= k) res += n - r;
        }
        return res;
    }

