        for(int i = 0; i < target.size(); i ++)
            map[target[i]] = i;

        vector<int> v;
        for(int e: arr)
            if(map.count(e)) v.push_back(map[e]);

        // LIS
        vector<int> dp;
        for(int e: v)
            if(dp.empty() || e > dp.back()) dp.push_back(e);
