int dfs(const string& s, int start, set<string>& bag){

        if(start == s.size())
            return bag.size();

        int res = 0;
        for(int end = start; end <= s.size(); end ++)
            if(!bag.count(s.substr(start, end - start + 1))){
                bag.insert(s.substr(start, end - start + 1));
                res = max(res, dfs(s, end + 1, bag));
                bag.erase(s.substr(start, end - start + 1));
            }
        return res;
    }

int maximumSwap(int num) {
        string s = to_string(num); //stoi
        int n = s.length();

        vector<int> maxRight(n); //stores the index of max element to right

        maxRight[n-1] = n-1;
        for(int i = n-2; i >= 0; i--) {
            int rightMaxIdx = maxRight[i+1];
            int rightMaxElement = s[rightMaxIdx];

            maxRight[i] = (s[i] > rightMaxElement) ? i : rightMaxIdx;
        }

        for(int i = 0; i < n; i++) {
            int maxRightIdx = maxRight[i];
            int maxRightElement = s[maxRightIdx];
            if(s[i] < maxRightElement) {
                swap(s[i], s[maxRightIdx]);
                return stoi(s);
            }
        }

        return num;
    }

