int leastInterval(vector<char> &tasks, int n)
  {
    vector<int> freq(26, 0);
    int Max = 0, maxCount = 0;
    for (auto &task : tasks)
    {
      freq[task - 'A']++;
      if (Max == freq[task - 'A'])
        maxCount++;
      else if (Max < freq[task - 'A'])
      {
        Max = freq[task - 'A'];
        maxCount = 1;
      }
    }

    int partCount = Max - 1;
    int partLength = n - (maxCount - 1);
    int emptySlots = partCount * partLength;
    int availableTasks = tasks.size() - (Max * maxCount);
    int idles = max(0, emptySlots - availableTasks);

    return tasks.size() + idles;
  }

int thirdMax(vector<int>& nums) {

        int count = 0, maxv = INT_MIN;
        int a = INT_MIN, b = INT_MIN, c = INT_MIN;
        for(int e: nums){
            if(count == 0) a = e, count ++;
            else if(count == 1 && e != a) b = e, count ++;
            else if(count == 2 && e != a && e != b) c = e, count ++;
            else if(count == 3 && e > c && e != a && e != b) c = e;

            if(b < c) swap(b, c);
            if(a < b) swap(a, b);

            maxv = max(maxv, e);
        }
        return count < 3 ? maxv : c;
    }

