int inorder(TreeNode *root, int k, int &val)
  {
    int ans = INT_MAX;

    if (root->left)
      ans = inorder(root->left, k, val);
    if (ans != INT_MAX)
      return ans;

    val++;
    if (val == k)
      return (root->val);

    if (root->right)
      ans = inorder(root->right, k, val);
    return ans;
  }

static void inline HashFinal(uint32_t& a, uint32_t& b, uint32_t& c)
{
    // Taken from lookup3, by Bob Jenkins.
    c ^= b;
    c -= ((b << 14) | (b >> 18));
    a ^= c;
    a -= ((c << 11) | (c >> 21));
    b ^= a;
    b -= ((a << 25) | (a >> 7));
    c ^= b;
    c -= ((b << 16) | (b >> 16));
    a ^= c;
    a -= ((c << 4) | (c >> 28));
    b ^= a;
    b -= ((a << 14) | (a >> 18));
    c ^= b;
    c -= ((b << 24) | (b >> 8));
}

vector<int> getModifiedArray(int length, vector<vector<int>> &updates) {
        vector<int> nums(length);

        for(vector<int> &vec : updates) {
            int start    = vec[0];
            int end_next = vec[1]+1;
            int update   = vec[2];

            nums[start] += update;
            if(end_next < length)
                nums[end_next] -= update;

        }

        for(int i = 1; i<length; i++)
            nums[i] += nums[i-1];

        return nums;
    }

