string isPossible(string S,int R,int N) {
    int cntl=0,cntr=0;
    int cntu=0,cntd=0;
    for(int i=0;i<N;i ++) {
        if(S[i]== ' L ')cntl ++;
        else if(S[i]== ' R ')cntr ++;
        else if(S[i]== ' U ')cntu ++;
        else cntd++;
    }
    if(max(max(cntl,cntr), max(cntu,cntd))>=R)return " Yes ";
    unordered_map<int,int>mp;
    int r_square=R*R;
    for(int i=1;i*i<=r_square;i ++) {
        mp[i*i]= i;
        if(mp.find(r_square-i*i)!= mp.end()) {
            if(max(cntl,cntr)>= mp[r_square-i*i]&& max(cntu,cntd)>= i)return " Yes ";
            if(max(cntl,cntr)>= i&&max(cntu,cntd)>= mp[r_square-i*i]) return " Yes " ;
        }
    }
    return " No ";
}

