bool hasSquareOfZeroes(vector<vector<int>>& matrix,int r1,int c1,int r2,int c2,unordered_map<string,bool >&cache) {
    if(r1>=r2 c1>=c2)return false;
    string key=to_string(r1)+ '-'+to_string(c1)+ '-'+to_string(r2)+ '-'+to_string(c2);
    if(cache.find(key)!= cache.end())return cache[key];
    cache[key]= isSquareOfZeroes(matrix,r1,c1,r2,c2)|| hasSquareOfZeroes(matrix,r1+1,c1+1,r2-1,c2-1,cache)|| hasSquareOfZeroes(matrix,r1,c1+1,r2-1,c2,cache)|| hasSquareOfZeroes(matrix,r1+1,c1,r2,c2-1,cache)|| hasSquareOfZeroes(matrix,r1+1,c1+1,r2,c2,cache)|| hasSquareOfZeroes(matrix,r1,c1,r2-1,c2-1,cache);
    return cache[key];
}
