int solve(int n,int m,int x,int y,int d) {
    int top=min(d,x-1);
    int down=min(d,n-x);
    int left=min(d,y-1);
    int right=min(d,m-y);
    int quad1=top*left;
    int quad2=left*down;
    int quad3=down*right;
    int quad4=right*top;
    int totalsq=quad1+quad2+quad3+quad4;
    int singleBlocks=top+down+left+right+1;
    return totalsq+singleBlocks;
}

