vector<int> maxSlidingWindow(vector<int> &nums, int k)
  {
    list<pair<int, int>> window;
    vector<int> ans;

    for (int i = 0; i < nums.size(); ++i)
    {
      auto curr = nums[i];
      while (window.size() && window.front().second <= i - k)
        window.pop_front();
      while (window.size() && window.back().first < curr)
        window.pop_back();
      window.push_back({curr, i});
      if (i >= k - 1)
        ans.push_back(window.front().first);
    }

    return ans;
  }

void induced_sort(const vector<int> &vec, int val_range, vector<int> &SA, const vector<bool> &sl, const vector<int> &lms_idx) {
  vector<int> l(val_range, 0), r(val_range, 0);
  for (int c : vec) {
    if (c + 1 < val_range) ++l[c + 1];
    ++r[c];
  }
  partial_sum(l.begin(), l.end(), l.begin());
  partial_sum(r.begin(), r.end(), r.begin());
  fill(SA.begin(), SA.end(), -1);
  for (int i = lms_idx.size() - 1; i >= 0; --i)
    SA[--r[vec[lms_idx[i]]]] = lms_idx[i];
  for (int i : SA)
    if (i >= 1 && sl[i - 1]) {
      SA[l[vec[i - 1]]++] = i - 1;
    }
  fill(r.begin(), r.end(), 0);
  for (int c : vec)
    ++r[c];
  partial_sum(r.begin(), r.end(), r.begin());
  for (int k = SA.size() - 1, i = SA[k]; k >= 1; --k, i = SA[k])
    if (i >= 1 && !sl[i - 1]) {
      SA[--r[vec[i - 1]]] = i - 1;
    }
}

