    map<vector<int >,int>mp;
    int ans=0;
    for(int i=0;i<N;i ++) {
        vector<int>a(26,0);
        for(int j=0;j<s[i ].size();j ++) {
            a[s[i ][j]- ' a ']++ ;
        }
        for(int j=0;j<26;j ++) {
            a[j]= a[j]% 2 ;
        }
        ans+=mp[a];
        for(int j=0;j<26;j ++) {
            vector<int>changedCount=a;
            if(a[j]== 0)changedCount[j]= 1;
            else changedCount[j]= 0;
            ans+=mp[changedCount];
        }
        mp[a]++ ;
    }
    return ans;
}

using namespace std;
void findAngles(double a,double b,double c,double d) {
    double numerator=a*a+d*d-b*b-c*c;
    double denominator=2 *(a*b+c*d);
    double x=numerator/denominator;
    cout<<fixed<<setprecision(2)<< " A : ? " <<(acos(x)* 180)/ 3.141592<<" ? degrees ";
    numerator=a*a+b*b-c*c-d*d;
    x=numerator/denominator;
    cout<<fixed<<setprecision(2)<< " STRB : ? " <<(acos(x)* 180)/ 3.141592<<" ? degrees ";
    numerator=c*c+b*b-a*a-d*d;
    x=numerator/denominator;
    cout<<fixed<<setprecision(2)<< " STRC : ? " <<(acos(x)* 180)/ 3.141592<<" ? degrees ";
    numerator=d*d+c*c-a*a-b*b;
    x=numerator/denominator;
    cout<<fixed<<setprecision(2)<< " STRD : ? " <<(acos(x)* 180)/ 3.141592<<" ? degrees ";
}

