const int MAX=100;
int countEndless(bool input[][MAX], int n) {
    bool row[n ][n], col[n ][n];
    for(int j=0;j<n;j ++) {
        bool isEndless=1;
        for(int i=n-1;i>=0;i --) {
            if(input[i ][j]== 0)isEndless=0;
            col[i ][j]= isEndless ;
        }
    }
    for(int i=0;i<n;i ++) {
        bool isEndless=1;
        for(int j=n-1;j>=0;j --) {
            if(input[i ][j]== 0)isEndless=0;
            row[i ][j]= isEndless ;
        }
    }
    int ans=0;
    for(int i=0;i<n;i ++)for(int j=1;j<n;j ++)if(row[i ][j]&& col[i ][j]) ans ++;
    return ans;
}

int ComputeXChooseY(int x, int y, vector<vector<int>>* x_choose_y_ptr) {
  if (y == 0 || x == y) {
    return 1;
  }

  vector<vector<int>>& x_choose_y = *x_choose_y_ptr;
  if (x_choose_y[x][y] == 0) {
    int without_y = ComputeXChooseY(x - 1, y, x_choose_y_ptr);
    int with_y = ComputeXChooseY(x - 1, y - 1, x_choose_y_ptr);
    x_choose_y[x][y] = without_y + with_y;
  }
  return x_choose_y[x][y];
}

int Divide(int x, int y) {
  int result = 0;
  int power = 32;
  unsigned long long y_power = static_cast<unsigned long long>(y) << power;
  while (x >= y) {
    while (y_power > x) {
      y_power >>= 1;
      --power;
    }

    result += 1 << power;
    x -= y_power;
  }
  return result;
}

