int maxScoreSightseeingPair(vector<int>& values) {
        int n = values.size();

        vector<int> vec(n, 0);
        //vec[i] = stores the maximum value of (values[i]+i) till index i in values wala array
        vec[0] = values[0] + 0;

        for(int i = 1; i < n; i++) {
            vec[i] = max(values[i]+i, vec[i-1]);
        }

        int result = 0;

        for(int j = 1; j < n; j++) {
            int x = values[j]-j;
            int y = vec[j-1]; //max value of (values[i]+i) in left hand side

            result = max(result, x+y);
        }

        return result;
    }

vector<int> findIndices(vector<int>& nums, int indexDifference, int valueDifference) {
        for (int i = 0, mx_i = 0, mn_i = 0; i + indexDifference < size(nums); ++i) {
            if (nums[i] > nums[mx_i]) {
                mx_i = i;
            } else if (nums[i] < nums[mn_i]) {
                mn_i = i;
            }
            // we don't need to add abs for the difference since
            // - if nums[mx_i]-nums[i+indexDifference] < 0, then checking nums[i+indexDifference]-nums[mn_i] >= -(nums[mx_i]-nums[i+indexDifference]) > 0 can cover the case
            // - if nums[i+indexDifference]-nums[mn_i] < 0, then checking nums[mx_i]-nums[i+indexDifference] >= -(nums[i+indexDifference]-nums[mn_i]) > 0 can cover the case
            if (nums[mx_i] - nums[i + indexDifference] >= valueDifference) {
                return {mx_i, i + indexDifference};
            }
            if (nums[i + indexDifference] - nums[mn_i] >= valueDifference) {
                return {mn_i, i + indexDifference};
            }
        }
        return {-1, -1};
    }

int query(const vector<vector<int>>& points, int x, int y, int r){

        int res = 0;
        for(const vector<int>& p: points)
            res += (x - p[0]) * (x - p[0]) + (y - p[1]) * (y - p[1]) <= r * r;
        return res;
    }

int specialArray(vector<int>& nums) {

        sort(nums.begin(), nums.end());
        for(int x = 0; x <= nums.size(); x ++){
            vector<int>::iterator iter = lower_bound(nums.begin(), nums.end(), x);
            if(nums.end() - iter == x) return x;
        }
        return -1;
    }

string longestPalindrome(string s) {

        if(s == "") return s;

        int best = 0, n = s.size();
        string res = "";
        for(int center = 0; center < n; center ++){
            int len = 1, x;
            for(x = 1; x <= min(center, n - (center + 1)) && s[center - x] == s[center + x]; x ++)
                len += 2;
            if(len > best)
                best = len, res = s.substr(center - x + 1, len);
        }

        for(int center = 0; center + 1 < n; center ++)
            if(s[center] == s[center + 1]){
                int len = 2, x;
                for(x = 1; x <= min(center, n - (center + 2)) && s[center - x] == s[center + 1 + x]; x ++)
                    len += 2;
                if(len > best)
                    best = len, res = s.substr(center - x + 1, len);
            }
        return res;
    }

bool twoSumBSTs(TreeNode* root1, TreeNode* root2, int target) {

        if(!root1) return false;
        if(search(root2, target - root1->val)) return true;
        if(twoSumBSTs(root1->left, root2, target)) return true;
        if(twoSumBSTs(root1->right, root2, target)) return true;
        return false;
    }

