double maxSubArraySum(double a[],int size) {
    double max_so_far=INT_MIN,max_ending_here=0;
    for(int i=0;i<size;i ++) {
        max_ending_here=max_ending_here+a[i];
        if(max_so_far<max_ending_here)max_so_far=max_ending_here;
