using namespace std;
int min_steps_required(int n,int m,int r,int c) {
    int i,j;
    int corner_steps_req=INT_MAX;
    i=1;
    j=1;
    corner_steps_req=min(corner_steps_req,abs(r-i)+ abs(j-c));
    i=n;
    j=1;
    corner_steps_req=min(corner_steps_req,abs(r-i)+ abs(j-c));
    i=1;
    j=m;
    corner_steps_req=min(corner_steps_req,abs(r-i)+ abs(j-c));
    i=n;
    j=m;
    corner_steps_req=min(corner_steps_req,abs(r-i)+ abs(j-c));
    int minimum_steps=min(2 *(n-1)+ m-1,2 *(m-1)+ n-1);
    return minimum_steps+corner_steps_req;
}

double ComputeSupportsAnglePseudoSplit ( EventPtr const& aEvent )
  {
    PseudoSplitEvent& lEvent = dynamic_cast<PseudoSplitEvent&>(*aEvent) ;

    Vector_2 lV1 ;
    Vector_2 lV2 ;

    if(lEvent.is_at_source_vertex())
    {
      // is_at_source_vertex <=> opposite node is seed0
      lV1 = Vector_2( aEvent->point(), lEvent.seed1()->point() );
      lV2 = Vector_2( aEvent->point(), aEvent->point() + CreateVector(aEvent->triedge().e2()) ) ;
    }
    else
    {
      lV1 = Vector_2( aEvent->point(), lEvent.seed0()->point() );
      lV2 = Vector_2( aEvent->point(), aEvent->point() - CreateVector(aEvent->triedge().e2()) ) ;
    }

    return ComputeApproximateAngle(lV1, lV2) ;
  }

vector<int> findAnagrams(string s, string p) {
        vector<int> result;
        if (p.empty() || s.empty()) {
            return result;
        }

        vector<int> cnts(26);
        for (const auto& c : p) {
            ++cnts[c - 'a'];
        }

        for (int left = 0, right = 0; right < s.length(); ++right) {
            --cnts[s[right] - 'a'];
            while (left <= right && cnts[s[right] - 'a'] < 0) {
                ++cnts[s[left++] - 'a'];
            }
            if (right - left + 1 == p.length()) {
                result.emplace_back(left);
            }
        }
        return result;
    }

