using namespace std;
int nthElement(int a,int b,int n) {
    vector<int>seq;
    for(int i=1;i<=n;i ++)seq.push_back(a*i);
    sort(seq.begin(),seq.end());
    for(int i=1,k=n;i<=n&&k;i ++) {
        if(! binary_search(seq.begin(),seq.end(),b*i)) {
            seq.push_back(b*i);
            sort(seq.begin(),seq.end());
            k--;
        }
    }
    return seq[n-1];
}

