vector<int> mergeKArrays(vector<vector<int>> arr, int K)
{
  vector<int> ans;
  priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>> pq;

  for (int i = 0; i < K; ++i)
  {
    pq.push({arr[i][0], i, 0});
  }

  while (pq.size())
  {
    auto curr = pq.top();
    pq.pop();
    int val = curr[0];
    int r = curr[1], c = curr[2];

    ans.push_back(val);
    if (c + 1 < K)
    {
      pq.push({arr[r][c + 1], r, c + 1});
    }
  }
  return ans;
}

bool recursion(int n, set<int> &s)
  {
    if (n == 0)
      return false;
    if (n == 1)
      return true;
    if (s.find(n) != s.end())
      return false;

    s.insert(n);
    int newNum = 0;
    while (n)
    {
      int digit = n % 10;
      n = n / 10;
      newNum += digit * digit;
    }

    return recursion(newNum, s);
  }

int maxOverlap(vector<vector<int>>& A, vector<vector<int>>& B) {
        int n = A.size();
        int count = 0;
        for(int x_shift = 0; x_shift<n; x_shift++) {
            for(int y_shift = 0; y_shift<n; y_shift++) {
                int temp = 0;
                for(int i = y_shift; i<n; i++) { //because y-shift changes row
                    for(int j = x_shift; j<n; j++) { //because x-shift changes column
                        if(A[i][j] == 1 && B[i-y_shift][j-x_shift] == 1)
                            temp++;
                    }
                }
                count = max(count, temp);
            }
        }
        return count;
    }

