int countOfWays(string s,int k) {
    int N=s.size();
    LL ans=0;
    for(int i=0;i<N;i ++) {
        if(s[i]== '5' s[i]== '0') {
            ans =(ans+exp_mod(2,i))%MOD ;
        }
    }
    LL q=exp_mod(2,N);
    LL qk=exp_mod(q,k);
    LL inv=exp_mod(q-1,MOD-2);
