vector<int> arrayRankTransform(vector<int>& arr) {

        map<int, int> rank;
        for(int e: arr) rank[e] = 0;

        int r = 1;
        for(const pair<int, int>& p: rank){
            rank[p.first] = r ++;
        }

        vector<int> res(arr.size());
        for(int i = 0; i < arr.size(); i ++)
            res[i] = rank[arr[i]];
        return res;
    }

int maximumBags(vector<int>& capacity, vector<int>& rocks, int additionalRocks) {

        int n = capacity.size();
        for(int i = 0; i < n; i ++)
            capacity[i] -= rocks[i];

        sort(capacity.begin(), capacity.end());
        for(int i = 0; i < n; i ++)
            if(capacity[i] <= additionalRocks){
                additionalRocks -= capacity[i];
                capacity[i] = 0;
            }

        int res = 0;
        for(int e: capacity) res += e == 0;
        return res;
    }

int maxSubArray(vector<int>& nums) {
        int n = nums.size();
        int ans = INT_MIN;

        // vector<int> dp(n+1, 0); // O(N) extra space
        // dp[i] = max subarray sum starting from index i
        // mandate to pick something
        int nextMax = 0;
        for(int i = n-1; i >= 0; i--) {
            // dp[i] = max(nums[i] + dp[i+1], 0)
            // dp[i] = nums[i] + max(dp[i+1], 0);
            int curMax = nums[i] + max(nextMax, 0);
            ans = max(ans, curMax);
            nextMax = curMax;
        }

        return ans;
    }

static unsigned isGrayICCProfile(const unsigned char* profile, unsigned size) {
  /*
  It is a gray profile if bytes 16-19 are "GRAY", rgb profile if bytes 16-19
  are "RGB ". We do not perform any full parsing of the ICC profile here, other
  than check those 4 bytes to grayscale profile. Other than that, validity of
  the profile is not checked. This is needed only because the PNG specification
  requires using a non-gray color model if there is an ICC profile with "RGB "
  (sadly limiting compression opportunities if the input data is grayscale RGB
  data), and requires using a gray color model if it is "GRAY".
  */
  if(size < 20) return 0;
  return profile[16] == 'G' &&  profile[17] == 'R' &&  profile[18] == 'A' &&  profile[19] == 'Y';
}

