int maxCount(vector<int>& banned, int n, int maxSum) {

        sort(banned.begin(), banned.end());

        int banned_index = 0, res = 0, sum = 0;
        for(int i = 1; i <= n; i ++){
            if(banned_index < banned.size() && i == banned[banned_index]){
                while(banned_index < banned.size() && i == banned[banned_index])
                    banned_index ++;
            }
            else if(sum + i > maxSum) break;
            else{
                res ++;
                sum += i;
            }
        }
        return res;
    }

void Rearrange(vector<int>* A_ptr) {
  vector<int>& A = *A_ptr;
  for (size_t i = 1; i < size(A); ++i) {
    if ((!(i % 2) && A[i - 1] < A[i]) || ((i % 2) && A[i - 1] > A[i])) {
      swap(A[i - 1], A[i]);
    }
  }
}

long long countAlternatingSubarrays(vector<int>& nums) {
        long long count = 0;
        int n = nums.size();

        for (int i = 0; i < n; ++i) {
            int j = i;

            while (j + 1 < n && nums[j] != nums[j + 1]) {
                ++j;
            }

            int len = j - i + 1;
            count += (long long)len * (len + 1) / 2;
            i = j;
        }

        return count;
    }

