int maxHeight(vector<vector<int>>& cuboids) {
        for (auto& cuboid : cuboids) {
            sort(begin(cuboid), end(cuboid));
        }
        cuboids.push_back({0, 0, 0});
        sort(begin(cuboids), end(cuboids));
        vector<int> dp(size(cuboids));
        for (int i = 1; i < size(cuboids); ++i) {
            for (int j = 0; j < i; ++j) {
                if (cuboids[j][0] <= cuboids[i][0] &&
                    cuboids[j][1] <= cuboids[i][1] &&
                    cuboids[j][2] <= cuboids[i][2]) {
                    dp[i] = max(dp[i], dp[j] + cuboids[i][2]);
                }
            }
        }
        return *max_element(cbegin(dp), cend(dp));
    }

int totalMoney(int n) {
        int terms = n/7; //Weeks

        int first = 28;
        int last  = 28 + (terms - 1) * 7; //AP formula for n-th term

        int result = terms * (first + last) / 2; //Sum of nth terms in an AP


        //Final week remaining days = n%7
        int start_money = 1 + terms;

        for(int day = 1; day <= (n%7); day++) {
            result += start_money;
            start_money++;
        }

        return result;
    }

