int maxScoreSightseeingPair(vector<int>& A) {

        int n = A.size();

        vector<int> B = A;
        for(int i = 0; i < n; i ++) B[i] -= i;
        for(int i = n - 2; i >= 0; i --)
            B[i] = max(B[i], B[i + 1]);

        int res = A[0] + B[1];
        for(int i = 1; i + 1 < n; i ++)
