int binary_search(MountainArray &mountainArr, int l, int r, int target, bool is_inc){

        while(l <= r){
            int mid = (l + r) / 2;
            int e = mountainArr.get(mid);
            if(e == target) return mid;

            if(is_inc){
                if(e < target) l = mid + 1;
                else r = mid - 1;
            }
            else{
                if(e < target) r = mid - 1;
                else l = mid + 1;
            }
        }
        return -1;
    }

bool validMountainArray(vector<int>& A) {

        if(A.size() < 3)
            return false;

        int i;
        for(i = 1; i < A.size(); i ++)
            if(A[i] < A[i - 1])
                break;
            else if(A[i] == A[i - 1])
                return false;

        if(i == 1 || i == A.size())
            return false;

        for(int j = i; j < A.size(); j ++)
            if(A[j - 1] <= A[j])
                return false;

        return true;
    }

void max_heapify(int arr[], int start, int end) {
    //建立父節點指標和子節點指標
    int dad = start;
    int son = dad * 2 + 1;
    while (son <= end) { //若子節點指標在範圍內才做比較
        if (son + 1 <= end && arr[son] < arr[son + 1]) //先比較兩個子節點大小，選擇最大的
            son++;
        if (arr[dad] > arr[son]) //如果父節點大於子節點代表調整完畢，直接跳出函數
            return;
        else { //否則交換父子內容再繼續子節點和孫節點比較
            swap(arr[dad], arr[son]);
            dad = son;
            son = dad * 2 + 1;
        }
    }
}

inline char const * generic_error_category_message( int ev, char * buffer, std::size_t len ) noexcept
{
    if( len == 0 )
    {
        return buffer;
    }

    if( len == 1 )
    {
        buffer[0] = 0;
        return buffer;
    }

    char const * m = std::strerror( ev );

    if( m == 0 ) return "Unknown error";

    std::strncpy( buffer, m, len - 1 );
    buffer[ len-1 ] = 0;

    return buffer;
}

