inline double tet_volume(vec3 p1, vec3 p2, vec3 p3, vec3 p4) {
        double Ux = p2.x - p1.x;
        double Uy = p2.y - p1.y;
        double Uz = p2.z - p1.z;

        double Vx = p3.x - p1.x;
        double Vy = p3.y - p1.y;
        double Vz = p3.z - p1.z;

        double Wx = p4.x - p1.x;
        double Wy = p4.y - p1.y;
        double Wz = p4.z - p1.z;

        double UVx = Uy * Vz - Uz * Vy;
        double UVy = Uz * Vx - Ux * Vz;
        double UVz = Ux * Vy - Uy * Vx;

        return ::fabs(
            UVx * Wx + UVy * Wy + UVz * Wz
        ) / 6.0;
    }

