int lengthOfLIS(vector<int> &nums)
  {
    int n = nums.size();
    vector<int> dp(n, 1);

    if (n <= 1)
      return n;

    dp[0] = 1;
    int ans = INT_MIN;

    for (int i = 1; i < n; ++i)
    {
      int maxPrev = 0;
      for (int j = 0; j < i; ++j)
      {
        if (nums[j] < nums[i])
          maxPrev = max(maxPrev, dp[j]);
      }
      dp[i] = maxPrev + 1;
      ans = max(ans, dp[i]);
    }

    return ans;
  }

