        int n = candies.size();
        for(int i = k; i < n; i ++)
            f[candies[i]] ++;

        int res = f.size();
        for(int i = k; i < n; i ++){

            f[candies[i - k]] ++;
            f[candies[i]] --;
            if(f[candies[i]] == 0) f.erase(candies[i]);

