int minTime(int n, vector<vector<int>>& edges, int k) {
        sort(begin(edges), end(edges), [](const auto& a, const auto& b) {
            return a[2] > b[2];
        });
        int cnt = 0;
        UnionFind uf(n);
        for (const auto& e : edges) {
            if (!uf.union_set(e[0], e[1])) {
                continue;
            }
            if (cnt == n - k) {
                return e[2];
            }
            ++cnt;
        }
        return 0;
    }

