vector<int> decode(vector<int>& encoded) {

        int n = encoded.size() + 1;

        int start = 0;
        for(int i = 1; i <= n; i ++) start ^= i;
        for(int i = 1; i < encoded.size(); i += 2)
            start ^= encoded[i];

        vector<int> res = {start};
        for(int code: encoded)
            res.push_back(res.back() ^ code);
        return res;
    }

