bool findGameWinner(int n) {

        if(n == 1) return false;

        vector<int> dp(n, 0);
        dp[1] = 1;
        for(int i = 2; i < n; i ++)
            dp[i] = (dp[i - 1] ^ dp[i - 2]) + 1;
        return dp[n - 1] ^ dp[n - 2];
    }

