int kthSmallest(vector<vector<int>> &A, int k)
  {
    int n = A.size(), m = A[0].size();
    int l = A[0][0], h = A[n - 1][m - 1], ans;

    while (l < h)
    {
      int mid = (l + h) / 2;
      int count = 0, j = m - 1;

      for (int i = 0; i < n; ++i)
      {
        while (j >= 0 && A[i][j] > mid)
          j--;
        count += j + 1;
      }

      if (count < k)
        l = mid + 1;
      else
        h = mid;
    }
    return l;
  }

