        int n = arr.size();
        vector<vector<int>> dp(2, vector<int>(5001, 0));
        for(int j = arr[0]; j <= 5000; j ++)
            dp[0][j] = 1;
        for(int i = 1; i < n; i ++){
            for(int j = 0; j < arr[i]; j ++)
                dp[i & 1][j] = dp[(i - 1) & 1][j];
            for(int j = arr[i]; j <= 5000; j ++)
                dp[i & 1][j] = max(dp[(i - 1) & 1][j], 1 + dp[(i - 1) & 1][j - arr[i]]);
        }
