vector<int> findKDistantIndices(vector<int>& nums, int key, int k) {
        int n = nums.size();

        vector<int> result;

        for(int j = 0; j < n; j++) {
            if(nums[j] == key) {
                int start = max(j-k, 0);
                int end   = min(j+k, n-1);

                if(result.size() > 0 && result.back() >= start) {
                    start = result.back()+1;
                }

                for(int i = start; i <= end; i++) {
                    result.push_back(i);
                }
            }
        }
        return result;
    }

Node *mergeSort(Node *head)
{
  if (!head || !head->next)
    return head;

  auto mid = midNode(head);
  auto temp = head;

  while (temp->next != mid)
    temp = temp->next;
  temp->next = NULL;

  auto head2 = mid;

  head = mergeSort(head);
  head2 = mergeSort(head2);

  return merge(head, head2);
}

