bool checkGroup(vector<int>arr) {
    if(arr.size()<=2)return true;
    int corner=arr[0]+ arr[( int)arr.size()-1];
    int xorSum=0;
    for(int i=0;i<arr.size()-1;i ++)xorSum +=(arr[i]^ arr[i+1]);
    if(! corner)if(xorSum>2)return false;
    else if(corner==1)if(xorSum>1)return false;
    else if(xorSum>0)return false;
    return true ;
}
