int binaryGap(int n) {
        int curr = 0;
        int prev = -1;

        int result = 0;

        while(n > 0) {
            if((n&1) > 0) {
                result = (prev != -1) ? max(result, curr - prev) : result;
                prev = curr;
            }

            curr++;
            n >>= 1;
        }

        return result;
    }

bool dfs(int arr[], int i, int N, int sum, vector<vector<int>> &memo)
{
  if (sum == 0)
    return true;
  if (i == N)
    return false;

  if (memo[i][sum] != -1)
    return memo[i][sum];

  if (arr[i] > sum)
    return memo[i][sum] = dfs(arr, i + 1, N, sum, memo);

  return memo[i][sum] = dfs(arr, i + 1, N, sum, memo) || dfs(arr, i + 1, N, sum - arr[i], memo);
}

void DirectedPermutations(int i, vector<int> *A_ptr,
                          vector<vector<int>> *result) {
  vector<int> &A = *A_ptr;
  if (i == size(A) - 1) {
    result->emplace_back(A);
    return;
  }

  // Try every possibility for A[i].
  for (int j = i; j < size(A); ++j) {
    swap(A[i], A[j]);
    // Generate all permutations for A[i + 1, size(A) - 1].
    DirectedPermutations(i + 1, A_ptr, result);
    swap(A[i], A[j]);
  }
}

