        int minVal = 0;
        int maxVal = 0;

        for(int &d : differences) {
            curr = curr + d;

            minVal = min(minVal, curr);
            maxVal = max(maxVal, curr);

            if((upper - maxVal) - (lower - minVal) + 1 <= 0) {
