boolean judgeSquareSum(int c) {
        for (long a = 0; a * a <= c; a++) {
            int x = c - (int) (a * a);
            // b*b == x (we need to find the b which satisfies this)

            int b_start = 0, b_end = x;

            while (b_start <= b_end) {
                long mid = b_start + (b_end - b_start) / 2;

                if (mid * mid == x) {
                    return true;
                } else if (mid * mid < x) {
                    b_start = (int) mid + 1;
                } else {
                    b_end = (int) mid - 1;
                }
            }
        }
        return false;
    }

vector<int> sortArray(vector<int>& nums) {
        int minE = *min_element(begin(nums), end(nums));
        int maxE = *max_element(begin(nums), end(nums));

        unordered_map<int, int> mp;

        for(int &num : nums)
            mp[num]++;

        int i = 0;

        for(int num = minE; num <= maxE; num++) {

            while(mp[num] > 0) {
                nums[i] = num;
                i++;
                mp[num]--;
            }

        }

        return nums;
    }

