long long f(int n, const vector<int>& nums, int k){

        int l = 0, r = -1, cur_odd = 0;
        long long res = 0;
        while(l < n){
            if(r + 1 < n && cur_odd + nums[r + 1] % 2 <= k){
                r ++;
                res += (r - l + 1);
                cur_odd += nums[r] % 2;
            }
            else{
                cur_odd -= nums[l] % 2;
                l ++;
            }
        }
        return res;
    }

