int countCollisions(String directions) {
        int n = directions.length();

        int i = 0; // left boundary
        while (i < n && directions.charAt(i) == 'L') {
            i++;
        }

        int j = n - 1; // right boundary
        while (j >= 0 && directions.charAt(j) == 'R') {
            j--;
        }

        int collisions = 0;
        while (i <= j) {
            if (directions.charAt(i) != 'S') {
                collisions++;
            }
            i++;
        }

        return collisions;
    }

