vector<vector<int>> generate(int n)
  {
    if (n == 1)
      return {{1}};
    if (n == 2)
      return {{1}, {1, 1}};

    vector<vector<int>> ans = {{1}, {1, 1}};

    for (int i = 3; i <= n; ++i)
    {
      vector<int> temp(i, 0);
      temp[0] = 1;
      temp[i - 1] = 1;

      for (int j = 1; j < i - 1; ++j)
        temp[j] = ans[i - 2][j - 1] + ans[i - 2][j];

      ans.push_back(temp);
    }

    return ans;
  }

