    if(d<0)return -1;
    float root1 =(- b+sqrt(d)) /(2*a);
    float root2 =(- b-sqrt(d)) /(2*a);
    if(root1>0&&floor(root1)== root1)return root1;
    if(root2>0&&floor(root2)== root2)return root2;
    return -1 ;
}
