        int res = INT_MAX;
        for(const pair<int, int>& p: table)
            if((state & p.first) == p.first) {
                int t = dfs(table, state - p.first, dp);
                if(t != INT_MAX) res = min(res, p.second + t);
            }
        return dp[state] = res;
    }

