bool isPalindrome(Node *head)
{
  if (!head || !head->next)
    return true;

  auto mid = findMid(head);
  auto temp = head;

  while (temp->next != mid)
    temp = temp->next;
  temp->next = NULL;

  auto head1 = head;
  auto head2 = reverse(mid);

  while (head1 && head2)
  {
    if (head1->data != head2->data)
      return false;
    head1 = head1->next;
    head2 = head2->next;
  }
  return true;
}

int uniquePaths(int m, int n) {

        vector<vector<int>> dp(m, vector<int>(n, 1));
        for(int i = 1; i < m; i ++)
            for(int j = 1; j < n; j ++)
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
        return dp[m - 1][n - 1];
    }

