bool backtracking(int n, int i, vector<bool> *lookup, vector<int> *result) {
        if (i == size(*result)) {
            return true;
        }
        if ((*result)[i]) {
            return backtracking(n, i + 1, lookup, result);
        }
        for (int x = n; x >= 1; --x) {
            int j = (x == 1) ? i : i + x;
            if ((*lookup)[x] || j >= size(*result) || (*result)[j]) {
                continue;
            }
            (*result)[i] = (*result)[j] = x, (*lookup)[x] = true;
            if (backtracking(n, i + 1, lookup, result)) {
                return true;
            }
            (*result)[i] = (*result)[j] = 0, (*lookup)[x] = false;

        }
        return false;
    }

using namespace std;
int minimumAdjacentDifference(vector<int>a,int n,int k) {
    int minDiff=INT_MAX;
    for(int i=0;i<=k;i ++) {
        int maxDiff=INT_MIN;
        for(int j=0;j<n-k-1;j ++) {
            for(int p=i;p<=i+j;p ++) {
                maxDiff=max(maxDiff,a[p+1]- a[p]) ;
            }
        }
        minDiff=min(minDiff,maxDiff);
    }
    return minDiff;
}

