int getPairs(vector<int>A,vector<int>B,int n) {
    vector<int>D(n);
    for(int i=0;i<n;i ++) {
        D[i]= A[i]- B[i];
    }
    sort(D.begin(),D.end());
    long long total=0;
    for(int i=n-1;i>=0;i --) {
        if(D[i]> 0) {
            total+=n-i-1 ;
        }
        else {
            int k=upper_bound(D.begin(),D.end(),- D[i])-D.begin();
            total+=n-k ;
        }
    }
    return total;
}

long long subsequenceSumOr(vector<int>& nums) {
        uint64_t result = 0, cnt = 0;
        for (int i = 0; i < 64; ++i) {
            cnt >>= 1;
            for (const auto& x : nums) {
                cnt += (static_cast<int64_t>(x) >> i) & 1;
            }
            if (cnt) {
                result |= 1ull << i;
            }
        }
        return result;
    }

int dfs(const vector<int>& v, int index, int t, vector<vector<int>>& dp){

        if(index == v.size()) return 0;
        if(dp[index][t] != INT_MIN) return dp[index][t];
        return dp[index][t] = max(t * v[index] + dfs(v, index + 1, t + 1, dp),
                                  dfs(v, index + 1, t, dp));
    }

