int smallestSubstring(string a) {
    vector<string>a1;
    for(int i=0;i<a.size();i ++) {
        for(int j=i+1;j<a.size();j ++) {
            if(i!=j)a1.push_back(a.substr(i,j+1)) ;
        }
    }
    map<string,int>a2;
    for(string i:a1)a2[i]++;
    vector<string>freshlist;
    for(auto i:a2) {
        if(i.second==1)freshlist.push_back(i.first);
    }
    map<string,int>dictionary;
    for(auto i:freshlist) {
        dictionary[i]= i.size() ;
    }
    vector<int>newlist;
    for(auto i:dictionary)newlist.push_back(i.second);
    int ans=INT_MAX;
    for(int i:newlist)ans=min(ans,i);
    return ans;
}

