using namespace std;
void shortestSubarray(int*A,int N) {
    int i;
    int left_index;
    for(i=0;i<N-1;i ++) {
        if(A[i]+ 1!=A[i+1]) break ;
    }
    left_index=i;
    int right_index;
    for(i=N-1;i>=1;i --) {
        if(A[i]!= A[i-1]+ 1)break ;
    }
    right_index=i;
    int updated_right;
    int minLength=min(N-left_index-1,right_index);
    if(A[right_index]<= A[left_index]+ 1) {
        updated_right=right_index+A[left_index]- A[right_index]+ 1;
        if(updated_right<N)minLength=min(minLength,updated_right-left_index-1);
    }
    cout<<minLength;
}

