int solve(int n, int p) {
        if(n == 0) {
            return true;
        }

        if(pow(3, p) > n) {
            return false;
        }

        bool p_ko_lelo = solve(n - pow(3, p), p+1);

        bool p_ko_nahi_lo = solve(n, p+1);

        return p_ko_lelo || p_ko_nahi_lo;
    }

bool reachingPoints(int sx, int sy, int tx, int ty) {
        while (tx >= sx && ty >= sy) {
            if (tx < ty) {
                swap(sx, sy);
                swap(tx, ty);
            }
            if (ty > sy) {
                tx %= ty;
            } else {
                return (tx - sx) % ty == 0;
            }
        }
        return false;
    }

int waysToSplitArray(vector<int>& nums) {
        int n = nums.size();

        long long sum = 0;
        for(int &num : nums) {
            sum += num;
        }

        long long leftSum  = 0;
        long long rightSum = 0;
        int split = 0;

        for(int i = 0; i < n-1; i++) {
            leftSum += nums[i];

            rightSum = sum - leftSum;

            if(leftSum >= rightSum) {
                split++;
            }
        }
        return split;
    }

int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {

        if(startFuel >= target)
            return 0;

        int n = stations.size();
        vector<long long> dp(n + 1, 0);
        dp[0] = startFuel;

        for(int i = 0 ; i < n ; i ++)
            for(int t = i ; t >= 0 ; t --)
                if(dp[t] >= stations[i][0]){
                    dp[t + 1] = max(dp[t + 1], dp[t] + stations[i][1]);
                }

        for(int t = 0; t <= n; t ++)
            if(dp[t] >= target)
                return t;
        return -1;
    }

