int maximumSum(vector<int>& arr) {

        int n = arr.size();
        if(n == 1) return arr[0];

        vector<int> undropped(n, 0);
        undropped[0] = arr[0];
        for(int i = 1; i < n; i ++)
            if(undropped[i - 1] <= 0) undropped[i] = arr[i];
            else undropped[i] = arr[i] + undropped[i - 1];
//        cout << "dp1 : "; for(int e: dp1) cout << e << " "; cout << endl;

        int res = *max_element(undropped.begin(), undropped.end());
        vector<int> dropped(n, 0);
        dropped[1] = arr[1];
        for(int i = 2; i < n; i ++)
            dropped[i] = max(arr[i] + dropped[i - 1], arr[i] + undropped[i - 2]);
//        cout << "dp2 : "; for(int e: dp2) cout << e << " "; cout << endl;

        res = max(res, *max_element(dropped.begin() + 1, dropped.end()));
        return res;
    }

int lengthOfLastWord(string s) {

        //s.find_last_not_of(' ') : This function searches for the last character in the string s that is not equal to the space character ' '.
                                    //It returns the index of the last non-space character found, or string::npos if no such character is found.
        //s.erase(pos)            : This function removes characters from the string s, starting from the position pos specified as an argument.
                                    //It removes characters from pos until the end of the string.

        s.erase(s.find_last_not_of(' ') + 1); //Removes the trailing spaces

        // Find the last space character
        int lastSpace = s.find_last_of(' ');

        // Calculate the length of the last word
        return lastSpace == string::npos ? s.length() : s.length() - lastSpace - 1;

    }

double new21Game(int n, int k, int maxPts) {

        if(k == 0) return 1.0;

        vector<long double> p(k + maxPts, 0), presum(k + maxPts + 1, 0);
        p[0] = 1.0;
        presum[1] = 1.0;
        for(int i = 1; i < p.size(); i ++){
            int r = min(i - 1, k - 1), l = max(i - maxPts, 0);
            long double sum = presum[r + 1] - presum[l];
            p[i] = sum / maxPts;
            presum[i + 1] = presum[i] + p[i];
        }

        long double res = 0.0;
        for(int i = k; i <= n && i < p.size(); i ++) res += p[i];
        return res;
    }

