int numWays(int n, int k)
    {
        if (n == 1)
            return k;
        if (n == 2)
            return k * k;

        int prevTwo = k;
        int prevOne = k * k;

        int ans = prevTwo;

        for (int i = 3; i <= n; ++i)
        {
            ans = (k - 1) * prevOne + (k - 1) * prevTwo;
            prevTwo = prevOne;
            prevOne = ans;
        }

        return ans;
    }

