int maxSetBitCount(string s,int k) {
    int maxCount=0,n=s.length();
    int count=0;
    for(int i=0;i<k;i ++) {
        if(s[i]== '1')count++;
    }
    maxCount=count;
    for(int i=k;i<n;i ++) {
        if(s[i-k]== '1')count --;
        if(s[i]== '1')count ++;
        maxCount=max(maxCount,count);
    }
    return maxCount;
}

