int querySegmentTree(int start, int end, int i, int l, int r, int segmentTree[]) {
    if (l > end || r < start) {
        return INT_MAX;
    }

    if (l >= start && r <= end) {
        return segmentTree[i];
    }

    int mid = l + (r - l) / 2;
    return min(querySegmentTree(start, end, 2 * i + 1, l, mid, segmentTree),
               querySegmentTree(start, end, 2 * i + 2, mid + 1, r, segmentTree));
}

using namespace std;
const double pi=acos(-1.0);
double nGon(int N) {
    double proAngleVar;
    if(N%4==0) {
        proAngleVar=pi *(180.0/N)/ 180 ;
    }
    else {
        proAngleVar=pi *(180.0 /(2*N))/180 ;
    }
    double negX=1.0e+99,posX=-1.0e+99,negY=1.0e+99,posY=-1.0e+99;
    for(int j=0;j<N;++ j) {
        double px=cos(2*pi*j/N+proAngleVar);
        double py=sin(2*pi*j/N+proAngleVar);
        negX=min(negX,px);
        posX=max(posX,px);
        negY=min(negY,py);
        posY=max(posY,py);
    }
    double opt2=max(posX-negX,posY-negY);
    return(double)opt2/sin(pi/N)/ 2;
}

