int jump(vector<int>& nums) {
        int n = nums.size();
        vector<int> dp(n, INT_MAX - 1);
        // dp[i] = min steps to reach the end of array if we are at ith index
        dp[n-1] = 0;
        for(int i = n-2; i >= 0; i--) {
            for(int j = i+1; j <= i+nums[i]; j++) {
                if(j >= n) break;
                dp[i] = min(dp[i], 1 + dp[j]);
            }
        }

        return dp[0];
    }

