int count_numbers(int L,int R) {
    int ans=0;
    int LogR=log2(R)+ 1;
    for(int zero_bit=0;zero_bit<LogR;zero_bit ++) {
        int cur=0;
        for(int j=0;j<zero_bit;j ++) {
            cur |=(1LL<<j);
        }
        for(int j=zero_bit+1;j<LogR;j ++) {
            cur |=(1LL<<j);
            if(cur>=L&&cur<=R) {
                ans++;
            }
        }
    }
    return ans;
}

