        int n = A.size(), i = 0, j = n -1;
        vector<int> ret;
        while(i <= j)
            if(abs(A[i]) > abs(A[j]))
                ret.push_back(A[i] * A[i]), i ++;
            else
                ret.push_back(A[j] * A[j]), j --;
        reverse(ret.begin(), ret.end());
        return ret;
    }

