        for(int i = 0; i + 1 < X; i ++){
            cur += grumpy[i] * customers[i];
            sum += (1 - grumpy[i]) * customers[i];
        }

        for(int i = X - 1; i < customers.size(); i ++){
            cur += customers[i] * grumpy[i];
            sum += (1 - grumpy[i]) * customers[i];
