        //greedily I'll use bricks because ladder helps me to jump to next
    //building irrespective of the height difference

        int n = heights.size();
        int i = 0;
        for( ; i<n-1 ; i++) {
            if(heights[i] >= heights[i+1]) {
                continue;
            }

            int diff = heights[i+1] - heights[i];
            if(bricks >= diff) {
                bricks -= diff;
                continue;
            }

            if(ladders > 0) {
                ladders--;
            } else
                break;
        }
        return i;
    }

