int findMinx(int A,int B,int C,int K) {
    int start=1;
    int end=ceil(sqrt(K));
    while(start<=end) {
        int mid=start +(end-start)/ 2;
        int x=func(A,B,C,mid);
        int Y=func(A,B,C,mid-1);
        if(x>=K&&Y<K) {
            return mid ;
        }
        else if(x<K) {
            start=mid+1 ;
        }
        else {
            end=mid-1 ;
        }
    }
    return -1;
}

