            }
            prev = i;
            ++result;
        }
        return result;
    }

int GetHeightHelper(int cases, int drops, vector<vector<int>>* F) {
  if (cases == 0 || drops == 0) {
    return 0;
  } else if (cases == 1) {
    return drops;
  }
  if ((*F)[cases][drops] == -1) {
    (*F)[cases][drops] = GetHeightHelper(cases, drops - 1, F) +
                         GetHeightHelper(cases - 1, drops - 1, F) + 1;
  }
  return (*F)[cases][drops];
}

