        vector<pair<int, int>> pos(R * C + 1);
        for(int i = 0; i < R; i ++)
            for(int j = 0; j < C; j ++)
                pos[mat[i][j]] = {i, j};

        vector<int> rows(R, C), cols(C, R);
        for(int i = 0; i < arr.size(); i ++){
            int r = pos[arr[i]].first, c = pos[arr[i]].second;
            rows[r] --, cols[c] --;
            if(rows[r] == 0 || cols[c] == 0) return i;
        }
        return -1;
    }

