        return "0";
    } else if (num == 1) {
        return s;
    } else {
        int size = s.size();
        string result(size + 1, '0');
        int adv = 0;
        for(int i = size; i > 0; --i) {
            int val = num * (s[i - 1] - '0') + adv;
            adv = val / 10;
            result[i] = (val % 10) + '0';
