boolean predecessor(String prev, String curr) {
        int M = prev.length();
        int N = curr.length();

        if (M >= N || N - M != 1)
            return false;

        int i = 0, j = 0;
        while (i < M && j < N) {
            if (prev.charAt(i) == curr.charAt(j)) {
                i++;
            }
            j++;
        }
        return i == M;
    }

void comb(vector<int> c, int t, vector<int> smallAns, vector<vector<int>> &ans, int i)
  {
    if (t < 0)
      return;
    if (t == 0)
    {
      ans.push_back(smallAns);
      return;
    }

    for (int j = i; j < c.size(); ++j)
    {
      smallAns.push_back(c[j]);
      comb(c, t - c[j], smallAns, ans, j);
      smallAns.pop_back();
    }
  }

long long minimumRemoval(vector<int>& beans) {

        int n = beans.size();

        sort(beans.begin(), beans.end());
        vector<long long> presum(n + 1, 0);
        for(int i = 0; i < n; i ++) presum[i + 1] = presum[i] + beans[i];

        long long res = presum.back();
        for(int i = 0; i < n; i ++){
            if(i && beans[i] == beans[i - 1]) continue;

            long long tres = presum[i];
            tres += presum[n] - presum[i] - (long long)(n - i) * beans[i];
            res = min(res, tres);
        }
        return res;
    }

ll mod_count(ll a, ll m, ll c, ll n) {
  ++c; ++n;
  assert(m > 0);
  if (n == 0) return 0;
  a %= m; if (a < 0) a += m;
  ll extra_c = c / m; c %= m;
  if (c < 0) extra_c--, c += m;
  assert(0 <= c && c < m);
  ll ans = extra_c * n;
  ll extra_n = n / m; n %= m;
  if (n < 0) extra_n--, n += m;
  assert(0 <= n && n < m);
  if (extra_n) {
    ans += extra_n * (lattice_cnt(m, a + m, (a + m) * (m - 1)) - lattice_cnt(m, a + m, (a + m) * (m - 1) - c));
  }
  if (n) {
    ans += lattice_cnt(m, a + m, (a + m) * (n - 1)) - lattice_cnt(m, a + m, (a + m) * (n - 1) - c);
  }
  return ans;
}

