        vector<int> maxRight(10, -1); //0,1,2.....9

        for(int i = 0; i < n; i++) {
            int idx = s[i] - '0'; //'2' -'0' = 2
            maxRight[idx] = i;
        }

        for(int i = 0; i < n; i++) {
            char currChar = s[i];
            int currDigit = currChar - '0';

            for(int digit = 9; digit > currDigit; digit--) {
                if(maxRight[digit] > i) {
                    swap(s[i], s[maxRight[digit]]);
                    return stoi(s);
                }
            }
        }

        return num;
    }

