int lastMaterial(vector<int>& material) {

        priority_queue<int> pq;
        for(int e: material) pq.push(e);

        while(pq.size() >= 2){
            int a = pq.top(); pq.pop();
            int b = pq.top(); pq.pop();
            if(a - b) pq.push(a - b);
        }
        return pq.empty() ? 0 : pq.top();
    }

