void heapify(vector<int> &arr, int idx){
        int n = arr.size();
        int left = 2*idx + 1;
        int right = 2*idx + 2;

        if (idx >= n)
        return;
        int l = 2 * idx + 1;
        int r = 2 * idx + 2;
        int max;

        if (l < n && arr[l] > arr[idx]) max = l;
        else max = idx;

        if (r < n && arr[r] > arr[max]) max = r;

        if (max != idx) {
            swap(arr[max], arr[idx]);
            heapify(arr, max);
        }
    }

