            v[2 * i] = {lights[i][0] - lights[i][1], START};
            v[2 * i + 1] = {lights[i][0] + lights[i][1], END};
        }

        sort(v.begin(), v.end());

        int cur_brightness = 0, max_brightness = 0, res = INT_MIN;
        for(const pair<int, int>& p: v)
            if(p.second == START){
                cur_brightness ++;
                if(cur_brightness > max_brightness)
