        int n = ranks.size();

        ll l = 1;
        int maxR = *max_element(begin(ranks), end(ranks));
        ll r = 1LL * maxR * cars * cars;

        ll result = -1;
        //T.C: O(n * log(maxR*cars*cars));
        while(l <= r) { //log(maxR * cars * cars)
            ll mid = l + (r-l)/2;

            if(isPossible(ranks, mid, cars)) { //O(n)
