static unsigned invMatrix(float* m) {
  int i;
  /* double used instead of float for intermediate computations to avoid
  intermediate numerical precision issues */
  double e0 = (double)m[4] * m[8] - (double)m[5] * m[7];
  double e3 = (double)m[5] * m[6] - (double)m[3] * m[8];
  double e6 = (double)m[3] * m[7] - (double)m[4] * m[6];
  /* inverse determinant */
  double d = 1.0 / (m[0] * e0 + m[1] * e3 + m[2] * e6);
  float result[9];
  if((d > 0 ? d : -d) > 1e15) return 1; /* error, likely not invertible */
  result[0] = e0 * d;
  result[1] = ((double)m[2] * m[7] - (double)m[1] * m[8]) * d;
  result[2] = ((double)m[1] * m[5] - (double)m[2] * m[4]) * d;
  result[3] = e3 * d;
  result[4] = ((double)m[0] * m[8] - (double)m[2] * m[6]) * d;
  result[5] = ((double)m[3] * m[2] - (double)m[0] * m[5]) * d;
  result[6] = e6 * d;
  result[7] = ((double)m[6] * m[1] - (double)m[0] * m[7]) * d;
  result[8] = ((double)m[0] * m[4] - (double)m[3] * m[1]) * d;
  for(i = 0; i < 9; i++) m[i] = result[i];
  return 0; /* ok */
}

bool oneEditAway(string first, string second) {

        int n1 = first.size(), n2 = second.size();
        if(n1 == n2){

            int change = 0;
            for(int i = 0; i < n1; i ++)
                change += (first[i] != second[i]);
            return change <= 1;
        }

        if(abs(n1 - n2) > 1) return false;

        if(n1 > n2) swap(n1, n2), swap(first, second);

        // n1 < n2;
        for(int len = 0; len <= n1; len ++)
            if(first.substr(0, len) == second.substr(0, len) && first.substr(len) == second.substr(len + 1))
                return true;
        return false;
    }

std::uint32_t count_paths_dfs(const std::vector<std::vector<std::uint32_t>>& A,
                              std::uint32_t u,
                              std::uint32_t v,
                              std::uint32_t n,
                              std::vector<bool>& visited) {
        if (u == v) {
            return 1;  // Base case: Reached the destination node
        }

        visited[u] = true;  // Mark the current node as visited
        std::uint32_t path_count = 0;  // Count of all paths from `u` to `v`

        for (std::uint32_t i = 0; i < n; i++) {
            if (A[u][i] == 1 && !visited[i]) {  // Check if there is an edge and the node is not visited
                path_count += count_paths_dfs(A, i, v, n, visited);  // Recursively explore paths from `i` to `v`
            }
        }

        visited[u] = false;  // Unmark the current node as visited (backtracking)
        return path_count;
    }

static T lanczos_sum_near_2(const T& dz)
   {
      // LCOV_EXCL_START
      static const T d[5] = {
         static_cast<T>(0.6534966888520080645505805298901130485464L),
         static_cast<T>(0.006577461728560758362509168026049182707101L),
         static_cast<T>(-0.004480276069269967207178373559014835978161L),
         static_cast<T>(0.00255461870648818292376982818026706528842L),
         static_cast<T>(-0.000750517993690428370380996157470900204524L),
      };
      // LCOV_EXCL_STOP
      T result = 0;
      T z = dz + 2;
      for(unsigned k = 1; k <= sizeof(d)/sizeof(d[0]); ++k)
      {
         result += (-d[k-1]*dz)/(z + k*z + k*k - 1);
      }
      return result;
   }

