long long minTime(vector<int>& skill, vector<int>& mana) {
        int n = skill.size(), m = mana.size();
        vector<long long> finishTime(n, 0); // finishTime[i] = when wizard i finishes current potion

        for (int j = 0; j < m; ++j) {
            finishTime[0] += 1LL * mana[j] * skill[0];

            for (int i = 1; i < n; ++i)
                finishTime[i] = max(finishTime[i], finishTime[i - 1]) + 1LL * mana[j] * skill[i];

            for (int i = n - 1; i > 0; --i)
                finishTime[i - 1] = finishTime[i] - 1LL * mana[j] * skill[i];
        }
        return finishTime[n-1];
    }

int countArrays(vector<int>& original, vector<vector<int>>& bounds) {
        int left = bounds[0][0], right = bounds[0][1];
        int result = right - left + 1;
        for (int i = 1; i < size(original); ++i) {
            const int diff = original[i] - original[i - 1];
            left = max(left + diff, bounds[i][0]);
            right = min(right + diff, bounds[i][1]);
            result = min(result, max(right - left + 1, 0));
        }
        return result;
    }

int LongestSubarrayWithDistinctEntries(const vector<int>& A) {
  // Records the most recent occurrences of each entry.
  unordered_map<int, size_t> most_recent_occurrence;
  size_t longest_dup_free_subarray_start_idx = 0, result = 0;
  for (size_t i = 0; i < size(A); ++i) {
    const auto& [inserted_entry, inserted_happen] =
        most_recent_occurrence.emplace(A[i], i);
    // Defer updating dup_idx until we see a duplicate.
    if (!inserted_happen) {
      // A[i] appeared before. Did it appear in the longest current subarray?
      if (inserted_entry->second >= longest_dup_free_subarray_start_idx) {
        result = max(result, i - longest_dup_free_subarray_start_idx);
        longest_dup_free_subarray_start_idx = inserted_entry->second + 1;
      }
      inserted_entry->second = i;
    }
  }
  return max(result, size(A) - longest_dup_free_subarray_start_idx);
}

ListNode *partition(ListNode *head, int x) {
        ListNode dummy_smaller{0};
        ListNode dummy_larger{0};
        auto smaller = &dummy_smaller;
        auto larger = &dummy_larger;

        while (head) {
            if (head->val < x) {
                smaller->next = head;
                smaller = smaller->next;
            } else {
                larger->next = head;
                larger = larger->next;
            }
            head = head->next;
        }
        smaller->next = dummy_larger.next;
        larger->next = nullptr;

        return dummy_smaller.next;
    }

