TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (!root || root == p || root == q) {
            return root;
        }
        TreeNode *left = lowestCommonAncestor(root->left, p, q);
        TreeNode *right = lowestCommonAncestor(root->right, p, q);
         // 1. If the current subtree contains both p and q,
         //    return their LCA.
         // 2. If only one of them is in that subtree,
         //    return that one of them.
         // 3. If neither of them is in that subtree,
         //    return the node of that subtree.
        return left ? (right ? root : left) : right;
    }

int divide(int dividend, int divisor)
  {
    /** a/b = e^(ln(a))/e^(ln(b)) = e^(ln(a)-ln(b)) **/
    if (dividend == 0)
      return 0;
    if (divisor == 0)
      return INT_MAX;

    double t1 = log(fabs(dividend));
    double t2 = log(fabs(divisor));

    long long result = double(exp(t1 - t2));
    if ((dividend < 0) ^ (divisor < 0))
      result = -result;
    if (result > INT_MAX)
      result = INT_MAX;
    return result;
  }

std::vector<int> FixSampleIndices(const BinMapper* bin_mapper,
                                  int num_total_samples, int num_indices,
                                  const int* sample_indices,
                                  const double* sample_values) {
  std::vector<int> ret;
  if (bin_mapper->GetDefaultBin() == bin_mapper->GetMostFreqBin()) {
    return ret;
  }
  int i = 0, j = 0;
  while (i < num_total_samples) {
    if (j < num_indices && sample_indices[j] < i) {
      ++j;
    } else if (j < num_indices && sample_indices[j] == i) {
      if (bin_mapper->ValueToBin(sample_values[j]) !=
          bin_mapper->GetMostFreqBin()) {
        ret.push_back(i);
      }
      ++i;
    } else {
      ret.push_back(i++);
    }
  }
  return ret;
}

