int numSubarraysWithSum(vector<int>& A, int S) {

        int i_low = 0, i_high = 0;
        int sum_low = 0, sum_high = 0;
        int res = 0;
        for(int j = 0; j < A.size(); j ++){
            sum_low += A[j];
            while(sum_low > S)
                sum_low -= A[i_low ++];

            sum_high += A[j];
            while((sum_high > S || (sum_high == S && A[i_high] == 0)) && i_high < j)
                sum_high -= A[i_high ++];

            if(sum_low == S)
                res += (i_high - i_low + 1);
        }
        return res;
    }

