auto zip_repeat(const ContainerIn1& xs, const ContainerIn2& ys)
{
    auto nx = xs.size();
    auto ny = ys.size();
    auto qx = ny / nx + (ny % nx ? 1 : 0);
    auto qy = nx / ny + (nx % ny ? 1 : 0);
    return zip(qx > 1 ? repeat(qx, xs) : xs,
        qy > 1 ? repeat(qy, ys) : ys);
}

void go(const string& s, int len, vector<vector<int>>& dp){

        for(int i = 0; i < len; i ++) dp[i][i] = 1;
        for(int i = 0; i + 1 < len; i ++)
            dp[i][i + 1] = (s[i] == s[i + 1] ? 2 : 1);

        for(int l = 3; l <= len; l ++)
            for(int i = 0; i + l <= len; i ++){
                dp[i][i + l - 1] = max(dp[i + 1][i + l - 1], dp[i][i + l - 2]);
                if(s[i] == s[i + l - 1])
                    dp[i][i + l - 1] = max(dp[i][i + l - 1], 2 + dp[i + 1][i + l - 2]);
            }
    }

