ListNode* sortList(ListNode* head) {
      if(head==NULL || head->next==NULL) return head;

      auto temp = head, slow = head, fast = head;
      while(fast && fast->next){
        temp = slow;
        slow = slow->next;
        fast = fast->next->next;
      }

      temp->next = NULL;
      auto left = sortList(head);
      auto right = sortList(slow);

      return merge(left,right);

    }

vector<int> pathInZigZagTree(int label) {

        if(label == 1) return {1};

        vector<int> power2 = {1};
        int e = 1;
        for(int i = 1; power2.back() < label; i ++)
            e *= 2, power2.push_back(power2.back() + e);

        vector<int> res = {label};
        bool rev = true;
        for(int level = power2.size() - 2; res.back() != 1; level --){
            label /= 2;
            if(level && rev)
                res.push_back(power2[level - 1] + 1 + power2[level] - label);
            else
                res.push_back(label);
            rev = !rev;
        }

        reverse(res.begin(), res.end());
        return res;
    }

