int solve(vector<int>& nums, int l, int r, int target) {
        if(l > r)
            return -1;

        int mid = l + (r-l)/2;

        if(nums[mid] == target)
            return mid;
        else if(nums[mid] < target)
            return solve(nums, mid+1, r, target);
        else
            return solve(nums, l, mid-1, target);
    }

void merge(vector<int>& arr, int l, int mid, int r,
               vector<int>& indexes, vector<int>& aux, vector<int>& res){

        for(int i = l; i <= r; i ++)
            aux[i] = arr[i];

        vector<int> new_indexes(r - l + 1);
        int i = l, j = mid + 1;
        for(int k = l; k <= r; k ++)
            if(i > mid)
                arr[k] = aux[j], new_indexes[k - l] = indexes[j], j ++;
            else if(j > r)
                arr[k] = aux[i], new_indexes[k - l] = indexes[i], res[indexes[i]] += j - mid - 1, i ++;
            else if(aux[i] <= aux[j])
                arr[k] = aux[i], new_indexes[k - l] = indexes[i], res[indexes[i]] += j - mid - 1, i ++;
            else
                arr[k] = aux[j], new_indexes[k - l] = indexes[j], j ++;

        for(int k = l; k <= r; k ++)
            indexes[k] = new_indexes[k - l];
    }

bool dfs(int a[], int j, int k, int n, int vis[], int t, int c)
{
  if (c > t)
    return false;
  if (j == k)
    return true;
  if (c == t)
  {
    return dfs(a, j + 1, k, n, vis, t, 0);
  }

  for (int l = 0; l < n; ++l)
  {
    if (!vis[l])
    {
      vis[l] = 1;
      if (dfs(a, j, k, n, vis, t, c + a[l]))
        return true;
      vis[l] = 0;
    }
  }
  return false;
}

