ull divsum(ull to, ull c, ull k, ull m) {
    ull res = k / m * sumsq(to) + c / m * to;
    k %= m; c %= m;
    if (!k) return res;
    ull to2 = (to * k + c) / m;
    return res + (to - 1) * to2 - divsum(to2, m-1 - c, m, k);
}

const NodePtr* FindNode(const NodePtr* tree, Key& val) {
  std::stack<const NodePtr*> s{{tree}};

  while (!s.empty()) {
    auto node = s.top();
    s.pop();

    if (!*node) {
      continue;
    }

    if ((*node)->data == val) {
      return node;
    }

    s.push(&((*node)->left));
    s.push(&((*node)->right));
  }

  return nullptr;
}

long long minimumTotalDistance(vector<int>& robot, vector<vector<int>>& factory) {
        static const int64_t INF = numeric_limits<int64_t>::max();
        sort(begin(robot), end(robot));
        sort(begin(factory), end(factory));
        vector<int64_t> dp(size(robot) + 1, INF);  // dp[j] at i: min of factory[:i+1] and robot[:j]
        dp[0] = 0;
        for (int i = 0; i < size(factory); ++i) {
            for (int j = size(robot); j >= 1; --j) {
                int64_t curr = 0;
                for (int k = 0; k <= min(factory[i][1], j); ++k) {
                    dp[j] = min(dp[j], dp[j - k] != INF ? dp[j - k] + curr : INF);
                    if ((j - 1) - k >= 0) {
                        curr += abs(robot[(j - 1) - k] - factory[i][0]);
                    }
                }
            }
        }
        return dp.back();
    }

int furthestBuilding(vector<int>& heights, int bricks, int ladders) {

        int res = 0;
        priority_queue<int, vector<int>, greater<int>> pq;
        for(int i = 1; i < heights.size(); i ++)
            if(heights[i] > heights[i - 1]){
                int a = heights[i] - heights[i - 1];
                pq.push(a);
                if(pq.size() > ladders){
                    int x = pq.top(); pq.pop();
                    if(x > bricks) return i - 1;
                    bricks -= x;
                }
            }
        return heights.size() - 1;
    }

