int solve(int n, const vector<int>& nums, int maxv){

        vector<int> dp(maxv + 1), premin(maxv + 1);
        for(int v = 0; v <= maxv; v ++){
            dp[v] = abs(nums[0] - v);
            if(v) premin[v] = min(premin[v - 1], dp[v]);
            else premin[v] = dp[v];
        }

        for(int i = 1; i < n; i ++){
            vector<int> tdp(maxv + 1);
            for(int v = 0; v <= maxv; v ++)
                tdp[v] = premin[v] + abs(nums[i] - v);

            premin[0] = tdp[0];
            for(int v = 1; v <= maxv; v ++) premin[v] = min(premin[v - 1], tdp[v]);
            dp = tdp;
        }
        return *min_element(dp.begin(), dp.end());
    }

Integer ModularRoot(const Integer &a, const Integer &e,
                    const Integer &p, const Integer &q)
{
    Integer dp = EuclideanMultiplicativeInverse(e, p-1);
    Integer dq = EuclideanMultiplicativeInverse(e, q-1);
