            return false;

        unordered_map<char, char> match, rmatch;
        for(int i = 0; i < word.size(); i ++)
            if(match.find(word[i]) == match.end()){
                if(rmatch.find(pattern[i]) != rmatch.end())
                    return false;

                match[word[i]] = pattern[i];
                rmatch[pattern[i]] = word[i];
