int removeDuplicates(vector<int> &nums)
  {
    if (nums.size() == 0)
      return 0;
    int ans = 1, i = 0, j = 0;
    while (i < nums.size() && j < nums.size())
    {
      int curr = nums[i];
      while (j < nums.size() && nums[j] == curr)
        j++;
      if (j >= nums.size())
        break;
      i++;
      ans++;
      curr = nums[j];
      swap(nums[i], nums[j]);
      j++;
    }

    return ans;
  }

