    bool to_swap = 0;
    if (x > y) {
      to_swap ^= 1;
      swap(x, y);
    }
    while (x > 1 && y % x == 0) {
      y /= x;
      if (x > y) {
        to_swap ^= 1;
        swap(x, y);
      }
    }
    if (to_swap) swap(x, y);
  }

