int countOperations(int num1, int num2) {
        int count = 0;

        while (num1 > 0 && num2 > 0) {
            count += num1 / num2;
            num1 %= num2;

            // swap num1 and num2
            int temp = num1;
            num1 = num2;
            num2 = temp;
        }

        return count;
    }

int longestCommonSubsequence(string text1, string text2) {
        int m = text1.length();
        int n = text2.length();

        vector<vector<int>> t(m+1, vector<int>(n+1));

        for(int i = 0; i<m+1; i++) {
            for(int j = 0; j<n+1; j++) {
                if(i == 0 || j == 0)
                    t[i][j] = 0;
                else if(text1[i-1] == text2[j-1])
                    t[i][j] = 1 + t[i-1][j-1];
                else
                    t[i][j] = max(t[i][j-1], t[i-1][j]);
            }
        }

        return t[m][n];
    }

static void swap(int arr[], int i, int j) {
