bool threeConsecutiveOdds(vector<int>& arr) {
        //Approach-2
        int n = arr.size();
        int oddCount = 0;

        for(int i = 0; i < n; i++) {
            if(arr[i] % 2 == 1) {
                oddCount++;
            } else {
                oddCount = 0;
            }

            if(oddCount == 3)
                return true;
        }
        return false;
    }

