using namespace std;
int seriesSumUtil(int k,int n,int prevSum,int multi,int add) {
    if(k==n+1) {
        return prevSum ;
    }
    multi=multi*k;
    add=add+k;
    prevSum=prevSum+multi-add;
    return seriesSumUtil(k+1,n,prevSum,multi,add);
}
int seriesSum(int n) {
    if(n==1)return 0;
    int prevSum=0;
    int multi=1;
    int add=1;
    return seriesSumUtil(2,n,prevSum,multi,add);
}

