long long polynomialRollingHash(string const&str) {
    int p=31;
    int m=1e9+9;
    long long power_of_p=1;
    long long hash_val=0;
    for(int i=0;i<str.length();i ++) {
        hash_val =(hash_val +(str[i]- ' a '+1)* power_of_p)% m;
        power_of_p =(power_of_p*p)% m ;
    }
    return(hash_val%m+m)% m;
}

bool canDivideIntoSubsequences(vector<int>& nums, int K) {

        int count = 0;
        for(int start = 0, i = start + 1; i <= nums.size(); i ++)
            if(i == nums.size() || nums[i] != nums[start]){
                count = max(count, i - start);
                start = i;
                i = start;
            }

        return nums.size() >= K * count;
    }

