bool fill(vector<vector<int>> *grid, int i, int j) {
        static vector<pair<int, int>> directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        if (i < 0 || j < 0 ||
            i >= grid->size() || j >= (*grid)[i].size() ||
            (*grid)[i][j]) {
            return false;
        }
        (*grid)[i][j] = 1;
        for (const auto& [dx, dy] : directions) {
            fill(grid, i + dx, j + dy);
        }
        return true;
    }

bool isLongPressedName(string name, string typed) {

        if (name[0] != typed[0])
            return false;

        int j = 1;
        for (int i = 1; i < name.size();)
            if (typed[j] == name[i])
                j++, i++;
            else if (typed[j] == name[i - 1])
                j++;
            else
                return false;
        return true;
    }

