int solve(const string& s, int k, int l, int r, const vector<vector<int>>& presum){

        if(l > r || r - l + 1 < k) return 0;

        int breakchar = -1;
        for(int c = 0; c < 26; c ++)
            if((presum[c][r + 1] - presum[c][l]) && presum[c][r + 1] - presum[c][l] < k){
                breakchar = c;
                break;
            }

        if(breakchar == -1) return r - l + 1;

        int pos = -1;
        for(int i = l; i <= r; i ++)
            if(s[i] == 'a' + breakchar){
                pos = i;
                break;
            }
        return max(solve(s, k, l, pos - 1, presum), solve(s, k, pos + 1, r, presum));
    }

long long SwapBits(long long x, int i, int j) {
  // Extract the i-th and j-th bits, and see if they differ.
  if (((x >> i) & 1) != ((x >> j) & 1)) {
    // i-th and j-th bits differ. We will swap them by flipping their values.
    // Select the bits to flip with bit_mask. Since x^1 = 0 when x = 1 and 1
    // when x = 0, we can perform the flip XOR.
    unsigned long long bit_mask = (1ULL << i) | (1ULL << j);
    x ^= bit_mask;
  }
  return x;
}

long long distributeCandies(int n, int limit) {
        int64_t result = 0;
        for (int i = 0; i <= min(limit, n); ++i) {
            for (int j = 0; j <= min(limit, n - i); ++j) {
                if (n - i - j <= limit) {
                    ++result;
                }
            }
        }
