int ways(int i, string s, vector<int> &memo)
  {
    if (memo[i] > -1)
      return memo[i];
    int n = s.size();
    if (i == n)
      return memo[i] = 1;
    if (s[i] == '0')
      return memo[i] = 0;
    int ans = ways(i + 1, s, memo);
    if (i < n - 1 && (s[i] == '1' || (s[i] == '2' && s[i + 1] < '7')))
      ans += ways(i + 2, s, memo);
    return memo[i] = ans;
  }

