string reverseWords(string &str) {
        string result = "";
        int n = str.length();
        int i = n-1;
        int j = n-1;
        while(i >= 0) {
            if(str[i] == ' ') {
                result += str.substr(i+1, j-i) + " ";
                j = i-1;
            }
            i--;
        }
        result += str.substr(i+1, j-i);
        return result;
    }

int minDifference(vector<int>& nums) {
        int n = nums.size();
        int result = INT_MAX;
        if(n <= 4)
            return 0;

        partial_sort(begin(nums), begin(nums) + 4, end(nums));

        nth_element(begin(nums) + 4, begin(nums) + (n - 4), end(nums));

        sort(begin(nums) + (n - 4), end(nums)); //4th largest element will be correct

        result = min(result, nums[n-4] - nums[0]);
        result = min(result, nums[n-1] - nums[3]);
        result = min(result, nums[n-3] - nums[1]);
        result = min(result, nums[n-2] - nums[2]);

        return result;
    }

using namespace std;
int minimumCntOfFlipsRequired(string str) {
    int n=str.length();
    int zeros=0;
    for(int i=0;i<n;i ++) {
        if(str[i]== '0') {
            zeros++;
        }
    }
    if(zeros==0 zeros==n) {
        return 0 ;
    }
    int minFlips=INT_MAX;
    int currOnes=0;
    int flips;
    for(int i=0;i<n;i ++) {
        if(str[i]== '1') {
            currOnes++;
        }
        flips=currOnes +(zeros -(i+1-currOnes));
        minFlips=min(minFlips,flips);
    }
    return minFlips;
}

inline __attribute__((always_inline)) void TanH(float* A, MYINT I, MYINT J, float tanh_limit) {
    for (MYITE i = 0; i < I; i++) {
        for (MYITE j = 0; j < J; j++) {
            float x = A[i * J + j], y;

            y = tanh(x);

            A[i * J + j] = y;
        }
    }
    return;
}

TreeNode *lowestCommonAncestor(TreeNode *root, TreeNode *p, TreeNode *q)
  {
    if (!root || root == p || root == q)
      return root;

    // if they both on left call left
    if (root->val > p->val && root->val > q->val)
      return lowestCommonAncestor(root->left, p, q);

    // if they both on right call right
    if (root->val < p->val && root->val < q->val)
      return lowestCommonAncestor(root->right, p, q);

    // if one left one right, this is ans
    return root;
  }

