void AdjustScaleShlSaturate(TypeA* A, MYITE I, MYITE J, MYITE K, MYITE L, MYINT scale, MYINT saturate) {
    for (MYITE i = 0; i < I; i++) {
        for (MYITE j = 0; j < J; j++) {
            for (MYITE k = 0; k < K; k++) {
                for (MYITE l = 0; l < L; l++) {
                    TypeA a = A[i * J * K * L + j * K * L + k * L + l];
                    a = (a < saturate && a > -saturate) ? a : (a > 0 ? saturate : -saturate);
                    A[i * J * K * L + j * K * L + k * L + l] = a * scale;
                }
            }
        }
    }
    return;
}

