int countSteps(int x) {
    int c=0;
    int last=x;
    while(last) {
        int digits=countdig(last);
        digits-=1;
        int divisor=pow(10,digits);
        int first=last/divisor;
        int lastnumber=first*divisor;
        int skipped =(last-lastnumber)/ first;
        skipped+=1;
        c+=skipped;
        last=last -(first*skipped);
    }
    return c;
}

