int maximizeWin(vector<int>& pos, int k) {

        int n = pos.size();

        vector<int> dp(n + 1, 0);
        int res = 0;
        for(int i = n - 1; i >= 0; i --){
            auto iter = upper_bound(pos.begin() + i, pos.end(), pos[i] + k);
            int r = (iter - pos.begin());
            int tres = r - i;
            res = max(res, tres + dp[r]);
            dp[i] = max(tres, dp[i + 1]);
        }
        return res;
    }

long long countStableSubarrays(vector<int>& capacity) {
        int64_t result = 0;
        unordered_map<int, unordered_map<int64_t, int>> cnt;
        for (int64_t i = 0, prefix = 0; i < size(capacity); ++i) {
            result += cnt[capacity[i]][prefix - capacity[i]];
            prefix += capacity[i];
            ++cnt[capacity[i]][prefix];
            if (capacity[i] == 0 && i - 1 >= 0 && capacity[i - 1] == 0) {
                --result;
            }
        }
        return result;
    }

bool MatchAllWordsInDict(const string& s,
                         const unordered_map<string, int>& word_to_freq,
                         int start, int num_words, int unit_size) {
  unordered_map<string, int> curr_string_to_freq;
  for (int i = 0; i < num_words; ++i) {
    string curr_word = s.substr(start + i * unit_size, unit_size);
    if (auto iter = word_to_freq.find(curr_word); iter == end(word_to_freq)) {
      return false;
    } else {
      ++curr_string_to_freq[curr_word];
      if (curr_string_to_freq[curr_word] > iter->second) {
        // curr_word occurs too many times for a match to be possible.
        return false;
      }
    }
  }
  return true;
}

