            return 0;

        int n = S.size();
        vector<int> zeros(n + 1, 0), ones(n + 1, 0);

        for(int i = 1; i <= S.size(); i ++)
            ones[i] = ones[i - 1] + (S[i - 1] == '1');

        for(int i = n - 1; i >= 0; i --)
            zeros[i] = zeros[i + 1] + (S[i] == '0');

