int tour(petrolPump arr[], int n)
{
  int i = 0, j = 1;

  int curr_petrol = arr[i].petrol - arr[i].distance;

  while (i != j || curr_petrol < 0)
  {
    while (curr_petrol < 0 && i != j)
    {
      curr_petrol -= arr[i].petrol - arr[i].distance;
      i++;
      i = i % n;

      if (i == 0)
        return -1;
    }

    curr_petrol += arr[j].petrol - arr[j].distance;
    j++;
    j = j % n;
  }

  return i;
}

