vector<int> topo_sort(int k, vector<set<int>>& g){

        vector<int> indegrees(k + 1, 0);
        for(int u = 1; u <= k; u ++){
            for(int v: g[u]) indegrees[v] ++;
        }

        queue<int> q;
        for(int u = 1; u <= k; u ++)
            if(indegrees[u] == 0) q.push(u);

        vector<int> res;
        while(!q.empty()){
            int u = q.front(); q.pop();
            res.push_back(u);

            for(int v: g[u]){
                indegrees[v] --;
                if(indegrees[v] == 0) q.push(v);
            }
        }
        return res;
    }

