        for(int& e: hours)
            e = (e > 8 ? 1 : -1);

        int n = hours.size();
        vector<int> presum(n + 1, 0);
        for(int i = 1; i <= n; i ++)
            presum[i] = presum[i - 1] + hours[i - 1];

        unordered_map<int, int> pos;
        int res = 0;
        for(int i = 1; i <= n; i ++)
            if(presum[i] > 0) res = max(res, i);
            else{
                if(!pos.count(presum[i])) pos[presum[i]] = i;
                if(pos.count(presum[i] - 1)) res = max(res, i - pos[presum[i] - 1]);
            }
        return res;
    }

