int trap(vector<int>& height) {

        if(height.size() <= 2)
            return 0;

        vector<int> stack;
        int res = 0;
        for(int i = 0; i < height.size(); i ++){
            while(!stack.empty() && height[i] > height[stack.back()]){
                int cur = stack.back();
                stack.pop_back();
                if(stack.empty())
                    break;

                int dis = i - stack.back() - 1;
                int h = min(height[stack.back()], height[i]) - height[cur];
                res += h * dis;
            }
            stack.push_back(i);
        }
        return res;
    }

