string minInteger(string num, int k) {
        unordered_map<int, vector<int>> lookup;
        BIT bit(num.length() + 1);
        for (int i = num.length() - 1; i >= 0; --i) {
            lookup[num[i] - '0'].emplace_back(i + 1);
            bit.add(i + 1, 1);
        }
        string result;
        for (int i = 0; i < num.length(); ++i) {
            for (int d = 0; d <= 9; ++d) {
                if (!lookup[d].empty() && bit.sum(lookup[d].back() - 1) <= k) {
                    k -= bit.sum(lookup[d].back() - 1);
                    bit.add(lookup[d].back(), -1);
                    lookup[d].pop_back();
                    result.push_back('0' + d);
                    break;
                }
            }
        }
        return result;
    }

int atMostNGivenDigitSet(const string& dset, int N, int d){

        int dnum = to_string(N).size();
        if(dnum < d)
            return 0;
        if(dnum == 1){
            int res = 0;
            for(char c: dset)
                if(c - '0' <= N)
                    res ++;
            return res;
        }

        int res = 0;
        char leftmost = to_string(N)[0];
        for(int i = 0; i < dset.size(); i ++)
            if(dset[i] < leftmost)
                res += (int)pow(dset.size(), dnum - 1);
            else if(dset[i] == leftmost)
                res += atMostNGivenDigitSet(dset, N - (leftmost - '0') * pow(10, dnum - 1), dnum - 1);
            else
                break;

        return res;
    }

