void deal(unordered_map<int, int>& table, const vector<int>& nums, int state){

        vector<int> v;
        int index = 0, x = state;
        while(x){
            if(x & 1) v.push_back(nums[index]);
            index ++;
            x >>= 1;
        }

        sort(v.begin(), v.end());
        for(int i = 1; i < v.size(); i ++)
            if(v[i - 1] == v[i]) return;

        table[state] = v.back() - v[0];
    }

