int deleteString(string s) {

        int n = s.size();

        vector<vector<int>> lcs(n + 1, vector<int>(n + 1, 0));
        for(int i = n - 1; i >= 0; i --)
            for(int j = n - 1; j >= 0; j --)
                if(s[i] == s[j]) lcs[i][j] = 1 + lcs[i + 1][j + 1];

        vector<int> dp(n + 1, 0);
        dp[n - 1] = 1;
        for(int start = n - 2; start >= 0; start --){
            int len = n - start, tres = 1;
            for(int i = 1; i <= len / 2; i ++)
                if(lcs[start][start + i] >= i)
                    tres = max(tres, 1 + dp[start + i]);
            dp[start] = tres;
        }
        return dp[0];
    }

double maxAverageRatio(vector<vector<int>>& classes, int extraStudents) {

        priority_queue<pair<double, int>> pq;
        for(int i = 0; i < classes.size(); i ++)
            pq.push({(double)(classes[i][0] + 1) / (classes[i][1] + 1) - (double)classes[i][0] / classes[i][1], i});

        while(extraStudents){
            int i = pq.top().second;
            pq.pop();

            classes[i][0] ++;
            classes[i][1] ++;
            pq.push({(double)(classes[i][0] + 1) / (classes[i][1] + 1) - (double)classes[i][0] / classes[i][1], i});
            extraStudents --;
        }

        double sum = 0.0;
        for(const vector<int>& data: classes)
            sum += (double)data[0] / data[1];
        return sum / classes.size();
    }

