int longestCycle(vector<int>& g) {

        int n = g.size();
        UF uf(n);

        int res = -1;
        for(int i = 0; i < n; i ++){

            if(g[i] == -1) continue;

            if(!uf.is_connected(i, g[i])){
                uf.union_elements(i, g[i]);
                continue;
            }

            int tres = 1, cur = g[i];
            while(cur != i){
                tres ++;
                cur = g[cur];
            }
            res = max(res, tres);
        }
        return res;
    }

int minAbsoluteSumDiff(vector<int>& nums1, vector<int>& nums2) {

        long long sum = 0ll;
        for(int i = 0; i < nums1.size(); i ++)
            sum += (long long)abs(nums1[i] - nums2[i]);

        vector<int> v = nums1;
        sort(v.begin(), v.end());

        long long res = sum;
        for(int i = 0; i < nums1.size(); i ++){

            vector<int>::iterator iter = lower_bound(v.begin(), v.end(), nums2[i]);
            if(iter != v.end())
                res = min(res, sum - (long long)abs(nums1[i] - nums2[i]) + (long long)abs(*iter - nums2[i]));

            if(iter != v.begin()){
                iter --;
                res = min(res, sum - (long long)abs(nums1[i] - nums2[i]) + (long long)abs(*iter - nums2[i]));
            }
        }

        return res % (long long)(1e9 + 7);
    }

