int inverse(int x, int n){
    int t=0;
    int r=n;
    int newt=1;
    int newr=x;
    while(newr!=0){
        int quot=r/newr;
        int tmp=newt;
        newt=t-quot*newt;
        t=tmp;
        tmp=newr;
        newr=r-quot*newr;
        r=tmp;
    }
    if(r>1){
        return -1;
    }
    if(t<0){
        t+=n;
    }
    return t;
}

