long long countQuadruplets(vector<int>& nums) {
        vector<vector<int64_t>> left(size(nums), vector<int64_t>(size(nums) + 1));
        for (int j = 0; j < size(nums); ++j) {
            for (int i = 0; i < j; ++i) {
                left[j][i + 1] = left[j][i] + static_cast<int64_t>(nums[i] < nums[j]);
            }
        }
        vector<vector<int64_t>> right(size(nums), vector<int64_t>(size(nums) + 1));
        for (int j = 0; j < size(nums); ++j) {
            for (int i = size(nums) - 1; i > j; --i) {
                right[j][i] = right[j][i + 1] + static_cast<int64_t>(nums[i] > nums[j]);
            }
        }
        int64_t result = 0;
        for (int k = 0; k < size(nums); ++k) {
            for (int j = 0; j < k; ++j) {
                if (nums[k] < nums[j]) {
                    result += left[k][j] * right[j][k + 1];
                }
            }
        }
        return result;
    }

int maximumSum(vector<int>& arr) {

        int n = arr.size();
        if(n == 1) return arr[0];

        vector<int> dp1(n, 0);
        dp1[0] = arr[0];
        for(int i = 1; i < n; i ++)
            if(dp1[i - 1] <= 0) dp1[i] = arr[i];
            else dp1[i] = arr[i] + dp1[i - 1];

        int res = *max_element(dp1.begin(), dp1.end());
        vector<int> dp2(n, 0);
        dp2[n - 1] = arr[n - 1];
        for(int i = n - 2; i >= 0; i --) {
            if (dp2[i + 1] <= 0) dp2[i] = arr[i];
            else dp2[i] = arr[i] + dp2[i + 1];

            if(i - 1 >= 0)
                res = max(res, dp2[i + 1] + dp1[i - 1]);
        }

        return res;
    }

int maxProfit(vector<int> &prices, int fee)
  {
    if (prices.size() <= 1)
      return 0;
    vector<vector<int>> dp(2, vector<int>(prices.size(), 0));
    dp[0][0] = 0;
    dp[1][0] = -prices[0] - fee;
    for (int i = 1; i < prices.size(); ++i)
    {
      dp[0][i] = max(dp[0][i - 1], dp[1][i - 1] + prices[i]);
      dp[1][i] = max(dp[1][i - 1], dp[0][i - 1] - prices[i] - fee);
    }
    return dp[0][prices.size() - 1];
  }

