char nextGreatestAlphabet(vector<char >&alphabets,char K) {
    int n=alphabets.size();
    if(K>=alphabets[n-1]) return alphabets[0];
    int l=0,r=alphabets.size()-1;
    int ans=-1;
    while(l<=r) {
        int mid =(l+r)/ 2;
        if(alphabets[mid]> K) {
            r=mid-1;
            ans=mid ;
        }
        else l=mid+1 ;
    }
    return alphabets[ans];
}

