int MinimumLengthSubstring(string S,int N) {
    int ans=N;
    S="0"+S+"0";
    for(char c=' a ';c<=' z ';++ c) {
        int prev=0;
        int max_len=0;
        S[0]= c;
        S[N+1]= c;
        for(int i=1;i<=N+1;++ i) {
            if(S[i]== c) {
                int len=i-prev;
                max_len=max(max_len,len);
                prev=i ;
            }
        }
        ans=min(ans,max_len);
    }
    return ans;
}

