int solve(vector<vector<int>>& g){

        int R = g.size(), C = g[0].size();
        vector<vector<int>> dp(R, vector<int>(C, 0));

        int res = 0;
        for(int i = R - 2; i >= 0; i --)
            for(int j = 1; j + 1 < C; j ++){
                if(g[i][j] && g[i + 1][j - 1] && g[i + 1][j] && g[i + 1][j + 1])
                    dp[i][j] = 1 + min(min(dp[i + 1][j - 1], dp[i + 1][j]), dp[i + 1][j + 1]);
                res += dp[i][j];
            }
        return res;
    }

