void dfs(TreeNode* node, vector<int>& tres, int tsum,
             int sum, vector<vector<int>>& res){

        tres.push_back(node->val);
        tsum += node->val;

        if(!node->left && !node->right){
            if(tsum == sum)
                res.push_back(tres);
        }
        else {
            if (node->left)
                dfs(node->left, tres, tsum, sum, res);

            if (node->right)
                dfs(node->right, tres, tsum, sum, res);
        }

        tres.pop_back();
        return;
    }

int maxOnes (vector<vector <int>> &Mat, int M, int N) {
            int rowAns   = 0;
            int maxOnes  = -1;

            for(int row = 0; row<M; row++) {
                int low = 0, high = N-1;
                int result = -1;
                while(low <= high) {
                    int mid = low + (high-low)/2;
                    if(Mat[row][mid] == 1) {
                        result = mid;
                        high = mid-1;
                    } else {
                        low = mid+1;
                    }
                }
                if(result != -1 && N-result > maxOnes) {
                    maxOnes = N-result;
                    rowAns = row;
                }
            }

            return rowAns;

        }

