int longest_gap(int N) {
    int distance=0,count=0,first_1=-1,last_1=-1;
    while(N) {
        count ++;
        int r=N&1;
        if(r==1) {
            first_1=first_1==-1 ? count:first_1;
            last_1=count ;
        }
        N=N/2 ;
    }
    if(last_1<=first_1) {
        return -1 ;
    }
    else {
        distance =(last_1-first_1-1);
        return distance ;
    }
}

