void reverseWords(vector<char>& str) {

        vector<string> stack;
        int start = 0;
        string cur = "";
        for(int i = start; i <= str.size() ;)
            if(i == str.size() || str[i] == ' '){
                stack.push_back(cur);
                start = i + 1;
                i = start;
                cur = "";
            }
            else
                cur += str[i++];

        int index = 0;
        for(int i = stack.size() - 1; i >= 0 ; i --){
            for(int j = 0; j < stack[i].size() ; j ++)
                str[index++] = stack[i][j];
            if(i > 0)
                str[index++] = ' ';
        }
    }

