            vector<vector<vector<int>>>& dp){

        if(l >= r) return 0;
        if(dp[l][r][p] != -1) return dp[l][r][p];

        int res = dfs(s, l + 1, r, p, dp);
        if(s[l] - 'a' + 1 != p)
            for(int i = r; i > l; i --)
                if(s[i] == s[l]) res = max(res, 2 + dfs(s, l + 1, i - 1, s[l] - 'a' + 1, dp));
        return dp[l][r][p] = res;
    }

