int minJump(vector<int>& jump) {

        int n = jump.size();
        vector<int> dp(n, 1);
        for(int i = n - 2; i >= 0; i --){

            if(i + jump[i] < n) dp[i] = dp[i + jump[i]] + 1;

            for(int j = i + 1; j < n; j ++)
                if(1 + dp[i] <= dp[j]) dp[j] = 1 + dp[i];
                else break;
        }
        return dp[0];
    }

