    {
        if (!root)
            return {0, 0};

        auto left = dfs(root->left, ans);
        auto right = dfs(root->right, ans);

        double sum = left.first + right.first + root->val;
        double count = left.second + right.second + 1;
        ans = max(ans, sum / count);

        return {sum, count};
