int distinctSubstring(string&P,string&Q,int K,int N) {
    unordered_set<string>S;
    for(int i=0;i<N;++ i) {
        int sum=0;
        string s;
        for(int j=i;j<N;++ j) {
            int pos=P[j]- ' a ';
            sum+=Q[pos]- '0';
            s+=P[j];
            if(sum<=K) {
                S.insert(s);
            }
            else {
                break ;
            }
        }
    }
    return S.size();
}

boolean hasSameDigits(String s) {
        int n = s.length();
        StringBuilder sb = new StringBuilder(s);

        while (n > 2) {
            for (int i = 0; i < n - 1; i++) {
                int a = sb.charAt(i) - '0';
                int b = sb.charAt(i + 1) - '0';
                int sum = (a + b) % 10;
                sb.setCharAt(i, (char)(sum + '0'));
            }
            n--;
        }

        return sb.charAt(0) == sb.charAt(1);
    }

