inline __attribute__((always_inline)) void Relu4D(float* A, MYINT N, MYINT H, MYINT W, MYINT C) {
    for (MYITE n = 0; n < N; n++) {
        for (MYITE h = 0; h < H; h++) {
            for (MYITE w = 0; w < W; w++) {
                for (MYITE c = 0; c < C; c++) {
                    float a = A[n * H * W * C + h * W * C + w * C + c];
                    if (a < 0) {
                        a = 0;
                    }

                    A[n * H * W * C + h * W * C + w * C + c] = a;
                }
            }
        }
    }

    return;
}

int maximumScore(vector<int>& nums, int k) {

        int l = k - 1, r = k + 1;
        int res =nums[k], curmin = nums[k];
        while(l >= 0 || r < nums.size()){
            if(l < 0){
                curmin = min(curmin, nums[r]);
                r ++;
            }
            else if(r >= nums.size()){
                curmin = min(curmin, nums[l]);
                l --;
            }
            else if(nums[l] > nums[r]){
                curmin = min(curmin, nums[l]);
                l --;
            }
            else{
                curmin = min(curmin, nums[r]);
                r ++;
            }
            res = max(res, curmin * (r - l + 1));
        }
        return res;
    }

