string checkPro(int n,int k) {
    double exp=1.0/k;
    int KthRoot =(int)pow(n,exp);
    int product=1;
    for(int i=1;i<k+1;i ++) {
        product=product*i ;
    }
    if(product==n)return " Yes ";
    else {
        for(int j=2;j<KthRoot+1;j ++) {
            product=product *(j+k-1);
            product=product /(j-1);
            if(product==n)return " Yes " ;
        }
    }
    return " No ";
}

int dfs(vector<int> &stones, int i, int j, int sum, vector<vector<int>> &dp)
  {
    if (i == j)
      return 0;

    if (dp[i][j] != -1)
      return dp[i][j];

    // current score - next call se max kya hua hoga
    int ans = max(
        (sum - stones[i]) - dfs(stones, i + 1, j, sum - stones[i], dp),
        (sum - stones[j]) - dfs(stones, i, j - 1, sum - stones[j], dp));
    return dp[i][j] = ans;
  }

