using namespace std;
int solve(vector<int >&a) {
    int n=a.size();
    vector<int>dp(n+1,0), val(n+1,0);
    for(int i=n-1;i>=0;i --) {
        long long sum=a[i];
        int j=i;
        while(j+1<n and sum<val[j+1]) {
            j ++;
            sum+=a[j];
        }
        dp[i]=(j-i)+ dp[j+1];
        val[i]= sum ;
    }
    return dp[0];
}

int getIndex(ArrayReader &reader) {
        int left = 0, right = reader.length() - 1;
        while (left < right) {
            const auto& mid = left + (right - left) / 2;
            if (reader.compareSub(left, mid, (right - left + 1) % 2 ? mid : mid + 1, right) >= 0) {
                right = mid;
            }  else {
                left = mid + 1;
            }
        }
        return left;
    }

