int discreteLogarithm(int a,int b,int m) {
    int n =(int)sqrt(m)+ 1;
    unordered_map<int,int>value;
    for(int i=n;i>=1;-- i)value[powmod(a,i*n,m )]= i;
    for(int j=0;j<n;++ j) {
        int cur =(powmod(a,j,m)* b)% m;
        if(value[cur]) {
            int ans=value[cur]* n-j;
            if(ans<m)return ans ;
        }
    }
    return -1;
}

int longestSubarray(vector<int>& nums) {

        int res = 0, l = 0, r = -1, k = 0;
        while(l < nums.size()){
            if(k == 2 || r + 1 == nums.size()){
                k -= !nums[l ++];
            }
            else{
                if(r + 1 < nums.size())
                    k += !nums[++r];
                res = max(res, r - l + 1 - k);
            }
        }
        return res == nums.size() ? res - 1 : res;
    }

