int smaller_than(TreeNode* node, int x){

        if(!node)
            return 0;

        if(x <= node->val)
            return smaller_than(node->left, x);
        return (node->left ? node->left->sz : 0) + 1 + smaller_than(node->right, x);
    }

int dfs(const unordered_map<int, vector<int>>& G,
               int target, int t, int node, int parent) {
        if (!t || !(G.at(node).size() - int(parent != 0))) {
            return (node == target);
        }
        int result = 0;
        for (const auto& child : G.at(node)) {
            if (child == parent) {
                continue;
            }
            if (result = dfs(G, target, t - 1, child, node)) {
                break;
            }
        }
        return result * (G.at(node).size() - int(parent != 0));
    }

int longestPalindrome(string s) {
        int n = s.length();
        unordered_map<char, int> mp;

        int result = 0;
        for(char &ch : s) {
            mp[ch]++;
        }

        bool takeCentralChar = false;
        for(auto &it : mp) {
            if(it.second % 2 == 0) {
                result += it.second;
            } else {
                result += it.second - 1;
                takeCentralChar = true;
            }
        }

        if(takeCentralChar)
            result++;

        return result;
    }

int swapBits(unsigned int x, unsigned int p1, unsigned int p2, unsigned int n)
{
    /* xor contains xor of two sets */
    unsigned int xr = ((x >> p1) ^ (x >> p2)) & ((1U << n) - 1);

    /* To swap two sets, we need to again XOR the xor with original sets */
    return x ^ ((xr << p1) | (xr << p2));
}

