float calc_nearest_index(State state, Vec_f cx, Vec_f cy, Vec_f cyaw, int &ind){
  float mind = std::numeric_limits<float>::max();
  for(unsigned int i=0; i<cx.size(); i++){
    float idx = cx[i] - state.x;
    float idy = cy[i] - state.y;
    float d_e = idx*idx + idy*idy;

    if (d_e<mind){
      mind = d_e;
      ind = i;
    }
  }
  float dxl = cx[ind] - state.x;
  float dyl = cy[ind] - state.y;
  float angle = YAW_P2P(cyaw[ind] - std::atan2(dyl, dxl));
  if (angle < 0) mind = mind * -1;

  return mind;
}

TreeNode *constructBalancedBST(vector<int> &nums, int left, int right)
  {
    if (left > right)
      return NULL;

    int mid = left + (right - left) / 2;
    TreeNode *current = new TreeNode(nums[mid]);
    current->left = constructBalancedBST(nums, left, mid - 1);
    current->right = constructBalancedBST(nums, mid + 1, right);
    return current;
  }

void rotate_2_ccw(
    const FT angle_deg,
    const FT x, const FT y,
    FT& rx, FT& ry) {

    const double angle_rad = radians_2(angle_deg);
    const FT sin_val = static_cast<FT>(std::sin(angle_rad));
    const FT cos_val = static_cast<FT>(std::cos(angle_rad));

    rx = x * cos_val - y * sin_val; // rotation matrix
    ry = y * cos_val + x * sin_val;
  }

int bagOfTokensScore(vector<int> &tokens, int P)
  {
    sort(tokens.begin(), tokens.end());
    int maxScore = 0, score = 0;
    int l = 0, r = tokens.size() - 1;

    while (l <= r && P >= tokens[l])
    {
      while (l < tokens.size() && P >= tokens[l])
      {
        P -= tokens[l++];
        score++;
      }

      maxScore = max(maxScore, score);
      if (score > 0 && l <= r)
      {
        P += tokens[r--];
        score--;
      }
    }
    return maxScore;
  }

