  int max_length = 0, num_parens_so_far = 0, length = 0;
  for (IterType i = begin; i < end; ++i) {
    if (*i == paren) {
      ++num_parens_so_far, ++length;
    } else {  // *i != paren
      if (num_parens_so_far <= 0) {
        num_parens_so_far = length = 0;
      } else {
        --num_parens_so_far, ++length;
        if (num_parens_so_far == 0) {
          max_length = max(max_length, length);
        }
      }
    }
  }
  return max_length;
}

