int minimumMountainRemovals(vector<int>& nums) {

        int n = nums.size();

        vector<int> dp1(n, 1);
        for(int i = 1; i < n; i ++){
            for(int j = i - 1; j >= 0; j --)
                if(nums[i] > nums[j]) dp1[i] = max(dp1[i], 1 + dp1[j]);
        }

        vector<int> dp2(n, 1);
        for(int i = n - 2; i >= 0; i --){
            for(int j = i + 1; j < n; j ++)
                if(nums[i] > nums[j]) dp2[i] = max(dp2[i], 1 + dp2[j]);
        }

        int res = 3;
        for(int i = 0; i < n; i ++)
            if(dp1[i] > 1 && dp2[i] > 1)
                res = max(res, dp1[i] + dp2[i] - 1);
        return n - res;
    }

