ll sumProd(ll n,ll t) {
    ll dino=power(t+1,MOD-2,MOD);
    unsigned long long ans=1;
    for(ll i=n+t+1;i>n;-- i)ans =(ans%MOD*i%MOD)% MOD;
    ll tfact=1;
    for(int i=1;i<=t;++ i)tfact =(tfact*i)% MOD;
    ans=ans*dino-tfact+MOD;
    return ans%MOD;
}

