int solve(int low,int high,int T) {
    while(low<=high) {
        int mid =(low+high)/ 2;
        if(( mid *(mid+1))==T)return mid;
        if(mid>0 &&(mid *(mid+1))>T &&(mid *(mid-1))<=T)return mid-1;
