    int rightMostStart=INT_MIN;
    int leftMostEnd=INT_MAX;
    for(int i=0;i<N;i ++) {
        if(rightMostStart<intervals[i ].start)rightMostStart=intervals[i ].start;
        if(leftMostEnd>intervals[i ].end)leftMostEnd=intervals[i ].end ;
    }
    int res;
    if(rightMostStart>leftMostEnd)res=-1;
    else if(rightMostStart<=x&&x<=leftMostEnd)res=0;
