long long fixedRatio(string s, int num1, int num2) {

        int n = s.size();
        vector<int> presum1(n + 1, 0);
        for(int i = 0; i < n; i ++) presum1[i + 1] = presum1[i] + (s[i] == '1');

        long long res = 0;
        map<int, int> table;
        table[0] = 1;
        for(int i = 0; i < n; i ++){
            int t = presum1[i + 1] * num1 - (i + 1 - presum1[i + 1]) * num2;
            auto iter = table.find(t);
            if(iter != table.end()) res += iter->second;
            table[t] ++;
        }
        return res;
    }

using namespace std;
int minDistance(int n1,int n2) {
    int bitCount1=floor(log2(n1))+1;
    int bitCount2=floor(log2(n2))+1;
    int bitDiff=abs(bitCount1-bitCount2);
    int maxBitCount=max(bitCount1,bitCount2);
    if(bitCount1>bitCount2) {
        n2=n2*pow(2,bitDiff);
    }
    else {
        n1=n1*pow(2,bitDiff);
    }
    int xorValue=n1^n2;
    int bitCountXorValue;
    if(xorValue==0)bitCountXorValue=1;
    else {
        bitCountXorValue=floor(log2(xorValue))+1 ;
    }
    int disSimilarBitPosition=maxBitCount-bitCountXorValue;
    int result=bitCount1+bitCount2-2*disSimilarBitPosition;
    return result;
}

