    float* in = inPyrSignal->f - 1;
    PyrFloatArray* outc = newPyrSignal(g, inPyrSignal->size);
    float* out = outc->f - 1;
    float* endptr = out + inPyrSignal->size;
    while (out < endptr) {
        float z = *++in;
        if (z < -0.5f)
            *++out = (-z - .25f) / z;
        else if (z > 0.5f)
            *++out = (z - .25f) / z;
        else
            *++out = z;
    }
    return outc;
}

