    int maxProfit=0;
    int curr_val;
    do {
        curr_val=0;
        for(int i=0;i<N;i ++) {
            curr_val+=value[i];
            if(curr_val<=K) {
                maxProfit=max(curr_val+maxval *(i+1), maxProfit);
