void merge(vector<pair<int, int>>& arr, int l, int mid, int r,
               vector<pair<int, int>>& aux, vector<int>& res){

        for(int i = l; i <= r; i ++)
            aux[i] = arr[i];
        int i = l, j = mid + 1;
        for(int k = l; k <= r; k ++)
            if(i > mid)
                arr[k] = aux[j], j ++;
            else if(j > r)
                arr[k] = aux[i], res[aux[i].second] += j - mid - 1, i ++;
            else if(aux[i] <= aux[j])
                arr[k] = aux[i], res[aux[i].second] += j - mid - 1, i ++;
            else
                arr[k] = aux[j], j ++;
    }

