void findNthRoot(double x,int n) {
    double low,high;
    if(x>=0 and x<=1) {
        low=x;
        high=1 ;
    }
    else {
        low=1;
        high=x ;
    }
    double epsilon=0.00000001;
    double guess =(low+high)/ 2;
    while(abs(( pow(guess,n))-x)>= epsilon) {
        if(pow(guess,n)> x) {
            high=guess ;
        }
        else {
            low=guess ;
        }
        guess =(low+high)/ 2 ;
    }
    cout<<fixed<<setprecision(16)<< guess;
}

