int countTriplets(vector<int>& arr) {

        int n = arr.size();
        vector<int> pre(n + 1, 0);
        for(int i = 0; i < arr.size(); i ++)
            pre[i + 1] = pre[i] ^ arr[i];

        int res = 0;
        for(int i = 0; i < n; i ++)
            for(int j = i + 1; j < n; j ++)
                for(int k = j; k < n; k ++)
                    if(pre[j] ^ pre[i] == pre[k + 1] ^ pre[j])
                        res ++;
        return res;
    }

