void AddOrSubCir4D(float* A, const float* B, float* X, MYITE N, MYITE H, MYITE W, MYITE C, MYINT shrA, MYINT shrB, MYINT shrC, bool add) {
    for (MYITE n = 0; n < N; n++) {
        for (MYITE h = 0; h < H; h++) {
            for (MYITE w = 0; w < W; w++) {
                for (MYITE c = 0; c < C; c++) {
                    float a = A[n * H * W * C + h * W * C + w * C + c];
                    float b = B[c];

                    float res;
                    if (add) {
                        res = a + b;
                    } else {
                        res = a - b;
                    }

                    X[n * H * W * C + h * W * C + w * C + c] = res;
                }
            }
        }
    }
    return;
}

int maxProfit(vector<int> &nums)
  {
    int n = nums.size();
    if (n <= 1)
      return 0;
    vector<int> profit(n, 0);

    int max_so_far = nums[n - 1];
    for (int i = n - 2; i >= 0; --i)
    {
      max_so_far = max(max_so_far, nums[i]);
      profit[i] = max(profit[i + 1], max_so_far - nums[i]);
    }

    int min_so_far = nums[0];
    for (int i = 1; i < n; ++i)
    {
      min_so_far = min(min_so_far, nums[i]);
      profit[i] = max(profit[i - 1], profit[i] + nums[i] - min_so_far);
    }

    return profit[n - 1];
  }

