string solve(int n,char x,char y) {
    int length=ceil(log2(n+2))-1;
    int rank=n -(1<<length)+ 1;
    string left=" ",right=" ";
    for(int i=length-1;i>=0;i --) {
        int mask=1<<i;
        bool bit=mask&rank;
        if(bit) {
            left+=y;
            right+=y ;
        }
        else {
            left+=x;
            right+=x ;
        }
    }
    reverse(right.begin(),right.end());
    return left+right;
}

