using namespace std;
int Count(int N,int K) {
    if(K==0)return 0;
    int res=0;
    int low=1,high=N;
    while(low<=high) {
        int mid =(low+high)/ 2;
        int sum =(mid*mid+mid)/ 2;
        if(sum<=K) {
            res=max(res,mid);
            low=mid+1 ;
        }
        else {
            high=mid-1 ;
        }
    }
    return res;
}

