int dfs(int n, int index, int letter, vector<vector<int>>& dp){

        if(index == n) return 1;
        if(dp[index][letter] != -1) return dp[index][letter];

        int res = 0;
        for(int i = letter; i < 5; i ++)
            res += dfs(n, index + 1, i, dp);
        return dp[index][letter] = res;
    }

Matrix matrixExponentiation(const Matrix& base, int exponent) {

        if (exponent == 0) {
            Matrix identity(26, vector<int>(26, 0));
            for (int i = 0; i < 26; ++i)
                identity[i][i] = 1;
            return identity;
        }

        Matrix half   = matrixExponentiation(base, exponent / 2);
        Matrix result = matrixMultiplication(half, half);

        if (exponent % 2 == 1)
            result = matrixMultiplication(result, base);

        return result;
    }

vector<int> distinctDifferenceArray(vector<int>& nums) {

        int n = nums.size();

        vector<int> pre(n), suf(n + 1, 0);
        set<int> s;
        for(int i = 0; i < n; i ++){
            s.insert(nums[i]);
            pre[i] = s.size();
        }

        s.clear();
        for(int i = n - 1; i >= 0; i --){
            s.insert(nums[i]);
            suf[i] = s.size();
        }

        vector<int> res(n);
        for(int i = 0; i < n; i ++) res[i] = pre[i] - suf[i + 1];
        return res;
    }

