int specialArray(vector<int>& nums) {
        int n = nums.size();

        /*
            Every number larger than N is useless for our purpose,
            and we can treat those numbers as N.
        */
        vector<int> freq(n+1);

        for(int i = 0; i < n; i++) {
            freq[min(n, nums[i])]++;
        }

        int c_sum = 0;
        for(int i = n; i >= 0; i--) {
            c_sum += freq[i];
            if(i == c_sum) {
                return i;
            }
        }

        return -1;
    }

