int binomialCoeff(int x,int n,int k) {
    int sum=0,term=1;
    for(int i=1;i<=n;++ i) {
        term*=x-i+1;
        term/=i;
        sum+=term;
        if(sum>k)return sum ;
    }
    return sum ;
}
int minTrials(int n,int k) {
    int low=1,high=k;
    while(low<high) {
        int mid =(low+high)/ 2;
        if(binomialCoeff(mid,n,k)< k)low=mid+1;
        else high=mid ;
    }
    return low;
}

