int dfs(const vector<vector<int>>& g, int u, int p, const string& s,
              int& res){

        vector<int> len;
        int maxl = 1;
        for(int v: g[u]){
            if(v == p) continue;
            int l = dfs(g, v, u, s, res);
            if(s[u] != s[v]){
                len.push_back(l);
                maxl = max(maxl, 1 + l);
            }
        }

        if(len.size() == 0)
            res = max(res, 1);
        else if(len.size() == 1)
            res = max(res, len[0] + 1);
        else{
            sort(len.begin(), len.end(), greater<int>());
            res = max(res, len[0] + len[1] + 1);
        }
        return maxl;
    }

