float find_angle(int x,int y,int z) {
    int volume=x*x*y;
    float ans=0;
    if(z<volume/2) {
        float d =(x*y*y)/(2.0*z);
        ans=atan(d);
    }
    else {
        z=volume-z;
        float d =(2*z)/(float )(x*x*x);
        ans=atan(d);
    }
    ans =(ans*180)/ 3.14159265;
    return ans;
}

