int shortestWay(string source, string target) {
        vector<vector<int>> lookup(source.size() + 1, vector<int>(26, -1));
        vector<int> find_char_next_pos(26, -1);
        for (int i = source.length() - 1; i >= 0; --i) {
            find_char_next_pos[source[i] - 'a'] = i + 1;
            lookup[i] = find_char_next_pos;
        }

        int result = 1, start = 0;
        for (const auto& c : target) {
            start = lookup[start][c - 'a'];
            if (start != -1) {
                continue;
            }
            ++result;
            start = lookup[0][c - 'a'];
            if (start == -1) {
                return -1;
            }
        }
        return result;
    }

pair<int, int> traverse(TreeNode *root)
  {
    if (!root)
      return {0, 0};
    auto left = traverse(root->left);
    auto right = traverse(root->right);
    int NotRob = max(left.first + right.first, max(left.first + right.second, max(left.second + right.first, left.second + right.second)));

    return {root->val + left.second + right.second, NotRob};
  }

