using namespace std;
int largeProduct(vector<int>A,vector<int>B,int N) {
    if(N==0)return 0;
    priority_queue<int,vector<int >,greater<int>>pq;
    for(int i=0;i<N;i ++)pq.push(A[i]);
    sort(B.begin(),B.end());
    for(int i=0;i<N;i ++) {
        int minn=pq.top();
        pq.pop();
        int maximized_element=max(minn*B[i], minn+B[i]);
        pq.push(maximized_element);
    }
    int max_product=1;
    while(pq.size()>0) {
        max_product*=pq.top();
        pq.pop() ;
    }
    return max_product;
}

