vector<long long> getDistances(vector<int>& arr) {

        int n = arr.size();
        map<int, vector<int>> table;
        for(int i = 0; i < n; i ++)
            table[arr[i]].push_back(i);

        vector<long long> res(n, 0);
        for(const pair<int, vector<int>>& p: table){
            const vector<int>& v = p.second;
            long long sum = 0ll;
            for(int i = 1; i < v.size(); i ++) sum += v[i] - v[0];
            res[v[0]] = sum;

            long long x = v.size() - 1, y = 1;
            for(int i = 1; i < v.size(); i ++){
                sum -= x * (v[i] - v[i - 1]);
                sum += y * (v[i] - v[i - 1]);
                res[v[i]] = sum;
                x --; y ++;
            }
        }
        return res;
    }

void shell_sort(T *arr, size_t LEN) {
    const unsigned int gaps[] = {701, 301, 132, 57, 23, 10, 4, 1};
    const unsigned int gap_len = 8;
    size_t i, j, g;

    for (g = 0; g < gap_len; g++) {
        unsigned int gap = gaps[g];
        for (i = gap; i < LEN; i++) {
            T tmp = arr[i];

            for (j = i; j >= gap && (arr[j - gap] - tmp) > 0; j -= gap) {
                arr[j] = arr[j - gap];
            }

            arr[j] = tmp;
        }
    }
}

