long long getCount(int n,int k) {
    if(n==1)return 10;
    long long dp[n+1 ][11];
    for(int i=0;i<=n;i ++) {
        for(int j=0;j<11;j ++)dp[i ][j]= 0 ;
    }
    for(int i=1;i<=9;i ++)dp[1 ][i]= 1;
    for(int i=2;i<=n;i ++) {
        for(int j=0;j<=9;j ++) {
            int l=max(0,j-k);
            int r=min(9,j+k);
            dp[i ][l]+= dp[i-1 ][j];
            dp[i ][r+1]-= dp[i-1 ][j];
        }
        for(int j=1;j<=9;j ++)dp[i ][j]+= dp[i ][j-1];
    }
    long long count=0;
    for(int i=0;i<=9;i ++)count+=dp[n ][i];
    return count;
}

