vector<int> finalPrices(vector<int>& prices) {

        int n = prices.size();

        vector<int> res(n);
        stack<int> stack;
        for(int i = 0; i < n; i ++){
            while(!stack.empty() && prices[i] <= prices[stack.top()])
                res[stack.top()] = prices[stack.top()] - prices[i], stack.pop();
            stack.push(i);
        }
        while (!stack.empty()) res[stack.top()] = prices[stack.top()], stack.pop();
        return res;
    }

int minCostSetTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
        const auto& cost = [=](int m, int s) {
            if (!(0 <= m && m <= 99 && s <= 99)) {
                return numeric_limits<int>::max();
            }
            int result = 0, curr = startAt;
            for (const auto& x: to_string(m * 100 + s)) {
                result += (((x - '0') != curr) ? moveCost : 0) + pushCost;
                curr = x - '0';
            }
            return result;
        };
        int m = targetSeconds / 60, s = targetSeconds % 60;
        return min(cost(m, s), cost(m - 1, s + 60));
    }

