bool canJump(vector<int>& nums) {
        int n = nums.size();
        vector<bool> allowed(n, 0); // O(n) extra space
        allowed[0] = 1;
        for (int i = 0; i < n; i++) {
            if (allowed[i]) {
                for(int j = min(n-1, i+nums[i]); j >= i+1; j--) {
                    if(allowed[j]) break;
                    allowed[j] = 1;
                }
            }
        }
        return allowed[n-1];
    }

