int maxRanges(vector<vector<int>>arr,int N) {
    sort(arr.begin(),arr.end());
    int count=1;
    vector<int>prev=arr[0];
    for(int i=1;i<N;i ++) {
        vector<int>last=arr[i-1];
        vector<int>current=arr[i];
        if(last[0]== current[0]&& last[1]== current[1]&& current[1]== current[0]) continue;
        int start=max(prev[0], current[0]- 1);
        int end=max(prev[1], current[1]);
        if(end-start>0) {
            prev[0]= 1+start;
            prev[1]= end;
            count++;
        }
    }
    return count;
}

