int SearchEntryEqualToItsIndex(const vector<int>& A) {
  int left = 0, right = size(A) - 1;
  while (left <= right) {
    int mid = left + ((right - left) / 2);
    // A[mid] == mid if and only if difference == 0.
    if (int difference = A[mid] - mid; difference == 0) {
      return mid;
    } else if (difference > 0) {
      right = mid - 1;
    } else {  // difference < 0.
      left = mid + 1;
    }
  }
  return -1;
}

