bool judgeSquareSum(int c) {
        int sqrt_c = sqrt(c);
        if(sqrt_c * sqrt_c == c) return true;

        for(int a = 0; a <= sqrt(c); ++a) {
            int b_sq = c - (a*a);
            int b = sqrt(b_sq);
            if(b*b == b_sq) return true;
        }

        return false;
    }

