int findMinFibonacciNumbers(int k) {

        int a = 1, b = 1, c;
        set<int> fibs = {1};
        while(a + b <= 1e9){
            c = a + b;
            fibs.insert(c);
            a = b, b = c;
        }

        int res = 0;
        while(k){
            set<int>::iterator iter = fibs.lower_bound(k);
            if(!(iter != fibs.end() && *iter == k)) iter --;
            res ++;
            k -= *iter;
        }
        return res;
    }

bool checkPowersOfThree(int n) {
        int p = 0;

        while(pow(3, p) <= n) {
            p++;
        }

        while(n > 0) {
            if(n >= pow(3, p)) {
                n = n - pow(3, p);
            }

            if(n >= pow(3, p)) {
                return false;
            }

            p--;
        }

        return true;
    }

