inline double sc_loop(Unit* unit, double in, double hi, int loop) {
    // avoid the divide if possible
    if (in >= hi) {
        if (!loop) {
            unit->mDone = true;
            return hi;
        }
        in -= hi;
        if (in < hi)
            return in;
    } else if (in < 0.) {
        if (!loop) {
            unit->mDone = true;
            return 0.;
        }
        in += hi;
        if (in >= 0.)
            return in;
    } else
        return in;

    return in - hi * floor(in / hi);
}

vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) {
        UnionFind union_find(n);
        for (int i = threshold + 1; i <= n; ++i) {
            // https://stackoverflow.com/questions/25905118/finding-big-o-of-the-harmonic-series
            // sum of harmonic series is O(logn)
            for (int j = 2 * i; j <= n; j += i) {
                union_find.union_set(i - 1, j - 1);
            }
        }
        vector<bool> result;
        for (const auto& q : queries) {
            result.emplace_back(union_find.find_set(q[0] - 1) == union_find.find_set(q[1] - 1));
        }
        return result;
    }

int longestSubarray(vector<int>& nums, int limit) {

        SegmentTree tree(nums);
        int res = 1;
        for(int l = 0, i = 1; i < nums.size(); i ++){

            if(tree.query_max(l, i ) - tree.query_min(l, i) <= limit)
                res = max(res, i - l + 1);
            else{
                while(tree.query_max(l, i) - tree.query_min(l, i) > limit)
                    l ++;
            }
        }
        return res;
    }

using namespace std;
int maxOR(long long arr[],int n,int k,int x) {
    long long preSum[n+1], suffSum[n+1];
    long long res,pow=1;
    for(int i=0;i<k;i ++)pow*=x;
    preSum[0]= 0;
    for(int i=0;i<n;i ++)preSum[i+1]= preSum[i]| arr[i];
    suffSum[n]= 0;
    for(int i=n-1;i>=0;i --)suffSum[i]= suffSum[i+1]| arr[i];
    res=0;
    for(int i=0;i<n;i ++)res=max(res,preSum[i]|(arr[i]* pow)suffSum[i+1]);
    return res;
}

SPDLOG_CONSTEXPR_FUNC unsigned int count_digits_fallback(T n) {
    // taken from fmt: https://github.com/fmtlib/fmt/blob/8.0.1/include/fmt/format.h#L899-L912
    unsigned int count = 1;
    for (;;) {
        // Integer division is slow so do it for a group of four digits instead
        // of for every digit. The idea comes from the talk by Alexandrescu
        // "Three Optimization Tips for C++". See speed-test for a comparison.
        if (n < 10) return count;
        if (n < 100) return count + 1;
        if (n < 1000) return count + 2;
        if (n < 10000) return count + 3;
        n /= 10000u;
        count += 4;
    }
}

long long taskSchedulerII(vector<int>& tasks, int space) {

        map<int, long long> last;
        long long cur = 1;
        for(int task: tasks){
            if(!last.count(task)){
                last[task] = cur;
                cur ++;
                continue;
            }

            long long pre = last[task];
            long long next = max(pre + space + 1, cur);
            last[task] = next;
            cur = next + 1;
        }
        return cur - 1;
    }

