int minimumSquare(int a,int b) {
    long long result=0,rem=0;
    if(a<b)swap(a,b);
    while(b>0) {
        result+=a/b;
        long long rem=a%b;
        a=b;
        b=rem ;
    }
    return result;
}

int trappingWater(int arr[], int n)
{
  int ans = 0;
  vector<int> left(n, 0), right(n, 0);
  left[0] = arr[0], right[n - 1] = arr[n - 1];

  for (int i = 1; i < n; ++i)
    left[i] = max(left[i - 1], arr[i]);
  for (int i = n - 2; i >= 0; --i)
    right[i] = max(right[i + 1], arr[i]);

  for (int i = 0; i < n; ++i)
  {
    int level = min(left[i], right[i]);
    if (level > arr[i])
      ans += level - arr[i];
  }
  return ans;
}

