int findChampion(int n, vector<vector<int>>& edges) {
        vector<int> indegree(n, 0);
        for(vector<int>& edge : edges) {
            int u = edge[0];
            int v = edge[1];

            //u --> v
            indegree[v]++;
        }

        int champ = -1;
        int count = 0;
        for(int i = 0; i < n; i++) {
            if(indegree[i] == 0) { //ith node is the champion
                champ = i;
                count++;
                if(count > 1) {
                    return -1;
                }
            }
        }

        return champ;
    }

int maxScore(vector<int>& cardPoints, int k) {

        int n = cardPoints.size();

        vector<int> presum(n + 1, 0);
        for(int i = 0; i < n; i ++) presum[i + 1] = presum[i] + cardPoints[i];

        vector<int> postsum(n + 1, 0);
        for(int i = n - 1; i >= 0; i --) postsum[i] = postsum[i + 1] + cardPoints[i];

        int res = 0;
        for(int i = 0; i <= k; i ++)
            res = max(res, presum[i] + postsum[n - (k - i)]);
        return res;
    }

