        for(int i = 0, j = 0; i < n1 || j < n2;){
            if(i == n1) res.push_back(nums2[j++]);
            else if(j == n2) res.push_back(nums1[i++]);
            else if(nums1[i][0] < nums2[j][0]) res.push_back(nums1[i++]);
