int sumIndicesWithKSetBits(vector<int>& nums, int k) {
        const auto& next_popcount = [](uint32_t n) {  // reference: https://massivealgorithms.blogspot.com/2014/06/hakmem-item-175.html
            const uint32_t lowest_bit = n & -n;
            const uint32_t left_bits = n + lowest_bit;
            const uint32_t changed_bits = n ^ left_bits;
            const uint32_t right_bits = (changed_bits / lowest_bit) >> 2;
            return left_bits | right_bits;
        };

        int result = 0;
        for (int i = (1 << k) - 1; i < size(nums); i = next_popcount(i)) {
            result += nums[i];
            if (i == 0) {
                break;
            }
        }
        return result;
    }

int maxSeg5(vector<int>& pieces, int n, int Sum) {
    vector<vector<int>> t(n+1, vector<int>(Sum+1));
    for(int i = 0; i<n+1; i++) {
        for(int j = 0; j<Sum+1; j++) {
            if(i == 0 || j == 0)
                t[i][j] = 0;
        }
    }

    for(int i = 1; i<n+1; i++) {
        for(int j = 1; j<Sum+1; j++) {
            if(pieces[i-1] <= j) {
                if(pieces[i-1] == j || t[i][j-pieces[i-1]] != 0) //It checks for a valid peice (If we cut a segment, then remaining segment length should also be valid)
                    t[i][j] = max(1 + t[i][j-pieces[i-1]], t[i-1][j]);
                else
                    t[i][j] = t[i-1][j];
            } else {
                t[i][j] = t[i-1][j];
            }
        }
    }
    return t[n][Sum];
}

