long long minCost(long long arr[], long long n)
{
  priority_queue<long long, vector<long long>, greater<long long>> pq;
  long long cost = 0;

  for (int i = 0; i < n; ++i)
    pq.push(arr[i]);
  while (pq.size() > 1)
  {
    auto a = pq.top();
    pq.pop();
    auto b = pq.top();
    pq.pop();
    cost += (a + b);
    pq.push(a + b);
  }

  return cost;
}

