    while(( 1<<i)<= n) {
        bool k=0;
        int change=1<<i;
        for(int j=0;j<=n;j ++) {
            ans+=k;
            if(change==1) {
                k =!k;
                change=1<<i ;
            }
            else {
                change--;
            }
        }
        i++;
    }
    return ans ;
