        int lookup = 0;
        const auto& check = [&](int x) {
            for (; x ; x /= 10) {
                const int d = x % 10;
                if (d == 0 || lookup & (1 << d)) {
                    return false;
                }
                lookup |= 1 << d;
            }
            return true;
        };

