int kthSmallest(vector<vector<int>>& mat, int k) {

        vector<int> res = {0};
        priority_queue<int> pq;
        for(const vector<int>& row: mat){
            for(int a: res) for(int b: row){
                pq.push(a + b);
                if(pq.size() > k) pq.pop();
            }
            res.clear();
            while (!pq.empty()) res.push_back(pq.top()), pq.pop();
        }
        return res[0];
    }

