uint32_t powmod(uint32_t a, uint32_t b, uint32_t mod) {
        a %= mod;
        uint64_t result = 1;
        while (b) {
            if (b & 1) {
                result = result * a % mod;
            }
            a = uint64_t(a) * a % mod;
            b >>= 1;
        }
        return result;
    }

void permute(vector<int> nums, int i, vector<vector<int>> &ans)
  {
    if (i == nums.size() - 1)
    {
      ans.push_back(nums);
      return;
    }

    for (int it = i; it < nums.size(); ++it)
    {
      swap(nums[i], nums[it]);
      permute(nums, i + 1, ans);
      swap(nums[i], nums[it]);
    }
  }

