int minIncrementForUnique(vector<int>& A) {
        sort(A.begin(), A.end());
        A.emplace_back(numeric_limits<int>::max());
        int result = 0, duplicate = 0;
        for (int i = 1; i < A.size(); ++i) {
            if (A[i - 1] == A[i]) {
                ++duplicate;
                result -= A[i];
            } else {
                int move = min(duplicate, A[i] - A[i - 1] - 1);
                duplicate -= move;
                result += move * A[i - 1] + move * (move + 1) / 2;
            }
        }
        return result;
    }

int SquareRoot(int k) {
  int left = 0, right = k;
  // Candidate interval [left, right] where everything before left has
  // square <= k, and everything after right has square > k.
  while (left <= right) {
    long long mid = left + ((right - left) / 2);
    if (long long mid_squared = mid * mid; mid_squared <= k) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return left - 1;
}

bool MatrixSearch(const vector<vector<int>>& A, int x) {
  int row = 0, col = size(A[0]) - 1;  // Start from the top-right corner.
  // Keeps searching while there are unclassified rows and columns.
  while (row < size(A) && col >= 0) {
    if (A[row][col] == x) {
      return true;
    } else if (A[row][col] < x) {
      ++row;  // Eliminate this row.
    } else {  // A[row][col] > x.
      --col;  // Eliminate this column.
    }
  }
  return false;
}

