        for(int i = n; i >= 1; i --){
            dp[i] = dp[i + 1];
            vector<int> t = {i, i, 0};
            vector<vector<int>>::iterator iter = lower_bound(rides.begin(), rides.end(), t);
            while(iter != rides.end() && (*iter)[0] == i){
                dp[i] = max(dp[i], (*iter)[1] - (*iter)[0] + (*iter)[2] + dp[(*iter)[1]]);
                iter ++;
            }
        }
        return dp[1];
    }

